INSERT INTO `estados` VALUES (1,'Borrador','Estado en el que se crea la oferta',1),(2,'Registrada','Estado al que pasa la oferta una vez confirmada la carga de datos',1),(3,'Eliminada','Estado al que pasa la oferta al ser eliminada (siempre y cuando no posea reservas en curso)',1),(4,'Publicada','Estado al que pasa la oferta al crearse las tarifas y para disponibilizarla a los turistas',1),(5,'Pausada','Estado al que pasa la oferta cuando el prestador no paga la suscripción',1),(6,'Inactiva','Estado al que pasa la oferta cuando el prestador desea no mostrarla o modificar algo (siempre y cuando no posea reservas en curso)',1),(7,'Pendiente','Estado en el que se crea la reserva de una oferta paga',2),(8,'Confirmada','Estado al que pasa la reserva cuando el turista paga la tarifa o en el que se crea si la oferta es gratis',2),(9,'Cancelada','Estado al que pasa la reserva cuando el turista desea cancelarla y esta dentro del plazo',2),(10,'En curso','Estado al que pasa la reserva cuando llega la fecha/horario de inicio de la oferta',2),(11,'Finalizada','Estado al que pasa la reserva cuando llega la fecha/horario de fin de la oferta',2),(12,'Borrador','Estado en el que se crea el establecimiento',3),(13,'Registrado','Estado al que pasa el establecimiento una vez confirmada la carga de datos',3),(14,'Eliminado','Estado al que pasa el establecimiento al ser eliminado',3),(15,'Pendiente devolución','Estado al que pasa la reserva cuando el turista cancela la reserva y hay devoluciones pendientes',2);
/*!40000 ALTER TABLE `estados` ENABLE KEYS */;
UNLOCK TABLES;

