CREATE DEFINER=`root`@`%` FUNCTION `FN_MIN_MONTO_O_TIPO_DETALLE`(
     OfertaID INT,
     FechaDesde DATE,
     FechaHasta DATE,
     returnMontoMin TINYINT
) RETURNS varchar(50) CHARSET utf8mb4
    DETERMINISTIC
BEGIN
    DECLARE minMonto DECIMAL(20,2);
    DECLARE tipoDetalle VARCHAR(50);
    
    -- Obtener el MONTO_TARIFA mínimo y el ID_TIPO_DETALLE asociado dentro del rango de fechas de vigencia
    SELECT MIN(TXO.MONTO_TARIFA), TXO.ID_TIPO_DETALLE
    INTO minMonto, tipoDetalle
    FROM TARIFAS_X_OFERTA TXO
    WHERE TXO.ID_OFERTA = OfertaID
      AND TXO.FEC_VIGENCIA_INICIO <= FechaHasta
      AND TXO.FEC_VIGENCIA_FIN >= FechaDesde
    ORDER BY TXO.MONTO_TARIFA ASC
    LIMIT 1;

    -- Retornar el valor basado en el parámetro returnMontoMin
    IF returnMontoMin = 1 THEN
        RETURN CAST(minMonto AS CHAR); -- Convertimos minMonto a cadena para el retorno
    ELSE
        RETURN tipoDetalle;
    END IF;
END ;;
DELIMITER ;
