CREATE DEFINER=`root`@`%` FUNCTION `FN_OBT_CANT_TIPO_CAMA_X_DETALLE_OFERTA`(
p_id_tipo_detalle VARCHAR(36)
) RETURNS varchar(255) CHARSET utf8mb4
    DETERMINISTIC
BEGIN
    DECLARE v_resultado VARCHAR(255) DEFAULT '';
    
    -- Selecciona el nombre de cama y la cantidad de camas concatenados
    SELECT GROUP_CONCAT(CONCAT(tc.TX_TIPO_CAMA, ': ', pxtd.CANTIDAD_CAMAS) SEPARATOR ', ') 
    INTO v_resultado
    FROM PLAZAS_X_TIPO_DETALLE pxtd
    JOIN TIPOS_CAMA tc ON pxtd.ID_TIPO_CAMA = tc.ID_TIPO_CAMA
    WHERE pxtd.ID_TIPO_DETALLE = p_id_tipo_detalle
    AND pxtd.FEC_BAJA IS NULL;  -- Solo considera los registros activos (sin baja)

    RETURN v_resultado;
END ;;
DELIMITER ;
