CREATE DEFINER=`root`@`%` FUNCTION `FN_VALIDAR_PERFILES_USUARIO`(I_ID_USUARIO VARCHAR(36)) RETURNS int
    DETERMINISTIC
BEGIN
    DECLARE V_POSEE_PERFIL INT;
    
    SELECT COUNT(*)
    INTO V_POSEE_PERFIL
    FROM PERFILES_X_USUARIO PXU
    LEFT JOIN PERFILES P ON PXU.ID_PERFIL = P.ID_PERFIL
    WHERE ID_USUARIO = I_ID_USUARIO
    AND FEC_BAJA IS NULL
    AND USR_BAJA IS NULL;
    
    RETURN V_POSEE_PERFIL;
END ;;
