CREATE DEFINER=`root`@`%` PROCEDURE `consulta_prueba`(
IN I_ID_OFERTA VARCHAR(36),
IN I_ID_TIPO_DETALLE VARCHAR(36),
IN I_FEC_INICIO DATETIME,
IN I_FEC_FIN DATETIME
)
BEGIN
	DECLARE V_COUNT_CONFLICTS INT;
		
        SELECT COUNT(*)
		INTO V_COUNT_CONFLICTS
		FROM RESERVAS R
		LEFT JOIN CAMBIOS_ESTADO_RESERVA CER ON R.ID_RESERVA = CER.ID_RESERVA
		AND CER.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_RESERVA WHERE ID_RESERVA = R.ID_RESERVA)
		WHERE R.ID_OFERTA = I_ID_OFERTA -- '32b241fa-858e-11ef-8ae1-0242ac140002'
		AND R.ID_TIPO_DETALLE = I_ID_TIPO_DETALLE  -- '5a2b63fc-858e-11ef-8ae1-0242ac140002'
		 AND (
				(I_FEC_INICIO >= R.FEC_INICIO AND I_FEC_FIN <= R.FEC_FIN) -- Caso 1: la reserva B está completamente dentro de A
				OR (I_FEC_FIN >= R.FEC_INICIO AND I_FEC_FIN <= R.FEC_FIN) -- Caso 2: la reserva B termina dentro de A
				OR (I_FEC_INICIO >= R.FEC_INICIO AND I_FEC_INICIO <= R.FEC_FIN) -- Caso 3: la reserva B empieza dentro de A
			)
		AND CER.ID_ESTADO IN (1,8, 10)         -- Reservada (ID 8) o En curso (ID 10)
		;

	SELECT V_COUNT_CONFLICTS, I_FEC_INICIO, I_FEC_FIN  FROM DUAL;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
