CREATE DEFINER=`root`@`%` PROCEDURE `obtener_todos_los_procedimientos`(IN p_schema VARCHAR(64))
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE proc_name VARCHAR(64);
    DECLARE create_stmt LONGTEXT;
    DECLARE full_sql TEXT;
    DECLARE cur CURSOR FOR
        SELECT ROUTINE_NAME
        FROM INFORMATION_SCHEMA.ROUTINES
        WHERE ROUTINE_TYPE = 'PROCEDURE'
          AND ROUTINE_SCHEMA = p_schema;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    SET full_sql = '';

    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO proc_name;
        IF done THEN
            LEAVE read_loop;
        END IF;

        SET @sql = CONCAT('SHOW CREATE PROCEDURE `', p_schema, '`.`', proc_name, '`');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;

        -- Recuperar el resultado y concatenarlo
        -- En MySQL Workbench, el resultado se muestra en una pestaña separada
        -- Por lo tanto, para obtener todo concatenado automáticamente, se recomienda copiar y pegar manualmente los resultados
    END LOOP;
    CLOSE cur;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
