CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_ACTIVIDAD`(
    IN I_ID_OFERTA_TURISTICA VARCHAR(36),
    IN I_ID_SUB_TIPO_OFERTA INT,
    IN I_ID_SUB_CATEGORIA INT,
    IN I_TX_OFERTA VARCHAR(100),
    IN I_TX_DESCRIPCION VARCHAR(2000),
    IN I_TX_REQUISITOS VARCHAR(2000),
    IN I_ID_USUARIO VARCHAR(100),
    IN I_ID_POLITICA_CANCELACION INT,
    IN I_PLAZO_DIAS_CANCELACION INT,
    IN I_ID_TIPO_PAGO_ANTICIPADO INT,
    IN I_MONTO_PAGO_ANTICIPADO INT,
    IN I_PORCENTAJE_PAGO_ANTICIPADO DECIMAL(5,2),
    IN I_ID_DIFICULTAD INT,
    IN I_DURACION_HS DECIMAL(5,2),
    IN I_DISTANCIA_KM DECIMAL(5,2),
    IN I_BL_CON_GUIA TINYINT,
    IN I_BL_ELIMINAR TINYINT
)
BEGIN
    DECLARE V_ID_OFERTA VARCHAR(36);
    DECLARE V_ID_PRESTADOR VARCHAR(36);
    DECLARE V_COUNT_OFERTAS INT;
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion, I_ID_OFERTA_TURISTICA AS id_oferta;
    END;

    -- Iniciar transacción
    START TRANSACTION;
    
    SELECT ID_PRESTADOR
    INTO V_ID_PRESTADOR
    FROM PRESTADORES
    WHERE ID_USUARIO = I_ID_USUARIO
    AND FEC_BAJA IS NULL;

	IF I_ID_OFERTA_TURISTICA IS NOT NULL AND I_BL_ELIMINAR = 0 THEN
    
        -- Modificación: Actualizar oferta turística existente
        UPDATE OFERTAS_TURISTICAS
        SET TX_OFERTA = I_TX_OFERTA,
            TX_DESCRIPCION = I_TX_DESCRIPCION,
            ID_SUB_TIPO_OFERTA = I_ID_SUB_TIPO_OFERTA,
            ID_POLITICA_CANCELACION = I_ID_POLITICA_CANCELACION,
            PLAZO_DIAS_CANCELACION = I_PLAZO_DIAS_CANCELACION,
            ID_TIPO_PAGO_ANTICIPADO = I_ID_TIPO_PAGO_ANTICIPADO,
            MONTO_PAGO_ANTICIPADO = I_MONTO_PAGO_ANTICIPADO,
            PORCENTAJE_PAGO_ANTICIPADO = I_PORCENTAJE_PAGO_ANTICIPADO,
			ID_SUB_CATEGORIA = I_ID_SUB_CATEGORIA,
			DURACION_HS = I_DURACION_HS,
            DISTANCIA_KM = I_DISTANCIA_KM,
            ID_DIFICULTAD = I_ID_DIFICULTAD,
            TX_REQUISITOS = I_TX_REQUISITOS,
            BL_CON_GUIA = I_BL_CON_GUIA
        WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA_TURISTICA
        AND FEC_BAJA IS NULL;

        SELECT 'ok' AS resultado, 'Oferta actualizada exitosamente' AS descripcion, I_ID_OFERTA_TURISTICA AS id_oferta;

    ELSEIF I_ID_OFERTA_TURISTICA IS NOT NULL AND I_BL_ELIMINAR = 1 THEN
		-- Validación: Asegurarse de que no existan reservas en curso o futuras para la oferta
		SELECT COUNT(*) INTO V_COUNT_OFERTAS
		FROM RESERVAS
		WHERE ID_OFERTA = I_ID_OFERTA_TURISTICA
		AND FEC_FIN >= CURDATE();  -- Validar que la fecha fin no sea anterior a hoy

		-- Si existen reservas activas o futuras, lanzar un mensaje de error y finalizar el bloque
		IF V_COUNT_OFERTAS > 0 THEN
			SET V_ERROR = 'No se puede eliminar la oferta porque tiene reservas activas o futuras.';
			ROLLBACK;
			SELECT 'error' AS resultado, V_ERROR AS descripcion, I_ID_OFERTA_TURISTICA AS id_oferta;
		ELSE
			-- Baja: Marcar oferta como eliminada si no hay reservas activas o futuras
			UPDATE OFERTAS_TURISTICAS
			SET FEC_BAJA = NOW(),
				USR_BAJA = I_ID_USUARIO
			WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA_TURISTICA
			AND FEC_BAJA IS NULL;
            
            INSERT INTO CAMBIOS_ESTADO_OFERTA (ID_OFERTA, ID_ESTADO, FEC_ALTA, USR_ALTA)
			VALUES (I_ID_OFERTA_TURISTICA, 3, NOW(), I_ID_USUARIO);

			SELECT 'ok' AS resultado, 'Oferta eliminada exitosamente' AS descripcion, I_ID_OFERTA_TURISTICA AS id_oferta;
		END IF;
    END IF;

    -- Confirmar transacción
    COMMIT;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
