CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_CAMAS_X_OFERTA`(
    IN I_ID_OFERTA VARCHAR(36),
    IN I_ID_TIPO_DETALLE VARCHAR(36), -- Puede ser NULL
    IN I_ID_TIPO_CAMA INT,
    IN I_CANTIDAD_CAMAS INT,
    IN I_BL_ELIMINAR TINYINT -- 1 = baja, 0 = alta/modif
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_EXISTE_PLAZAS_X_TIPO_DETALLE INT;

    -- Handler para errores
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Verificar si existe cama activa para esa oferta + tipo_detalle (posible NULL) + tipo_cama
    SELECT COUNT(*)
    INTO V_EXISTE_PLAZAS_X_TIPO_DETALLE
    FROM PLAZAS_X_TIPO_DETALLE
    WHERE ID_OFERTA = I_ID_OFERTA
      AND ID_TIPO_DETALLE <=> I_ID_TIPO_DETALLE   -- comparación segura con NULL
      AND ID_TIPO_CAMA = I_ID_TIPO_CAMA
      AND FEC_BAJA IS NULL;

    IF V_EXISTE_PLAZAS_X_TIPO_DETALLE = 0 AND I_BL_ELIMINAR = 0 THEN
        
        INSERT INTO PLAZAS_X_TIPO_DETALLE 
        (ID_OFERTA, ID_TIPO_DETALLE, ID_TIPO_CAMA, CANTIDAD_CAMAS)
        VALUES 
        (I_ID_OFERTA, I_ID_TIPO_DETALLE, I_ID_TIPO_CAMA, I_CANTIDAD_CAMAS);
        
        SELECT 'ok' AS resultado, 'Cama agregada exitosamente' AS descripcion;

    ELSEIF V_EXISTE_PLAZAS_X_TIPO_DETALLE > 0 AND I_BL_ELIMINAR = 0 THEN
        
        UPDATE PLAZAS_X_TIPO_DETALLE
        SET CANTIDAD_CAMAS = I_CANTIDAD_CAMAS
        WHERE ID_OFERTA = I_ID_OFERTA
          AND ID_TIPO_DETALLE <=> I_ID_TIPO_DETALLE
          AND ID_TIPO_CAMA = I_ID_TIPO_CAMA
          AND FEC_BAJA IS NULL;
        
        SELECT 'ok' AS resultado, 'Cama actualizada exitosamente' AS descripcion;

    ELSEIF V_EXISTE_PLAZAS_X_TIPO_DETALLE > 0 AND I_BL_ELIMINAR = 1 THEN
        
        UPDATE PLAZAS_X_TIPO_DETALLE
        SET FEC_BAJA = NOW()
        WHERE ID_OFERTA = I_ID_OFERTA
          AND ID_TIPO_DETALLE <=> I_ID_TIPO_DETALLE
          AND ID_TIPO_CAMA = I_ID_TIPO_CAMA
          AND FEC_BAJA IS NULL;
        
        SELECT 'ok' AS resultado, 'Cama eliminada exitosamente' AS descripcion;

    ELSE
        SET V_ERROR = 'Error: Parámetros incorrectos.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;

END ;;
DELIMITER ;
