CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_CARACTERISTICAS_X_TIPO_DETALLE`(
    IN I_ID_TIPO_DETALLE VARCHAR(36),
    IN I_LISTA_ID_CARACTERISTICAS VARCHAR(2000),
    IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
    DECLARE V_ID_CREADO INT DEFAULT 0;
    DECLARE V_INDEX INT DEFAULT 0;
    DECLARE V_STR_SPLIT VARCHAR(255);
    DECLARE V_DELIMITER VARCHAR(1) DEFAULT ',';

    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = COALESCE(V_ERROR, V_ERROR_SQL);
        SELECT 'error' AS resultado, V_ERROR AS descripcion, '' AS id;
    END;

    -- Verificación de parámetros obligatorios
    IF I_ID_TIPO_DETALLE IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Error: ID del tipo detalle no puede ser nulo';
    END IF;

    -- Baja de todas las características activas existentes antes de insertar las nuevas
    DELETE FROM CARACTERISTICAS_X_TIPO_DETALLE
    WHERE ID_TIPO_DETALLE = I_ID_TIPO_DETALLE;

    -- Alta de nuevas características
    IF I_LISTA_ID_CARACTERISTICAS IS NOT NULL THEN
        -- Loop para procesar cada ID de característica en la lista ingresada
        LOOP_CARACTERISTICAS: LOOP
            SET V_INDEX = V_INDEX + 1;
            SET V_STR_SPLIT = FN_SPLIT_STR(I_LISTA_ID_CARACTERISTICAS, V_DELIMITER, V_INDEX);

            IF V_STR_SPLIT = '' OR V_STR_SPLIT IS NULL THEN
                LEAVE LOOP_CARACTERISTICAS;
            END IF;

            -- Inserción de características
            INSERT INTO CARACTERISTICAS_X_TIPO_DETALLE (
                ID_TIPO_DETALLE,
                ID_CARACTERISTICA)
            VALUES (
                I_ID_TIPO_DETALLE,
                V_STR_SPLIT);

            SET V_ID_CREADO = LAST_INSERT_ID();
        END LOOP LOOP_CARACTERISTICAS;

        -- Verificación de inserciones
        IF V_ID_CREADO > 0 THEN
            SELECT 'ok' AS resultado, 'Características sobrescritas exitosamente' AS descripcion, V_ID_CREADO AS id;
        ELSE
            SELECT 'ok' AS resultado, 'No se agregaron nuevas características' AS descripcion, V_ID_CREADO AS id;
        END IF;
    ELSE
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Error: Lista de características no puede ser nula';
    END IF;

END ;;
