CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_DOMICILIO_OFERTA`(
    IN I_ID_OFERTA_TURISTICA VARCHAR(36),
    IN I_TX_CALLE VARCHAR(100),
    IN I_TX_NUMERO VARCHAR(10),
    IN I_ID_LOCALIDAD INT,
    IN I_ID_DEPARTAMENTO INT,
    IN I_ID_PROVINCIA INT,
    IN I_ID_PAIS INT,
    IN I_BL_SIN_NUMERO INT, -- Si es 1, el número será 'S/N'
    IN I_TX_LATITUD VARCHAR(50),
    IN I_TX_LONGITUD VARCHAR(50),
    IN I_BL_ELIMINAR TINYINT, -- Si es 1, se realiza una baja; si es 0, se modifica o inserta
    IN I_ID_ESTABLECIMIENTO INT
)
BEGIN
	DECLARE V_ID_DOMICILIO INT;
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_ID_DOMICILIO_ACTUAL INT;

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Verificar si la oferta ya tiene un domicilio asociado y que no esté dado de baja
    SELECT ID_DOMICILIO
    INTO V_ID_DOMICILIO_ACTUAL
    FROM OFERTAS_TURISTICAS
    WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA_TURISTICA
    AND FEC_BAJA IS NULL;

    -- Insertar o modificar el domicilio
    IF V_ID_DOMICILIO_ACTUAL IS NULL AND I_BL_ELIMINAR = 0 THEN
        -- Alta: Insertar nuevo domicilio
        IF I_ID_ESTABLECIMIENTO IS NULL THEN
			INSERT INTO DOMICILIOS (
				TX_CALLE,
				TX_ALTURA,
				ID_LOCALIDAD,
				ID_DEPARTAMENTO,
				ID_PROVINCIA,
				ID_PAIS,
				TX_LATITUD,
				TX_LONGITUD,
				FEC_ALTA
			) VALUES (
				I_TX_CALLE,
				(IF (I_BL_SIN_NUMERO = 1, 'S/N', I_TX_NUMERO)), -- Usar 'S/N' si no tiene número
				I_ID_LOCALIDAD,
				I_ID_DEPARTAMENTO,
				I_ID_PROVINCIA,
				I_ID_PAIS,
				I_TX_LATITUD,
				I_TX_LONGITUD,
				NOW()
			);
            -- Actualizar el ID_DOMICILIO en la tabla OFERTAS_TURISTICAS
			UPDATE OFERTAS_TURISTICAS
			SET ID_DOMICILIO = LAST_INSERT_ID()
			WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA_TURISTICA;
        
			SELECT 'ok' AS resultado, 'Domicilio agregado exitosamente a la oferta' AS descripcion;

		ELSEIF I_ID_ESTABLECIMIENTO IS NOT NULL
        THEN
			SELECT ID_DOMICILIO
            INTO V_ID_DOMICILIO
            FROM ESTABLECIMIENTOS
            WHERE ID_ESTABLECIMIENTO = I_ID_ESTABLECIMIENTO;
            
			INSERT INTO DOMICILIOS (
				TX_CALLE,
				TX_ALTURA,
				ID_LOCALIDAD,
				ID_DEPARTAMENTO,
				ID_PROVINCIA,
				ID_PAIS,
				TX_LATITUD,
				TX_LONGITUD,
				FEC_ALTA
			)
			SELECT 
				TX_CALLE,
				TX_ALTURA,
				ID_LOCALIDAD,
				ID_DEPARTAMENTO,
				ID_PROVINCIA,
				ID_PAIS,
				TX_LATITUD,
				TX_LONGITUD,
				NOW()
			FROM DOMICILIOS
			WHERE ID_DOMICILIO = V_ID_DOMICILIO;

            -- Actualizar el ID_DOMICILIO en la tabla OFERTAS_TURISTICAS
			UPDATE OFERTAS_TURISTICAS
			SET ID_DOMICILIO = LAST_INSERT_ID()
			WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA_TURISTICA;
            
			SELECT 'ok' AS resultado, 'Domicilio agregado exitosamente a la oferta' AS descripcion;

        END IF;
        
    ELSEIF V_ID_DOMICILIO_ACTUAL IS NOT NULL AND I_BL_ELIMINAR = 0 THEN
        -- Modificación: Actualizar domicilio existente
        IF I_ID_ESTABLECIMIENTO IS NULL THEN
			UPDATE DOMICILIOS
			SET TX_CALLE = I_TX_CALLE,
				TX_ALTURA = (IF (I_BL_SIN_NUMERO = 1, 'S/N', I_TX_NUMERO)), -- Usar 'S/N' si no tiene número
				ID_LOCALIDAD = I_ID_LOCALIDAD,
				ID_DEPARTAMENTO = I_ID_DEPARTAMENTO,
				ID_PROVINCIA = I_ID_PROVINCIA,
				ID_PAIS = I_ID_PAIS,
				TX_LATITUD = I_TX_LATITUD,
				TX_LONGITUD = I_TX_LONGITUD,
				FEC_MOD = NOW()
			WHERE ID_DOMICILIO = V_ID_DOMICILIO_ACTUAL;
        
			SELECT 'ok' AS resultado, 'Domicilio actualizado exitosamente' AS descripcion;
            
		ELSEIF I_ID_ESTABLECIMIENTO IS NOT NULL THEN
			
            SELECT ID_DOMICILIO
            INTO V_ID_DOMICILIO
            FROM ESTABLECIMIENTOS
            WHERE ID_ESTABLECIMIENTO = I_ID_ESTABLECIMIENTO;
            
			UPDATE DOMICILIOS d
			JOIN (
				SELECT 
					TX_CALLE,
					TX_ALTURA,
					ID_LOCALIDAD,
					ID_DEPARTAMENTO,
					ID_PROVINCIA,
					ID_PAIS,
					TX_LATITUD,
					TX_LONGITUD
				FROM DOMICILIOS
				WHERE ID_DOMICILIO = V_ID_DOMICILIO
			) sub ON d.ID_DOMICILIO = V_ID_DOMICILIO_ACTUAL
			SET 
				d.TX_CALLE = sub.TX_CALLE,
				d.TX_ALTURA = sub.TX_ALTURA,
				d.ID_LOCALIDAD = sub.ID_LOCALIDAD,
				d.ID_DEPARTAMENTO = sub.ID_DEPARTAMENTO,
				d.ID_PROVINCIA = sub.ID_PROVINCIA,
				d.ID_PAIS = sub.ID_PAIS,
				d.TX_LATITUD = sub.TX_LATITUD,
				d.TX_LONGITUD = sub.TX_LONGITUD,
				d.FEC_MOD = NOW();

            SELECT 'ok' AS resultado, 'Domicilio actualizado exitosamente' AS descripcion;
        END IF;
    ELSEIF V_ID_DOMICILIO_ACTUAL IS NOT NULL AND I_BL_ELIMINAR = 1 THEN
        -- Baja: Marcar domicilio como eliminado
        UPDATE DOMICILIOS
        SET FEC_BAJA = NOW()
        WHERE ID_DOMICILIO = V_ID_DOMICILIO_ACTUAL;

        -- Marcar la oferta como sin domicilio asociado (ID_DOMICILIO en NULL)
        UPDATE OFERTAS_TURISTICAS
        SET ID_DOMICILIO = NULL
        WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA_TURISTICA;
        
        SELECT 'ok' AS resultado, 'Domicilio eliminado exitosamente de la oferta' AS descripcion;

    ELSE
        -- Error: Condiciones no válidas
        SET V_ERROR = 'Error: Parámetros incorrectos o domicilio no encontrado.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_ABM_ESTABLECIMIENTOS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_ESTABLECIMIENTOS`(
    IN I_ID_ESTABLECIMIENTO INT, -- Si es NULL, se hace un Alta; si no, se realiza una Baja o Modificación
    IN I_TX_ESTABLECIMIENTO VARCHAR(100),
    IN I_TX_DESCRIPCION VARCHAR(200),
    IN I_NRO_HABILITACION VARCHAR(20),
    IN I_NRO_TELEFONO VARCHAR(45),
    IN I_TX_MAIL VARCHAR(45),
    IN I_ID_USUARIO VARCHAR(100),
    IN I_TX_CALLE VARCHAR(100),
    IN I_TX_ALTURA VARCHAR(45),
    IN I_ID_LOCALIDAD INT,
    IN I_ID_DEPARTAMENTO INT,
    IN I_ID_PROVINCIA INT,
    IN I_BL_SIN_NUMERO INT,
    IN I_TX_LATITUD VARCHAR(50),
    IN I_TX_LONGITUD VARCHAR(50),
    IN I_BL_ELIMINAR TINYINT -- Si es 1, se realiza una baja; si es 0, se inserta o modifica
)
BEGIN
    DECLARE V_ID_DOMICILIO VARCHAR(36);
    DECLARE V_COUNT_ESTABLECIMIENTOS INT;
    DECLARE V_ID_PRESTADOR VARCHAR(36);
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_OFERTAS_ACTIVAS INT;

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1
        V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion, I_ID_ESTABLECIMIENTO AS id_establecimiento;
    END;

    -- Validar que el prestador exista
    SELECT P.ID_PRESTADOR
    INTO V_ID_PRESTADOR
    FROM PRESTADORES P
    WHERE P.ID_USUARIO = I_ID_USUARIO
    LIMIT 1;

    IF V_ID_PRESTADOR IS NULL THEN
        SET V_ERROR := 'Error: El usuario proporcionado no tiene un prestador asociado.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;

    -- Si el parámetro I_BL_ELIMINAR es 1, realizar una baja (soft delete)
    IF I_BL_ELIMINAR = 1 THEN
        IF I_ID_ESTABLECIMIENTO IS NOT NULL THEN
            
            SELECT COUNT(*)
            INTO V_OFERTAS_ACTIVAS
			FROM OFERTAS_TURISTICAS
			WHERE ID_ESTABLECIMIENTO = I_ID_ESTABLECIMIENTO
			  AND FEC_BAJA IS NULL;
            
            IF V_OFERTAS_ACTIVAS > 0 THEN
				SET V_ERROR := 'Error: El establecimiento tiene ofertas activas y no puede ser eliminado.';
				SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
			ELSE
				UPDATE ESTABLECIMIENTOS
				SET FEC_BAJA = NOW(),
					USR_BAJA = I_ID_USUARIO
				WHERE ID_ESTABLECIMIENTO = I_ID_ESTABLECIMIENTO
				AND FEC_BAJA IS NULL;

				SELECT 'ok' AS resultado, 'Establecimiento eliminado exitosamente' AS descripcion, I_ID_ESTABLECIMIENTO AS id_establecimiento;
			END IF;
        ELSE
            SET V_ERROR := 'Error: Se necesita el ID del establecimiento para eliminar.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        END IF;

    -- Si el parámetro I_ID_ESTABLECIMIENTO es NULL, realizar una alta
    ELSEIF I_ID_ESTABLECIMIENTO IS NULL THEN
        -- Validar existencia del establecimiento
        SELECT COUNT(*)
        INTO V_COUNT_ESTABLECIMIENTOS
        FROM ESTABLECIMIENTOS
        WHERE TX_ESTABLECIMIENTO = TRIM(I_TX_ESTABLECIMIENTO)
        AND ID_PRESTADOR = V_ID_PRESTADOR
        AND FEC_BAJA IS NULL;

        IF V_COUNT_ESTABLECIMIENTOS = 0 THEN
            -- Insertar en la tabla DOMICILIOS
            INSERT INTO DOMICILIOS (
                ID_LOCALIDAD,
                ID_DEPARTAMENTO,
                ID_PROVINCIA,
                ID_PAIS,
                TX_CALLE,
                TX_ALTURA,
                TX_LATITUD,
                TX_LONGITUD,
                FEC_ALTA
            ) VALUES (
                I_ID_LOCALIDAD,
                I_ID_DEPARTAMENTO,
                I_ID_PROVINCIA,
                1, -- ARGENTINA
                I_TX_CALLE,
                (IF (I_BL_SIN_NUMERO = 1, 'S/N', I_TX_ALTURA)),
                I_TX_LATITUD,
                I_TX_LONGITUD,
                NOW()
            );
            SELECT LAST_INSERT_ID() INTO V_ID_DOMICILIO;

            -- Insertar en la tabla ESTABLECIMIENTOS
            INSERT INTO ESTABLECIMIENTOS (
                TX_ESTABLECIMIENTO,
                TX_DESCRIPCION,
                NRO_HABILITACION,
                NRO_TELEFONO,
                TX_MAIL,
                ID_PRESTADOR,
                FEC_ALTA,
                USR_ALTA,
                ID_DOMICILIO
            ) VALUES (
                I_TX_ESTABLECIMIENTO,
                I_TX_DESCRIPCION,
                I_NRO_HABILITACION,
                I_NRO_TELEFONO,
                I_TX_MAIL,
                V_ID_PRESTADOR,
                NOW(),
                I_ID_USUARIO,
                V_ID_DOMICILIO
            );
            SELECT LAST_INSERT_ID() INTO I_ID_ESTABLECIMIENTO;

            -- Retornar resultado exitoso
            SELECT 'ok' AS resultado, 'Establecimiento creado exitosamente' AS descripcion, I_ID_ESTABLECIMIENTO AS id_establecimiento;

        ELSE
            SET V_ERROR := 'Error: El prestador ya posee un establecimiento con el nombre ingresado.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        END IF;

    -- Si el parámetro I_ID_ESTABLECIMIENTO no es NULL y I_BL_ELIMINAR es 0, realizar una modificación
    ELSE
        UPDATE ESTABLECIMIENTOS
        SET TX_ESTABLECIMIENTO = I_TX_ESTABLECIMIENTO,
            TX_DESCRIPCION = I_TX_DESCRIPCION,
            NRO_HABILITACION = I_NRO_HABILITACION,
            NRO_TELEFONO = I_NRO_TELEFONO,
            TX_MAIL = I_TX_MAIL
        WHERE ID_ESTABLECIMIENTO = I_ID_ESTABLECIMIENTO
        AND FEC_BAJA IS NULL;

        -- Actualizar datos del domicilio
        UPDATE DOMICILIOS
        SET ID_LOCALIDAD = I_ID_LOCALIDAD,
            ID_DEPARTAMENTO = I_ID_DEPARTAMENTO,
            ID_PROVINCIA = I_ID_PROVINCIA,
            TX_CALLE = I_TX_CALLE,
            TX_ALTURA = (IF (I_BL_SIN_NUMERO = 1, 'S/N', I_TX_ALTURA)),
            TX_LATITUD = I_TX_LATITUD,
            TX_LONGITUD = I_TX_LONGITUD
        WHERE ID_DOMICILIO = (SELECT ID_DOMICILIO FROM ESTABLECIMIENTOS WHERE ID_ESTABLECIMIENTO = I_ID_ESTABLECIMIENTO);

        SELECT 'ok' AS resultado, 'Establecimiento actualizado exitosamente' AS descripcion, I_ID_ESTABLECIMIENTO AS id_establecimiento;
    END IF;
END ;;
DELIMITER ;
