CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_GUIAS_X_ACTIVIDAD`(
    IN I_ID_OFERTA VARCHAR(36),
    IN I_NRO_RESOLUCION VARCHAR(25),
    IN I_NOMBRE_APELLIDO VARCHAR(50),
    IN I_USR_ALTA VARCHAR(36),
    IN I_ID_GUIA_X_ACTIVIDAD INT, -- Si es NULL, se hace un Alta; si no, se realiza una Baja o Modificación
    IN I_BL_ELIMINAR TINYINT -- Si es 1, se realiza una baja; si es 0, se inserta o modifica
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_ID_GUIA_X_ACTIVIDAD INT;

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- ABM
    IF I_ID_GUIA_X_ACTIVIDAD IS NULL AND I_BL_ELIMINAR = 0 THEN
        -- Alta: Insertar nuevo guía
        INSERT INTO GUIAS_X_ACTIVIDAD (
            ID_OFERTA,
            NRO_RESOLUCION,
            NOMBRE_APELLIDO,
            FEC_ALTA,
            USR_ALTA
        ) VALUES (
            I_ID_OFERTA,
            I_NRO_RESOLUCION,
            I_NOMBRE_APELLIDO,
            NOW(),
            I_USR_ALTA
        );
        
        -- Obtener el ID del guía recién insertado
        SET V_ID_GUIA_X_ACTIVIDAD = LAST_INSERT_ID();
        
        SELECT 'ok' AS resultado, 'Guía agregado exitosamente a la actividad' AS descripcion, V_ID_GUIA_X_ACTIVIDAD AS id_guia;

    ELSEIF I_ID_GUIA_X_ACTIVIDAD IS NOT NULL AND I_BL_ELIMINAR = 0 THEN
        -- Modificación: Actualizar guía existente
        UPDATE GUIAS_X_ACTIVIDAD
        SET NOMBRE_APELLIDO = I_NOMBRE_APELLIDO,
            NRO_RESOLUCION = I_NRO_RESOLUCION
        WHERE ID_GUIA_X_ACTIVIDAD = I_ID_GUIA_X_ACTIVIDAD
        AND FEC_BAJA IS NULL;
        
        SELECT 'ok' AS resultado, 'Guía actualizado exitosamente' AS descripcion, I_ID_GUIA_X_ACTIVIDAD AS id_guia;

    ELSEIF I_ID_GUIA_X_ACTIVIDAD IS NOT NULL AND I_BL_ELIMINAR = 1 THEN
        -- Baja: Marcar guía como eliminado
        UPDATE GUIAS_X_ACTIVIDAD
        SET FEC_BAJA = NOW(),
            USR_BAJA = I_USR_ALTA
        WHERE ID_GUIA_X_ACTIVIDAD = I_ID_GUIA_X_ACTIVIDAD
        AND FEC_BAJA IS NULL;
        
        SELECT 'ok' AS resultado, 'Guía eliminado exitosamente de la actividad' AS descripcion;

    ELSE
        -- Error: Condiciones no válidas
        SET V_ERROR = 'Error: Parámetros incorrectos o guía no encontrado.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;
    
END ;;
DELIMITER ;
