CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_HORARIOS_CHECK`(
    IN I_ID_OFERTA VARCHAR(36),
    IN I_CHECK_IN_HORA INT,
    IN I_CHECK_IN_MINUTO INT,
    IN I_CHECK_OUT_HORA INT,
    IN I_CHECK_OUT_MINUTO INT,
    IN I_APLICA_LUNES TINYINT,
    IN I_APLICA_MARTES TINYINT,
    IN I_APLICA_MIERCOLES TINYINT,
    IN I_APLICA_JUEVES TINYINT,
    IN I_APLICA_VIERNES TINYINT,
    IN I_APLICA_SABADO TINYINT,
    IN I_APLICA_DOMINGO TINYINT,
    IN I_ID_HORARIO INT,  -- Si es NULL, se hace un Alta; si no, es una Modificación o Baja
    IN I_CUPO_MAXIMO INT, 
    IN I_CUPO_ACTUAL INT,
    IN I_BL_SIN_CUPO INT,
    IN I_BL_ELIMINAR TINYINT -- Si es 1, se realiza una Baja; si es 0, se inserta o modifica
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_ID_HORARIO INT;
    
    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Iniciar transacción
    START TRANSACTION;

    -- ABM
    IF I_ID_HORARIO IS NULL AND I_BL_ELIMINAR = 0 THEN
        -- Alta: Insertar nuevo horario
        INSERT INTO HORARIOS_CHECK(
            ID_OFERTA,
            CHECK_IN_HORA,
            CHECK_IN_MINUTO,
            CHECK_OUT_HORA,
            CHECK_OUT_MINUTO,
            APLICA_LUNES,
            APLICA_MARTES,
            APLICA_MIERCOLES,
            APLICA_JUEVES,
            APLICA_VIERNES,
            APLICA_SABADO,
            APLICA_DOMINGO,
            FEC_ALTA,
            CUPO_MAXIMO,
            CUPO_ACTUAL,
            BL_SIN_CUPO,
            FEC_MODIFICACION
            )
        VALUES (
            I_ID_OFERTA,
            I_CHECK_IN_HORA,
            I_CHECK_IN_MINUTO,
            I_CHECK_OUT_HORA,
            I_CHECK_OUT_MINUTO,
            I_APLICA_LUNES,
            I_APLICA_MARTES,
            I_APLICA_MIERCOLES,
            I_APLICA_JUEVES,
            I_APLICA_VIERNES,
            I_APLICA_SABADO,
            I_APLICA_DOMINGO,
            NOW(),
            I_CUPO_MAXIMO,
            I_CUPO_ACTUAL,
            I_BL_SIN_CUPO,
            NOW()
        );
        
        -- Obtener el ID del horario recién insertado
        SET V_ID_HORARIO = LAST_INSERT_ID();
        SELECT 'ok' AS resultado, 'Horario creado exitosamente' AS descripcion, V_ID_HORARIO AS id_horario;

    ELSEIF I_ID_HORARIO IS NOT NULL AND I_BL_ELIMINAR = 1 THEN
        -- Baja: Marcar horario como eliminado
        UPDATE HORARIOS_CHECK
        SET FEC_BAJA = NOW()
        WHERE ID_HORARIO = I_ID_HORARIO
        AND FEC_BAJA IS NULL;

        IF ROW_COUNT() = 0 THEN
            -- Error: Horario no encontrado o ya eliminado
            SET V_ERROR = 'Error: Horario no encontrado o ya eliminado.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        ELSE
            SELECT 'ok' AS resultado, 'Horario eliminado exitosamente' AS descripcion;
        END IF;

    ELSEIF I_ID_HORARIO IS NOT NULL AND I_BL_ELIMINAR = 0 THEN
        -- Modificación: Actualizar un horario existente
        UPDATE HORARIOS_CHECK
        SET 
            CHECK_IN_HORA = I_CHECK_IN_HORA,
            CHECK_IN_MINUTO = I_CHECK_IN_MINUTO,
            CHECK_OUT_HORA = I_CHECK_OUT_HORA,
            CHECK_OUT_MINUTO = I_CHECK_OUT_MINUTO,
            APLICA_LUNES = I_APLICA_LUNES,
            APLICA_MARTES = I_APLICA_MARTES,
            APLICA_MIERCOLES = I_APLICA_MIERCOLES,
            APLICA_JUEVES = I_APLICA_JUEVES,
            APLICA_VIERNES = I_APLICA_VIERNES,
            APLICA_SABADO = I_APLICA_SABADO,
            APLICA_DOMINGO = I_APLICA_DOMINGO,
            FEC_MODIFICACION = NOW(),
            CUPO_ACTUAL = I_CUPO_ACTUAL,
            CUPO_MAXIMO = I_CUPO_MAXIMO,
            BL_SIN_CUPO = I_BL_SIN_CUPO
            WHERE ID_HORARIO = I_ID_HORARIO
        AND FEC_BAJA IS NULL;

        IF ROW_COUNT() = 0 THEN
            -- Error: Horario no encontrado o ya eliminado
            SET V_ERROR = 'Error: Horario no encontrado o ya eliminado.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        ELSE
            SELECT 'ok' AS resultado, 'Horario actualizado exitosamente' AS descripcion;
        END IF;

    ELSE
        -- Error: Condiciones no válidas
        SET V_ERROR = 'Error: Parámetros incorrectos.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;

    -- Confirmar la transacción
    COMMIT;

END ;;
DELIMITER ;
