    IN I_ID_IMAGEN INT, -- Si es NULL, se hace un Alta; si no, se realiza una Baja
    IN I_BL_ELIMINAR TINYINT -- Si es 1, se realiza una baja; si es 0, se inserta
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_ID_IMAGEN INT;
    DECLARE V_TX_RUTA_ARCHIVO VARCHAR(200);
	DECLARE V_USR_ALTA VARCHAR(36);


    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Iniciar transacción
    START TRANSACTION;

    -- ABM
    IF I_ID_IMAGEN IS NULL AND I_BL_ELIMINAR = 0 THEN
    
    -- Verificar si el usuario es el creador de la oferta
		SELECT USR_ALTA INTO V_USR_ALTA
		FROM TIPOS_DETALLE
		WHERE ID_TIPO_DETALLE = I_ID_TIPO_DETALLE
		AND FEC_BAJA IS NULL;
		
        IF V_USR_ALTA != I_ID_USUARIO THEN
			SET V_ERROR = 'Error: Usuario no autorizado para modificar esta oferta.';
			SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
		END IF;
        
        -- Alta: Insertar nueva imagen
        INSERT INTO IMAGENES_X_TIPOS_DETALLE
        (TX_NOMBRE_ARCHIVO, TX_NOMBRE_UNICO, TX_RUTA_ARCHIVO, TX_TIPO_MIME, ID_TIPO_DETALLE, TAMAÑO_ARCHIVO, FEC_ALTA, USR_ALTA)
        VALUES 
        (I_TX_NOMBRE_ARCHIVO, I_TX_NOMBRE_UNICO, I_TX_RUTA_ARCHIVO, I_TX_TIPO_MIME, I_ID_TIPO_DETALLE, I_TAMAÑO_ARCHIVO, NOW(), I_ID_USUARIO);
        
        -- Obtener el ID de la imagen recién insertada
        SET V_ID_IMAGEN = LAST_INSERT_ID();
        
        SELECT 'ok' AS resultado, 'Imagen creada exitosamente' AS descripcion, V_ID_IMAGEN AS id_imagen;

    ELSEIF I_ID_IMAGEN IS NOT NULL AND I_BL_ELIMINAR = 1 THEN
        -- Baja: Marcar imagen como eliminada
        -- Obtener la ruta de la imagen antes de marcarla como baja
        SELECT TX_RUTA_ARCHIVO, USR_ALTA INTO V_TX_RUTA_ARCHIVO, V_USR_ALTA
        FROM IMAGENES_X_TIPOS_DETALLE
        WHERE ID_IMAGEN_X_TIPO_DETALLE = I_ID_IMAGEN
        AND FEC_BAJA IS NULL;
        
        IF V_TX_RUTA_ARCHIVO IS NOT NULL
        AND V_USR_ALTA = I_ID_USUARIO
        THEN
            -- Marcar la imagen como eliminada
            UPDATE IMAGENES_X_TIPOS_DETALLE
            SET FEC_BAJA = NOW(),
                USR_BAJA = I_ID_USUARIO
            WHERE ID_IMAGEN_X_TIPO_DETALLE = I_ID_IMAGEN
            AND FEC_BAJA IS NULL;
            
            SELECT 'ok' AS resultado, 'Imagen eliminada exitosamente' AS descripcion, V_TX_RUTA_ARCHIVO AS ruta_archivo;
        ELSE
            -- Error: Imagen no encontrada o ya eliminada
            SET V_ERROR = 'Error: Imagen no encontrada o ya eliminada.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        END IF;
        
    ELSE
        -- Error: Condiciones no válidas
        SET V_ERROR = 'Error: Parámetros incorrectos.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;

    -- Confirmar la transacción
    COMMIT;

END ;;
DELIMITER ;
