CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_METODOS_PAGO_X_OFERTA`(
	IN I_ID_OFERTA VARCHAR(36),
    IN I_LISTA_METODOS_PAGO VARCHAR(2000),
    IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
    DECLARE V_ID_CREADO INT DEFAULT 0;
    DECLARE V_INDEX INT DEFAULT 0;
    DECLARE V_STR_SPLIT VARCHAR(255);
    DECLARE V_DELIMITER VARCHAR(1) DEFAULT ',';

    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = COALESCE(V_ERROR, V_ERROR_SQL);
        SELECT 'error' AS resultado, V_ERROR AS descripcion, '' AS id;
    END;

    -- Verificación de parámetros obligatorios
    IF I_ID_OFERTA IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Error: ID de la oferta no puede ser nulo';
    END IF;

    -- Eliminación de todos los métodos de pago previos de la oferta
    DELETE FROM METODOS_PAGO_X_OFERTA
    WHERE ID_OFERTA = I_ID_OFERTA;

    -- Alta de nuevos métodos de pago
    IF I_LISTA_METODOS_PAGO IS NOT NULL THEN
        -- Loop para procesar cada ID de método de pago en la lista ingresada
        LOOP_METODOS_PAGO: LOOP
            SET V_INDEX = V_INDEX + 1;
            SET V_STR_SPLIT = FN_SPLIT_STR(I_LISTA_METODOS_PAGO, V_DELIMITER, V_INDEX);

            IF V_STR_SPLIT = '' OR V_STR_SPLIT IS NULL THEN
                LEAVE LOOP_METODOS_PAGO;
            END IF;

            -- Inserción de métodos de pago
            INSERT INTO METODOS_PAGO_X_OFERTA (
                ID_OFERTA,
                ID_METODO_PAGO,
                FEC_ALTA,
                USR_ALTA)
            VALUES (
                I_ID_OFERTA,
                V_STR_SPLIT, -- ID del método de pago
                NOW(),
                I_ID_USUARIO);

            SET V_ID_CREADO = LAST_INSERT_ID();
        END LOOP LOOP_METODOS_PAGO;

        -- Verificación de inserciones
        IF V_ID_CREADO > 0 THEN
            SELECT 'ok' AS resultado, 'Métodos de pago sobrescritos exitosamente' AS descripcion, V_ID_CREADO AS id;
        ELSE
            SELECT 'ok' AS resultado, 'No se agregaron nuevos métodos de pago' AS descripcion, V_ID_CREADO AS id;
        END IF;
    ELSE
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Error: Lista de métodos de pago no puede ser nula';
    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_ABM_OBSERVACIONES_X_OFERTA` */;
