CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_OBSERVACIONES_X_OFERTA`(
    IN I_ID_OFERTA VARCHAR(36),
    IN I_ID_TIPO_OBSERVACION INT,
    IN I_TX_OBSERVACION VARCHAR(500),
    IN I_ID_USUARIO VARCHAR(36),
    IN I_BL_ELIMINAR TINYINT -- Si es 1, se realiza una baja; si es 0, se modifica o inserta
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_EXISTE_OBSERVACION_TIPO INT;

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Iniciar transacción
    START TRANSACTION;

    -- ABM
    SELECT COUNT(*)
    INTO V_EXISTE_OBSERVACION_TIPO
    FROM OBSERVACIONES_X_OFERTA
    WHERE ID_OFERTA = I_ID_OFERTA
    AND ID_TIPO_OBSERVACION = I_ID_TIPO_OBSERVACION 
    AND FEC_BAJA IS NULL;
    
    IF V_EXISTE_OBSERVACION_TIPO = 0 AND I_BL_ELIMINAR = 0 THEN
        -- Alta: Insertar nueva observación
        INSERT INTO OBSERVACIONES_X_OFERTA 
        (ID_OFERTA, ID_TIPO_OBSERVACION, TX_OBSERVACION, FEC_ALTA, USR_ALTA)
        VALUES 
        (I_ID_OFERTA, I_ID_TIPO_OBSERVACION, I_TX_OBSERVACION, NOW(), I_ID_USUARIO);
        
        SELECT 'ok' AS resultado, 'Observación creada exitosamente' AS descripcion;

    ELSEIF V_EXISTE_OBSERVACION_TIPO > 0 AND I_BL_ELIMINAR = 0 THEN
        -- Modificación: Actualizar una observación existente
        UPDATE OBSERVACIONES_X_OFERTA
        SET ID_TIPO_OBSERVACION = I_ID_TIPO_OBSERVACION,
            TX_OBSERVACION = I_TX_OBSERVACION,
            FEC_ALTA = NOW(),
            USR_ALTA = I_ID_USUARIO
        WHERE ID_OFERTA = I_ID_OFERTA
        AND ID_TIPO_OBSERVACION = I_ID_TIPO_OBSERVACION
        AND FEC_BAJA IS NULL; -- Solo modificar registros activos
        
        SELECT 'ok' AS resultado, 'Observación actualizada exitosamente' AS descripcion;

    ELSEIF V_EXISTE_OBSERVACION_TIPO > 0 IS NOT NULL AND I_BL_ELIMINAR = 1 THEN
        -- Baja: Marcar observación como eliminada
        UPDATE OBSERVACIONES_X_OFERTA
        SET FEC_BAJA = NOW(),
            USR_BAJA = I_ID_USUARIO
        WHERE ID_OFERTA = I_ID_OFERTA
        AND ID_TIPO_OBSERVACION = I_ID_TIPO_OBSERVACION
        AND FEC_BAJA IS NULL; -- Solo marcar como baja los registros activos
        
        SELECT 'ok' AS resultado, 'Observación eliminada exitosamente' AS descripcion;
        
    ELSE
        -- Error: Condiciones no válidas
        SET V_ERROR = 'Error: Parámetros incorrectos.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;

    -- Confirmar la transacción
    COMMIT;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
