CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_OFERTA_GUARDADA`(
    IN I_ID_OFERTA_GUARDADA VARCHAR(36),
    IN I_ID_OFERTA VARCHAR(36),
    IN I_USR_ALTA VARCHAR(36)
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ID_OFERTA VARCHAR(36);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_EXISTE INT DEFAULT 0;

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- ABM
    IF I_ID_OFERTA_GUARDADA IS NULL THEN
        -- Validación: Verificar si el usuario ya guardó esta oferta
        SELECT COUNT(*) INTO V_EXISTE
        FROM OFERTAS_GUARDADAS
        WHERE ID_OFERTA = I_ID_OFERTA
          AND USR_ALTA = I_USR_ALTA
          AND FECHA_BAJA IS NULL;

        IF V_EXISTE > 0 THEN
            -- Si ya existe, retornar mensaje de error
            SET V_ERROR = 'El usuario ya tiene esta oferta guardada.';
            SELECT 'error' AS resultado, V_ERROR AS descripcion;
        ELSE
            -- Si no existe, proceder con el alta
            SET V_ID_OFERTA = UUID();

            INSERT INTO OFERTAS_GUARDADAS
            (ID_OFERTA_GUARDADA, ID_OFERTA, USR_ALTA, FECHA_ALTA)
            VALUES
            (UUID(), I_ID_OFERTA, I_USR_ALTA, NOW());

            SELECT 'ok' AS resultado, 'Oferta guardada exitosamente' AS descripcion, V_ID_OFERTA AS id_oferta_guardada;
        END IF;

    ELSEIF I_ID_OFERTA_GUARDADA IS NOT NULL THEN
        -- Baja: Marcar oferta guardada como eliminada
        UPDATE OFERTAS_GUARDADAS
        SET FECHA_BAJA = NOW(),
            USR_BAJA = I_USR_ALTA
        WHERE ID_OFERTA_GUARDADA = I_ID_OFERTA_GUARDADA
        AND FECHA_BAJA IS NULL;

        SELECT 'ok' AS resultado, 'Oferta guardada eliminada exitosamente' AS descripcion;
    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
