CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_REDES_X_ENTIDAD`(
    IN I_ID_TIPO_ENTIDAD INT,
    IN I_ID_ENTIDAD VARCHAR(36),
    IN I_ID_RED_SOCIAL INT,
    IN I_TX_NOMBRE_USUARIO VARCHAR(50),
    IN I_TX_URL VARCHAR(100),
    IN I_BL_ELIMINAR TINYINT -- Si es 1, se realiza una baja; si es 0, se modifica o inserta
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_EXISTE_RED_X_ENTIDAD INT;
    DECLARE V_EXISTE_ENTIDAD INT;
    DECLARE V_EXISTE_RED_SOCIAL INT;
    
    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;
    
    START TRANSACTION;
    
    -- Validar que la entidad exista
    SELECT COUNT(*)
    INTO V_EXISTE_ENTIDAD
    FROM entidades
    WHERE id_entidad = I_ID_TIPO_ENTIDAD;
    
    IF V_EXISTE_ENTIDAD = 0 THEN
        SET V_ERROR = 'Error: La entidad especificada no existe.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;
    
    -- Validar que la red social exista
    SELECT COUNT(*)
    INTO V_EXISTE_RED_SOCIAL
    FROM redes_sociales
    WHERE ID_RED_SOCIAL = I_ID_RED_SOCIAL;
    
    IF V_EXISTE_RED_SOCIAL = 0 THEN
        SET V_ERROR = 'Error: La red social especificada no existe.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;
    
    -- Verificar si existe el registro buscando por ID_ENTIDAD, NRO_ENTIDAD e ID_RED_SOCIAL
    SELECT COUNT(*)
    INTO V_EXISTE_RED_X_ENTIDAD
    FROM redes_x_entidad
    WHERE ID_ENTIDAD = I_ID_TIPO_ENTIDAD
    AND NRO_ENTIDAD = I_ID_ENTIDAD
    AND ID_RED_SOCIAL = I_ID_RED_SOCIAL;
    
    -- ABM
    IF V_EXISTE_RED_X_ENTIDAD = 0 AND I_BL_ELIMINAR = 0 THEN
        -- Alta: Insertar nueva red social para la entidad
        INSERT INTO redes_x_entidad 
        (ID_ENTIDAD, NRO_ENTIDAD, ID_RED_SOCIAL, TX_NOMBRE_USUARIO, TX_URL)
        VALUES 
        (I_ID_TIPO_ENTIDAD, I_ID_ENTIDAD, I_ID_RED_SOCIAL, I_TX_NOMBRE_USUARIO, I_TX_URL);
        
        COMMIT;
        SELECT 'ok' AS resultado, 'Red social agregada exitosamente' AS descripcion, LAST_INSERT_ID() AS id_red_x_entidad;
        
    ELSEIF V_EXISTE_RED_X_ENTIDAD > 0 AND I_BL_ELIMINAR = 0 THEN
        -- Modificación: Actualizar red social existente
        UPDATE redes_x_entidad
        SET TX_NOMBRE_USUARIO = I_TX_NOMBRE_USUARIO,
            TX_URL = I_TX_URL
        WHERE ID_ENTIDAD = I_ID_TIPO_ENTIDAD
        AND NRO_ENTIDAD = I_ID_ENTIDAD
        AND ID_RED_SOCIAL = I_ID_RED_SOCIAL;
        
        COMMIT;
        SELECT 'ok' AS resultado, 'Red social actualizada exitosamente' AS descripcion;
        
    ELSEIF V_EXISTE_RED_X_ENTIDAD > 0 AND I_BL_ELIMINAR = 1 THEN
        -- Baja: Eliminar red social
        DELETE FROM redes_x_entidad
        WHERE ID_ENTIDAD = I_ID_TIPO_ENTIDAD
        AND NRO_ENTIDAD = I_ID_ENTIDAD
        AND ID_RED_SOCIAL = I_ID_RED_SOCIAL;
        
        COMMIT;
        SELECT 'ok' AS resultado, 'Red social eliminada exitosamente' AS descripcion;
        
    ELSE
        -- Error: Condiciones no válidas
        SET V_ERROR = 'Error: Parámetros incorrectos. Verifique los datos enviados.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
