CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_TARIFA_X_OFERTA`(
    IN I_ID_TARIFA INT,
    IN I_ID_OFERTA VARCHAR(36),
    IN I_ID_TIPO_DETALLE VARCHAR(36),
    IN I_ID_TIPO_ENTRADA INT,
    IN I_MONTO_TARIFA DECIMAL(15,2),
    IN I_FEC_DESDE DATETIME,
    IN I_FEC_HASTA DATETIME,
    IN I_BL_GRATIS TINYINT,
    IN I_ID_USUARIO VARCHAR(36),
    IN I_BL_ELIMINAR TINYINT
)
BEGIN
    DECLARE V_ID_TARIFA INT;

    IF I_ID_TARIFA IS NULL THEN
        -- Alta: Insertar nueva tarifa
        INSERT INTO TARIFAS_X_OFERTA (ID_OFERTA, ID_TIPO_DETALLE, ID_TIPO_ENTRADA, MONTO_TARIFA, FEC_DESDE, FEC_HASTA, BL_GRATIS,FEC_ALTA, USR_ALTA)
        VALUES (I_ID_OFERTA, I_ID_TIPO_DETALLE, I_ID_TIPO_ENTRADA, I_MONTO_TARIFA, I_FEC_DESDE, I_FEC_HASTA,  I_BL_GRATIS, NOW(), I_ID_USUARIO);

        SET V_ID_TARIFA = LAST_INSERT_ID();

        -- Mensaje de éxito para la inserción
        SELECT 'ok' AS resultado, 'Tarifa de oferta creada exitosamente' AS descripcion, V_ID_TARIFA AS id_tarifa;

    ELSEIF I_ID_TARIFA IS NOT NULL AND I_BL_ELIMINAR = 0 THEN
        -- Modificación: Actualizar una tarifa existente
        UPDATE TARIFAS_X_OFERTA
        SET MONTO_TARIFA = I_MONTO_TARIFA,
			BL_GRATIS = I_BL_GRATIS,
            FEC_DESDE = I_FEC_DESDE,
            FEC_HASTA = I_FEC_HASTA
        WHERE ID_TARIFA_X_OFERTA = I_ID_TARIFA 
        AND FEC_BAJA IS NULL; -- Solo modificar registros activos

        -- Mensaje de éxito para la actualización
        SELECT 'ok' AS resultado, 'Tarifa de oferta actualizada exitosamente' AS descripcion, I_ID_TARIFA AS id_tarifa;

    ELSEIF I_ID_TARIFA IS NOT NULL AND I_BL_ELIMINAR = 1 THEN
        -- Baja: Marcar el registro como inactivo
        UPDATE TARIFAS_X_OFERTA
        SET FEC_BAJA = NOW(),
            USR_BAJA = I_ID_USUARIO
        WHERE ID_TARIFA_X_OFERTA = I_ID_TARIFA 
        AND FEC_BAJA IS NULL; -- Solo marcar como baja los registros activos

        -- Mensaje de éxito para la baja
        SELECT 'ok' AS resultado, 'Tarifa de oferta eliminada exitosamente' AS descripcion, I_ID_TARIFA AS id_tarifa;
    END IF;
END ;;
DELIMITER ;
