CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_TIPO_DETALLE`(
	IN I_ID_OFERTA VARCHAR(36),
    IN I_ID_TIPO_DETALLE VARCHAR(36),
    IN I_TX_TIPO_DETALLE VARCHAR(70),
    IN I_CANTIDAD INT,
    IN I_CANTIDAD_BANOS INT,
    IN I_BL_BANO_COMPARTIDO TINYINT,
    IN I_BL_BANO_ADAPTADO TINYINT,
    IN I_ID_USUARIO VARCHAR(36),
    IN I_BL_ELIMINAR TINYINT
)
BEGIN
    DECLARE V_ID_TIPO_DETALLE VARCHAR(36);
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion, I_ID_TIPO_DETALLE AS id_tipo_detalle;
    END;

    IF I_ID_TIPO_DETALLE IS NULL THEN
        -- Alta: Insertar nuevo tipo de detalle
        SET V_ID_TIPO_DETALLE = UUID();
        INSERT INTO TIPOS_DETALLE (ID_OFERTA,ID_TIPO_DETALLE, TX_TIPO_DETALLE, CANTIDAD, CANTIDAD_BAÑOS, BL_BAÑO_COMPARTIDO, BL_BAÑO_ADAPTADO, FEC_ALTA, USR_ALTA)
        VALUES (I_ID_OFERTA,V_ID_TIPO_DETALLE ,I_TX_TIPO_DETALLE, I_CANTIDAD, I_CANTIDAD_BANOS, I_BL_BANO_COMPARTIDO, I_BL_BANO_ADAPTADO, NOW(), I_ID_USUARIO);

        -- Retornar resultado exitoso
        SELECT 'ok' AS resultado, 'Tipo de detalle creado exitosamente' AS descripcion, V_ID_TIPO_DETALLE AS id_tipo_detalle;

    ELSEIF I_ID_TIPO_DETALLE IS NOT NULL AND I_BL_ELIMINAR = 0 THEN
        -- Modificación: Actualizar un tipo de detalle existente
        UPDATE TIPOS_DETALLE
        SET ID_OFERTA = I_ID_OFERTA,
			TX_TIPO_DETALLE = I_TX_TIPO_DETALLE,
            CANTIDAD = I_CANTIDAD,	-- PERMITIR CAMBIAR CANTIDAD DE HABITACIONES?
            CANTIDAD_BAÑOS = I_CANTIDAD_BANOS,
            BL_BAÑO_COMPARTIDO = I_BL_BANO_COMPARTIDO,
            BL_BAÑO_ADAPTADO = I_BL_BANO_ADAPTADO
        WHERE ID_TIPO_DETALLE = I_ID_TIPO_DETALLE
        AND FEC_BAJA IS NULL; -- Solo modificar registros activos

        -- Retornar resultado exitoso
        SELECT 'ok' AS resultado, 'Tipo de detalle actualizado exitosamente' AS descripcion, I_ID_TIPO_DETALLE AS id_tipo_detalle;

    ELSEIF I_ID_TIPO_DETALLE IS NOT NULL AND I_BL_ELIMINAR = 1 THEN
        -- Baja: Marcar el tipo de detalle como inactivo
        UPDATE TIPOS_DETALLE
        SET FEC_BAJA = NOW(),
            USR_BAJA = I_ID_USUARIO
        WHERE ID_TIPO_DETALLE = I_ID_TIPO_DETALLE
        AND FEC_BAJA IS NULL; -- Solo marcar como baja los registros activos

        -- Retornar resultado exitoso
        SELECT 'ok' AS resultado, 'Tipo de detalle eliminado exitosamente' AS descripcion, I_ID_TIPO_DETALLE AS id_tipo_detalle;
    END IF;

END ;;
DELIMITER ;
