CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_TIPO_ENTRADA_TARIFA_EVENTO`(
    IN I_TX_TIPO_ENTRADA VARCHAR(50),
    IN I_TX_DESCRIPCION VARCHAR(200),
    IN I_ID_OFERTA VARCHAR(36),
    IN I_MONTO_TARIFA DECIMAL(15,2),
    IN I_BL_GRATIS TINYINT,
    IN I_ID_TIPO_ENTRADA INT, -- Si es NULL, se hace un Alta; si no, se realiza una Baja o Modificación
    IN I_BL_ELIMINAR TINYINT -- Si es 1, se realiza una baja; si es 0, se inserta o modifica
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_ID_USUARIO VARCHAR(36);
    DECLARE V_USR_ALTA VARCHAR(36);
    DECLARE V_ID_TIPO_ENTRADA INT;
    DECLARE V_ID_TARIFA INT;
    
    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;
    
    START TRANSACTION;
    
    -- Obtener el usuario creador de la oferta
    SELECT USR_ALTA INTO V_ID_USUARIO
    FROM ofertas_turisticas
    WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA
    AND FEC_BAJA IS NULL;
    
    -- Validar que la oferta exista y esté activa
    IF V_ID_USUARIO IS NULL THEN
        SET V_ERROR = 'Error: Oferta no encontrada o está eliminada.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;
    
    -- ============================================
    -- ALTA: Crear tipo de entrada y su tarifa
    -- ============================================
    IF I_ID_TIPO_ENTRADA IS NULL AND I_BL_ELIMINAR = 0 THEN
        -- Insertar nuevo tipo de entrada
        INSERT INTO TIPOS_ENTRADA_X_OFERTA
        (TX_TIPO_ENTRADA, TX_DESCRIPCION, ID_OFERTA, FEC_ALTA, USR_ALTA)
        VALUES 
        (I_TX_TIPO_ENTRADA, I_TX_DESCRIPCION, I_ID_OFERTA, NOW(), V_ID_USUARIO);
        
        -- Obtener el ID del tipo de entrada recién insertado
        SET V_ID_TIPO_ENTRADA = LAST_INSERT_ID();
        
        -- Insertar la tarifa asociada (FEC_DESDE y FEC_HASTA en NULL para eventos)
        INSERT INTO TARIFAS_X_OFERTA 
        (ID_OFERTA, ID_TIPO_ENTRADA, MONTO_TARIFA, FEC_DESDE, FEC_HASTA, BL_GRATIS, FEC_ALTA, USR_ALTA)
        VALUES 
        (I_ID_OFERTA, V_ID_TIPO_ENTRADA, I_MONTO_TARIFA, NULL, NULL, I_BL_GRATIS, NOW(), V_ID_USUARIO);
        
        SET V_ID_TARIFA = LAST_INSERT_ID();
        
        COMMIT;
        SELECT 'ok' AS resultado, 
               'Tipo de entrada y tarifa creados exitosamente' AS descripcion, 
               V_ID_TIPO_ENTRADA AS id_tipo_entrada,
               V_ID_TARIFA AS id_tarifa;
    
    -- ============================================
    -- BAJA: Eliminar tipo de entrada y su tarifa
    -- ============================================
    ELSEIF I_ID_TIPO_ENTRADA IS NOT NULL AND I_BL_ELIMINAR = 1 THEN
        -- Validar que el usuario sea el creador del tipo de entrada
        SELECT USR_ALTA INTO V_USR_ALTA
        FROM TIPOS_ENTRADA_X_OFERTA
        WHERE ID_TIPO_ENTRADA = I_ID_TIPO_ENTRADA
        AND FEC_BAJA IS NULL;
        
        IF V_USR_ALTA IS NULL THEN
            SET V_ERROR = 'Error: Tipo de entrada no encontrado o ya está eliminado.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        END IF;
        
        IF V_USR_ALTA = V_ID_USUARIO THEN
            -- Baja lógica del tipo de entrada
            UPDATE TIPOS_ENTRADA_X_OFERTA
            SET FEC_BAJA = NOW(),
                USR_BAJA = V_ID_USUARIO
            WHERE ID_TIPO_ENTRADA = I_ID_TIPO_ENTRADA
            AND FEC_BAJA IS NULL;
            
            -- Baja lógica en cascada de todas las tarifas asociadas
            UPDATE TARIFAS_X_OFERTA
            SET FEC_BAJA = NOW(),
                USR_BAJA = V_ID_USUARIO
            WHERE ID_TIPO_ENTRADA = I_ID_TIPO_ENTRADA
            AND FEC_BAJA IS NULL;
            
            COMMIT;
            SELECT 'ok' AS resultado, 
                   'Tipo de entrada y tarifas asociadas eliminados exitosamente' AS descripcion;
        ELSE
            SET V_ERROR = 'Error: Usuario no autorizado para eliminar este tipo de entrada.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        END IF;
    
    -- ============================================
    -- MODIFICACIÓN: Actualizar tipo de entrada y su tarifa
    -- ============================================
    ELSEIF I_ID_TIPO_ENTRADA IS NOT NULL AND I_BL_ELIMINAR = 0 THEN
        -- Validar que el usuario sea el creador
        SELECT USR_ALTA INTO V_USR_ALTA
        FROM TIPOS_ENTRADA_X_OFERTA
        WHERE ID_TIPO_ENTRADA = I_ID_TIPO_ENTRADA
        AND FEC_BAJA IS NULL;
        
        IF V_USR_ALTA IS NULL THEN
            SET V_ERROR = 'Error: Tipo de entrada no encontrado o ya está eliminado.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        END IF;
        
        IF V_USR_ALTA = V_ID_USUARIO THEN
            -- Actualizar el tipo de entrada
            UPDATE TIPOS_ENTRADA_X_OFERTA
            SET TX_TIPO_ENTRADA = I_TX_TIPO_ENTRADA,
                TX_DESCRIPCION = I_TX_DESCRIPCION,
                ID_OFERTA = I_ID_OFERTA
            WHERE ID_TIPO_ENTRADA = I_ID_TIPO_ENTRADA
            AND FEC_BAJA IS NULL;
            
            -- Actualizar la tarifa asociada (asumimos que hay una sola tarifa activa por tipo de entrada)
            UPDATE TARIFAS_X_OFERTA
            SET MONTO_TARIFA = I_MONTO_TARIFA,
                BL_GRATIS = I_BL_GRATIS
            WHERE ID_TIPO_ENTRADA = I_ID_TIPO_ENTRADA
            AND FEC_BAJA IS NULL;
            
            COMMIT;
            SELECT 'ok' AS resultado, 
                   'Tipo de entrada y tarifa modificados exitosamente' AS descripcion;
        ELSE
            SET V_ERROR = 'Error: Usuario no autorizado para modificar este tipo de entrada.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        END IF;
    
    ELSE
        -- Error: Condiciones no válidas
        SET V_ERROR = 'Error: Parámetros incorrectos.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_ABM_USUARIOS` */;
