CREATE DEFINER=`root`@`%` PROCEDURE `SP_ABM_USUARIOS`(
	IN I_TX_MAIL VARCHAR(100),
	IN I_TX_CONTRASENIA varchar(255) ,
	IN I_ID_USUARIO VARCHAR(100),
    IN I_NRO_VERIFICACION VARCHAR(100)
)
BEGIN

	DECLARE V_ID_USUARIO VARCHAR(36);
    DECLARE V_BL_VERIFICADO INT DEFAULT 0;
    DECLARE V_COUNT_USUARIO INT;
    
    DECLARE V_ERROR VARCHAR (5000);
	DECLARE V_ERROR_SQL VARCHAR(5000);
	DECLARE V_DESCRIPCION VARCHAR(500);
    DECLARE DONE INT DEFAULT FALSE;
    
	DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET DONE = TRUE;

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
		GET CURRENT DIAGNOSTICS CONDITION 1
		V_ERROR_SQL = MESSAGE_TEXT;
		IF (V_ERROR IS NULL ) THEN
			SET V_ERROR = V_ERROR_SQL;
		END IF;
        ROLLBACK;

		SELECT	'error'			AS resultado,
				V_ERROR			AS descripcion,
				V_ID_USUARIO	AS id_usuario;
	END;

	-- ALTA USUARIO
    
    IF I_TX_MAIL IS NOT NULL AND I_ID_USUARIO IS NULL
    THEN
    -- VALIDAMOS EXISTENCIA DE MAIL
		SELECT COUNT(*)
		INTO V_COUNT_USUARIO
		FROM USUARIOS
		WHERE TX_MAIL = TRIM(I_TX_MAIL)
		AND FEC_BAJA IS NULL;
		
		IF V_COUNT_USUARIO = 0
		THEN
			SET V_ID_USUARIO = UUID();
			
			IF I_TX_CONTRASENIA IS NULL AND I_NRO_VERIFICACION IS NULL
            THEN
				SET V_BL_VERIFICADO = 1;
			END IF;

			INSERT INTO USUARIOS(
			ID_USUARIO,
			TX_MAIL,
			TX_CONTRASENIA,
			NRO_VERIFICACION,
			BL_VERIFICADO,
			FEC_ALTA)
			VALUES (
			V_ID_USUARIO,
			I_TX_MAIL,
			I_TX_CONTRASENIA,
			I_NRO_VERIFICACION,
			V_BL_VERIFICADO,
			NOW());
				
            SELECT	'ok' 				AS resultado,
				V_DESCRIPCION		AS descripcion,
				V_ID_USUARIO		AS id_usuario;
                
        ELSE
			SET V_ERROR := 'Error al crear usuario. Ya existe un usuario con el email ingresado. ';
			SIGNAL SQLSTATE '45000';
		END IF;
				
	END IF;
        
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
