CREATE DEFINER=`root`@`%` PROCEDURE `SP_ALTA_DETALLE_RESERVA`(
    IN I_ID_RESERVA VARCHAR(36),
    IN I_ID_TIPO_DETALLE VARCHAR(36),
    IN I_ID_TIPO_ENTRADA INT,
    IN I_ID_OFERTA VARCHAR(36),
    IN I_FEC_INICIO DATETIME,
	IN I_FEC_FIN DATETIME,
	IN I_ID_HORARIO INT,
    IN I_CANTIDAD INT,
    IN I_PRECIO_UNITARIO DECIMAL(10,2),
    IN I_MONTO_TOTAL DECIMAL(15,2),
    IN I_USR_ALTA VARCHAR(36)
)
BEGIN
    DECLARE V_CANTIDAD_COINCIDENCIA INT;
    DECLARE V_CANTIDAD INT;
    DECLARE V_ID_DISPONIBILIDAD INT;
    DECLARE V_CUPO_ACTUAL INT;
    DECLARE V_BL_SIN_CUPO TINYINT;
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_ID_DETALLE_RESERVA VARCHAR(36);
    DECLARE V_TIPO_OFERTA VARCHAR(36);
    DECLARE V_SUB_TIPO_OFERTA VARCHAR(36);
    DECLARE V_PORCENTAJE_PAGO_ANTICIPADO DECIMAL(5,2);
    DECLARE V_MONTO_TOTAL_LIMPIO DECIMAL(18,2);

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Obtener el tipo y subtipo de oferta
    SELECT ID_TIPO_OFERTA, ID_SUB_TIPO_OFERTA, PORCENTAJE_PAGO_ANTICIPADO
    INTO V_TIPO_OFERTA, V_SUB_TIPO_OFERTA, V_PORCENTAJE_PAGO_ANTICIPADO
    FROM OFERTAS_TURISTICAS
    WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA;
    
    SET V_MONTO_TOTAL_LIMPIO = I_MONTO_TOTAL / 100 * V_PORCENTAJE_PAGO_ANTICIPADO;

    -- Validación para alojamientos
    IF V_TIPO_OFERTA = 1 AND V_SUB_TIPO_OFERTA = 1 THEN
		
        SELECT CANTIDAD
        INTO V_CANTIDAD
        FROM TIPOS_DETALLE
        WHERE ID_OFERTA = I_ID_OFERTA
        AND ID_TIPO_DETALLE = I_ID_TIPO_DETALLE;
        
		SELECT SUM(DR.CANTIDAD)
		INTO V_CANTIDAD_COINCIDENCIA
		FROM RESERVAS R
        LEFT JOIN DETALLE_RESERVA DR ON R.ID_RESERVA = DR.ID_RESERVA
		LEFT JOIN CAMBIOS_ESTADO_RESERVA CER ON R.ID_RESERVA = CER.ID_RESERVA
		AND CER.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_RESERVA WHERE ID_RESERVA = R.ID_RESERVA)
		WHERE R.ID_OFERTA = I_ID_OFERTA
		AND DR.ID_TIPO_DETALLE = I_ID_TIPO_DETALLE
		AND DATE(R.FEC_INICIO) <= DATE(I_FEC_FIN)
		AND DATE(R.FEC_FIN) >= DATE(I_FEC_INICIO)
        AND CER.ID_ESTADO IN (8,10); -- SE FIJA QUE LAS RESERVAS EN CURSO ESTEN EN ESTADO RESERVADA O EN CURSO

        -- Verificar disponibilidad de habitaciones
        IF V_CANTIDAD_COINCIDENCIA > (V_CANTIDAD - I_CANTIDAD) THEN
            SET V_ERROR = 'Error: No hay disponibilidad para el tipo de habitación en la fecha seleccionada.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        ELSE
            -- Insertar nuevo detalle de la reserva
            SET V_ID_DETALLE_RESERVA = UUID();
            INSERT INTO DETALLE_RESERVA
            (ID_DETALLE_RESERVA, ID_RESERVA, ID_TIPO_DETALLE, CANTIDAD, PRECIO_UNITARIO, MONTO_TOTAL, FEC_ALTA, USR_ALTA)
            VALUES
            (V_ID_DETALLE_RESERVA, I_ID_RESERVA, I_ID_TIPO_DETALLE, I_CANTIDAD, I_PRECIO_UNITARIO, V_MONTO_TOTAL_LIMPIO, NOW(), I_USR_ALTA);

            SELECT 'ok' AS resultado, 'Detalle de reserva creado exitosamente' AS descripcion, V_ID_DETALLE_RESERVA AS id_detalle_reserva;
        END IF;

    -- Validación para actividades
    ELSEIF V_TIPO_OFERTA = 2 THEN
        -- Verificar disponibilidad en DISPONIBILIDAD_DIA
        SELECT ID_DISPONIBILIDAD, CUPO_DISPONIBLE, BL_SIN_CUPO
        INTO V_ID_DISPONIBILIDAD, V_CUPO_ACTUAL, V_BL_SIN_CUPO
        FROM DISPONIBILIDAD_DIA
        WHERE ID_HORARIO = I_ID_HORARIO
        AND DATE(FECHA) = DATE(I_FEC_INICIO);

        IF V_ID_DISPONIBILIDAD IS NOT NULL THEN
            -- Verificar si hay cupo suficiente
            IF V_BL_SIN_CUPO = 0 AND V_CUPO_ACTUAL >= I_CANTIDAD THEN
                -- Actualizar el cupo disponible
                UPDATE DISPONIBILIDAD_DIA
                SET CUPO_DISPONIBLE = CUPO_DISPONIBLE - I_CANTIDAD
                WHERE ID_HORARIO = I_ID_HORARIO
                AND DATE(FECHA) = DATE(I_FEC_INICIO);

                -- Insertar el detalle de reserva
                SET V_ID_DETALLE_RESERVA = UUID();
                INSERT INTO DETALLE_RESERVA
                (ID_DETALLE_RESERVA, ID_RESERVA, ID_TIPO_ENTRADA, CANTIDAD, PRECIO_UNITARIO, MONTO_TOTAL, FEC_ALTA, USR_ALTA)
                VALUES
                (V_ID_DETALLE_RESERVA, I_ID_RESERVA, I_ID_TIPO_ENTRADA, I_CANTIDAD, I_PRECIO_UNITARIO, V_MONTO_TOTAL_LIMPIO, NOW(), I_USR_ALTA);

                COMMIT;
                SELECT 'ok' AS resultado, 'Detalle de reserva creado exitosamente' AS descripcion, V_ID_DETALLE_RESERVA AS id_detalle_reserva;
			
            ELSEIF V_BL_SIN_CUPO = 1 THEN
				-- Insertar el detalle de reserva
                SET V_ID_DETALLE_RESERVA = UUID();
                INSERT INTO DETALLE_RESERVA
                (ID_DETALLE_RESERVA, ID_RESERVA, ID_TIPO_ENTRADA, CANTIDAD, PRECIO_UNITARIO, MONTO_TOTAL, FEC_ALTA, USR_ALTA)
                VALUES
                (V_ID_DETALLE_RESERVA, I_ID_RESERVA, I_ID_TIPO_ENTRADA, I_CANTIDAD, I_PRECIO_UNITARIO, V_MONTO_TOTAL_LIMPIO, NOW(), I_USR_ALTA);

                COMMIT;
                SELECT 'ok' AS resultado, 'Detalle de reserva creado exitosamente' AS descripcion, V_ID_DETALLE_RESERVA AS id_detalle_reserva;
                
            ELSE
                SET V_ERROR = CONCAT('Error: Cupo insuficiente. Disponibles: ', V_CUPO_ACTUAL,'BL SIN CUPO:  ', I_FEC_INICIO,'CANTIDAD QUE QUIERE COMPRAR ', I_CANTIDAD);
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
            END IF;
            
        ELSE
            -- Crear registro de disponibilidad si no existe
				INSERT INTO DISPONIBILIDAD_DIA (ID_HORARIO, FECHA, CUPO_DISPONIBLE, CUPO_MAXIMO, BL_SIN_CUPO)
				VALUES (
					I_ID_HORARIO,
					DATE(I_FEC_INICIO),
					CASE 
						WHEN (SELECT BL_SIN_CUPO FROM HORARIOS_CHECK WHERE ID_HORARIO = I_ID_HORARIO) = 1 THEN NULL
						ELSE (SELECT CUPO_MAXIMO FROM HORARIOS_CHECK WHERE ID_HORARIO = I_ID_HORARIO) - I_CANTIDAD
					END,
					(SELECT CUPO_MAXIMO FROM HORARIOS_CHECK WHERE ID_HORARIO = I_ID_HORARIO),
					(SELECT BL_SIN_CUPO FROM HORARIOS_CHECK WHERE ID_HORARIO = I_ID_HORARIO)
				);


            -- Insertar el detalle de reserva
            SET V_ID_DETALLE_RESERVA = UUID();
            INSERT INTO DETALLE_RESERVA
            (ID_DETALLE_RESERVA, ID_RESERVA, ID_TIPO_ENTRADA, CANTIDAD, PRECIO_UNITARIO, MONTO_TOTAL, FEC_ALTA, USR_ALTA)
            VALUES
            (V_ID_DETALLE_RESERVA, I_ID_RESERVA, I_ID_TIPO_ENTRADA, I_CANTIDAD, I_PRECIO_UNITARIO, V_MONTO_TOTAL_LIMPIO, NOW(), I_USR_ALTA);

            COMMIT;
            SELECT 'ok' AS resultado, 'Detalle de reserva creado exitosamente' AS descripcion, V_ID_DETALLE_RESERVA AS id_detalle_reserva;
        END IF;

    ELSE
        SET V_ERROR = 'Tipo de oferta no reconocido.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;
END ;;
DELIMITER ;
