CREATE DEFINER=`root`@`%` PROCEDURE `SP_ALTA_OFERTA`(
--  IN I_ID_OFERTA_TURISTICA VARCHAR(36),
 IN I_ID_TIPO_OFERTA INT,
 IN I_ID_SUB_TIPO_OFERTA INT,
 IN I_ID_ESTABLECIMIENTO INT,
 IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
	DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_ID_OFERTA_TURISTICA VARCHAR(36) DEFAULT NULL;
    DECLARE V_ID_PRESTADOR VARCHAR(36);
    
 -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion, V_ID_OFERTA_TURISTICA AS id_oferta;
    END;

    SELECT ID_PRESTADOR
    INTO V_ID_PRESTADOR
    FROM PRESTADORES
    WHERE ID_USUARIO = I_ID_USUARIO
    AND FEC_BAJA IS NULL;
    
    SET V_ID_OFERTA_TURISTICA = UUID();
	
    INSERT INTO OFERTAS_TURISTICAS
	(ID_OFERTA_TURISTICA, ID_TIPO_OFERTA, ID_SUB_TIPO_OFERTA, ID_ESTABLECIMIENTO,
	ID_PRESTADOR, FEC_ALTA, USR_ALTA)
	VALUES
	(V_ID_OFERTA_TURISTICA, I_ID_TIPO_OFERTA, I_ID_SUB_TIPO_OFERTA, I_ID_ESTABLECIMIENTO,
	V_ID_PRESTADOR, NOW(), I_ID_USUARIO);
    
    INSERT INTO CAMBIOS_ESTADO_OFERTA
            (ID_OFERTA, ID_ESTADO, FEC_ALTA, USR_ALTA)
            VALUES
            (V_ID_OFERTA_TURISTICA, 1, NOW(), I_ID_USUARIO);
    
	SELECT 'ok' AS resultado, 'Oferta creada exitosamente' AS descripcion, V_ID_OFERTA_TURISTICA AS id_oferta;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
