CREATE DEFINER=`root`@`%` PROCEDURE `SP_ALTA_RESERVA`(
    IN I_ID_OFERTA VARCHAR(36),
    IN I_TX_MAIL_CONTACTO VARCHAR(45),
    IN I_NRO_TELEFONO_CONTACTO VARCHAR(45),
    IN I_FEC_INICIO DATETIME,
	IN I_FEC_FIN DATETIME,
    IN I_MONTO_FINAL DECIMAL(15,2),
    IN I_USR_ALTA VARCHAR(36)
)
BEGIN
    DECLARE V_ID_TURISTA VARCHAR(36);
    DECLARE V_ID_RESERVA VARCHAR(36);
    DECLARE V_COUNT_CONFLICTS INT;
    DECLARE V_CUPO_ACTUAL INT;
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Obtener el ID del turista
    SELECT ID_TURISTA INTO V_ID_TURISTA
    FROM TURISTAS
    WHERE ID_USUARIO = I_USR_ALTA;

	-- Generar un UUID para la reserva
	SET V_ID_RESERVA = UUID();

	-- Insertar la nueva reserva
	INSERT INTO RESERVAS
	(ID_RESERVA, FEC_INICIO, FEC_FIN, ID_OFERTA, ID_TURISTA, USR_ALTA, FEC_ALTA, MONTO_FINAL, TX_MAIL_CONTACTO, NRO_TELEFONO_CONTACTO)
	VALUES
	(V_ID_RESERVA, I_FEC_INICIO, I_FEC_FIN, I_ID_OFERTA, V_ID_TURISTA, I_USR_ALTA, NOW(), I_MONTO_FINAL, I_TX_MAIL_CONTACTO, I_NRO_TELEFONO_CONTACTO);
	
    IF I_MONTO_FINAL != 0
    THEN
		-- Registrar el cambio de estado inicial "Pendiente de pago"
		INSERT INTO CAMBIOS_ESTADO_RESERVA
		(ID_RESERVA, ID_ESTADO, FEC_ALTA, USR_ALTA)
		VALUES
		(V_ID_RESERVA, 7, NOW(), I_USR_ALTA);
	ELSE
		-- Registrar el cambio de estado inicial "Reservada"
		INSERT INTO CAMBIOS_ESTADO_RESERVA
		(ID_RESERVA, ID_ESTADO, FEC_ALTA, USR_ALTA)
		VALUES
		(V_ID_RESERVA, 8, NOW(), I_USR_ALTA);
	END IF;

	-- Retornar éxito
	SELECT 'ok' AS resultado, 'Reserva creada exitosamente' AS descripcion, V_ID_RESERVA AS id_reserva;

END ;;
DELIMITER ;
