CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_BUSCAR_UBICACIONES`(
    IN I_CAMPO_BUSQUEDA VARCHAR(100)
)
BEGIN
    SELECT 
        PAISES.TX_PAIS AS pais,
        PROVINCIAS.TX_PROVINCIA AS provincia,
        DEPARTAMENTOS.TX_DEPARTAMENTO AS departamento,
        LOCALIDADES.TX_LOCALIDAD AS localidad,
        LOCALIDADES.ID_LOCALIDAD AS id_localidad,
        LOCALIDADES.TX_LATITUD AS latitud,
        LOCALIDADES.TX_LONGITUD AS longitud,
        -- Calcular una relevancia avanzada
        CASE 
            WHEN LOCALIDADES.TX_LOCALIDAD = I_CAMPO_BUSQUEDA THEN 100
            WHEN LOCALIDADES.TX_LOCALIDAD LIKE CONCAT('%', I_CAMPO_BUSQUEDA, '%') THEN 95
            WHEN PROVINCIAS.TX_PROVINCIA = I_CAMPO_BUSQUEDA THEN 90
            WHEN PROVINCIAS.TX_PROVINCIA LIKE CONCAT('%', I_CAMPO_BUSQUEDA, '%') THEN 85
            WHEN DEPARTAMENTOS.TX_DEPARTAMENTO = I_CAMPO_BUSQUEDA THEN 80
            WHEN DEPARTAMENTOS.TX_DEPARTAMENTO LIKE CONCAT('%', I_CAMPO_BUSQUEDA, '%') THEN 75
            WHEN PAISES.TX_PAIS = I_CAMPO_BUSQUEDA THEN 70
            WHEN PAISES.TX_PAIS LIKE CONCAT('%', I_CAMPO_BUSQUEDA, '%') THEN 65
            ELSE 50 -- para coincidencias menores
        END AS relevancia
    FROM 
        LOCALIDADES
    JOIN DEPARTAMENTOS ON LOCALIDADES.ID_DEPARTAMENTO = DEPARTAMENTOS.ID_DEPARTAMENTO
    JOIN PROVINCIAS ON DEPARTAMENTOS.ID_PROVINCIA = PROVINCIAS.ID_PROVINCIA
    JOIN PAISES ON PROVINCIAS.ID_PAIS = PAISES.ID_PAIS
    WHERE PROVINCIAS.ID_PROVINCIA = 6
    AND (
        PAISES.TX_PAIS LIKE CONCAT('%', I_CAMPO_BUSQUEDA, '%')
        OR PROVINCIAS.TX_PROVINCIA LIKE CONCAT('%', I_CAMPO_BUSQUEDA, '%')
        OR DEPARTAMENTOS.TX_DEPARTAMENTO LIKE CONCAT('%', I_CAMPO_BUSQUEDA, '%')
        OR LOCALIDADES.TX_LOCALIDAD LIKE CONCAT('%', I_CAMPO_BUSQUEDA, '%')
    ) 
    ORDER BY relevancia DESC
    LIMIT 5; -- Limitar a los primeros 5 resultados más relevantes
END ;;
DELIMITER ;
