CREATE DEFINER=`root`@`%` PROCEDURE `SP_CANCELAR_RESERVA_CON_POLITICA`(
    IN I_ID_RESERVA VARCHAR(36),
    IN I_ID_USUARIO_CANCELA VARCHAR(36)
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_COUNT_RESERVA INT;
    DECLARE V_FEC_INICIO DATETIME;
    DECLARE V_DIAS_DIFERENCIA INT;
    DECLARE V_PLAZO_DIAS_CANCELACION INT;
    DECLARE V_ID_POLITICA_CANCELACION INT;
    DECLARE V_MONTO_ANTICIPADO DECIMAL(20,2);

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Validar que la reserva existe y no esté ya cancelada
    SELECT COUNT(*)
    INTO V_COUNT_RESERVA
    FROM RESERVAS
    WHERE ID_RESERVA = I_ID_RESERVA
    AND FEC_BAJA IS NULL;

    IF V_COUNT_RESERVA = 1 THEN
        -- Obtener la fecha de inicio de la reserva y la política de cancelación asociada a la oferta
        SELECT R.FEC_INICIO, O.PLAZO_DIAS_CANCELACION, O.ID_POLITICA_CANCELACION, O.MONTO_PAGO_ANTICIPADO
        INTO V_FEC_INICIO, V_PLAZO_DIAS_CANCELACION, V_ID_POLITICA_CANCELACION, V_MONTO_ANTICIPADO
        FROM RESERVAS R
        JOIN OFERTAS_TURISTICAS O ON R.ID_OFERTA = O.ID_OFERTA_TURISTICA
        WHERE R.ID_RESERVA = I_ID_RESERVA;

        -- Calcular la diferencia de días entre la fecha actual y la fecha de inicio de la reserva
        SET V_DIAS_DIFERENCIA = DATEDIFF(V_FEC_INICIO, NOW());

        -- Verificar si la reserva está dentro del plazo permitido para cancelar
        IF V_DIAS_DIFERENCIA >= V_PLAZO_DIAS_CANCELACION THEN
            -- Dependiendo de la política de cancelación, se ejecutan diferentes acciones
            CASE V_ID_POLITICA_CANCELACION
                WHEN 1 THEN
                    -- Política 1: Cancelación con devolución de pago anticipado
                    -- Aquí puedes agregar la lógica de devolución del pago anticipado si se requiere
                    -- Actualizar la reserva como cancelada
                    UPDATE RESERVAS
                    SET FEC_BAJA = NOW(), USR_BAJA = I_ID_USUARIO_CANCELA
                    WHERE ID_RESERVA = I_ID_RESERVA;

                    -- Registrar el cambio de estado como "Cancelada"
                    INSERT INTO CAMBIOS_ESTADO_RESERVA
                    (ID_RESERVA, ID_ESTADO, FEC_ALTA, USR_ALTA)
                    VALUES
                    (I_ID_RESERVA, 9, NOW(), I_ID_USUARIO_CANCELA);

                    SELECT 'ok' AS resultado, 'Reserva cancelada con devolución de pago anticipado' AS descripcion;

                WHEN 2 THEN
                    -- Política 2: Cancelación con pago anticipado reutilizable
                    -- Aquí puedes marcar el pago anticipado como reutilizable para otra reserva
                    -- Actualizar la reserva como cancelada
                    UPDATE RESERVAS
                    SET FEC_BAJA = NOW(), USR_BAJA = I_ID_USUARIO_CANCELA
                    WHERE ID_RESERVA = I_ID_RESERVA;

                    -- Registrar el cambio de estado como "Cancelada"
                    INSERT INTO CAMBIOS_ESTADO_RESERVA
                    (ID_RESERVA, ID_ESTADO, FEC_ALTA, USR_ALTA)
                    VALUES
                    (I_ID_RESERVA, 9, NOW(), I_ID_USUARIO_CANCELA);

                    SELECT 'ok' AS resultado, 'Reserva cancelada con pago anticipado reutilizable' AS descripcion;

                WHEN 3 THEN
                    -- Política 3: Cancelación sin devolución de pago anticipado
                    -- Actualizar la reserva como cancelada
                    UPDATE RESERVAS
                    SET FEC_BAJA = NOW(), USR_BAJA = I_ID_USUARIO_CANCELA
                    WHERE ID_RESERVA = I_ID_RESERVA;

                    -- Registrar el cambio de estado como "Cancelada"
                    INSERT INTO CAMBIOS_ESTADO_RESERVA
                    (ID_RESERVA, ID_ESTADO, FEC_ALTA, USR_ALTA)
                    VALUES
                    (I_ID_RESERVA, 9, NOW(), I_ID_USUARIO_CANCELA);

                    SELECT 'ok' AS resultado, 'Reserva cancelada sin devolución de pago anticipado' AS descripcion;
            END CASE;
        ELSE
            -- Si el plazo de cancelación ya ha pasado
            SET V_ERROR = 'No se puede cancelar la reserva fuera del plazo de cancelación.';
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
        END IF;
    ELSE
        -- Si no existe la reserva o ya fue cancelada
        SET V_ERROR = 'La reserva no existe o ya ha sido cancelada.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_CARGAR_UBICACIONES` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
