CREATE DEFINER=`root`@`%` PROCEDURE `SP_CARGAR_UBICACIONES`(
    IN I_LOCALIDAD VARCHAR(100),
    IN I_LATITUD VARCHAR(45),
    IN I_LONGITUD VARCHAR(45),
    IN I_DEPARTAMENTO VARCHAR(100),
    IN I_PROVINCIA VARCHAR(100)
)
BEGIN
    DECLARE V_ID_DEPARTAMENTO INT;
    DECLARE V_ID_LOCALIDAD INT;
	DECLARE DESCRIPCION VARCHAR(100);

    -- Obtener ID del departamento
    CALL SP_REGISTRAR_DEPARTAMENTO(I_DEPARTAMENTO, I_PROVINCIA);
    SELECT ID_DEPARTAMENTO INTO V_ID_DEPARTAMENTO
    FROM DEPARTAMENTOS
    WHERE TX_DEPARTAMENTO = I_DEPARTAMENTO
    AND ID_PROVINCIA = (SELECT ID_PROVINCIA FROM PROVINCIAS WHERE TX_PROVINCIA = I_PROVINCIA);
    
    IF V_ID_DEPARTAMENTO IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No se pudo obtener o crear el departamento especificado.';
    ELSE
        -- Verificar si la localidad ya existe
        SELECT ID_LOCALIDAD INTO V_ID_LOCALIDAD
        FROM LOCALIDADES
        WHERE TX_LOCALIDAD = I_LOCALIDAD AND ID_DEPARTAMENTO = V_ID_DEPARTAMENTO;
        
        IF V_ID_LOCALIDAD IS NULL THEN
            -- Si no existe, insertar nueva localidad
            INSERT INTO LOCALIDADES (TX_LOCALIDAD, TX_LATITUD, TX_LONGITUD, ID_DEPARTAMENTO)
            VALUES (I_LOCALIDAD, I_LATITUD, I_LONGITUD, V_ID_DEPARTAMENTO);
            
            SET V_ID_LOCALIDAD = LAST_INSERT_ID();
            SET DESCRIPCION = "Localidad insertada correctamente";
        ELSE
            -- Si existe, actualizar latitud y longitud
            UPDATE LOCALIDADES
            SET TX_LATITUD = I_LATITUD, TX_LONGITUD = I_LONGITUD
            WHERE ID_LOCALIDAD = V_ID_LOCALIDAD;
            
            SET V_ID_LOCALIDAD = LAST_INSERT_ID();
            SET DESCRIPCION = "La localidad ya existía, se actualizan los datos de latitud y longitud";

        END IF;
        
        -- Devolver el ID de la localidad
        SELECT 'ok' AS resultado,
			V_ID_LOCALIDAD AS id_localidad,
            DESCRIPCION AS descripcion;
    END IF;
END ;;
DELIMITER ;
