DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_GUARDAR_DATOS_MP`(
	IN I_ID_USUARIO VARCHAR(36),
    IN I_TX_ACCESS_TOKEN VARCHAR(100),
    IN I_TX_PUBLIC_KEY VARCHAR(100),
    IN I_TX_REFRESH_TOKEN VARCHAR(100),
    IN I_BL_LIVE_MODE TINYINT,
    IN I_TX_USER_ID VARCHAR(100),
    IN I_TX_TOKEN_TYPE VARCHAR(45),
    IN I_EXPIRACION BIGINT,
    IN I_TX_SCOPE VARCHAR(100)
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Actualizar los datos en la tabla DATOS_MP_USUARIO
    UPDATE DATOS_MP_USUARIO
    SET TX_ACCESS_TOKEN = I_TX_ACCESS_TOKEN,
        TX_PUBLIC_KEY = I_TX_PUBLIC_KEY,
        TX_REFRESH_TOKEN = I_TX_REFRESH_TOKEN,
        BL_LIVE_MODE = I_BL_LIVE_MODE,
        TX_USER_ID = I_TX_USER_ID,
        TX_TOKEN_TYPE = I_TX_TOKEN_TYPE,
        EXPIRACION = I_EXPIRACION,
        TX_SCOPE = I_TX_SCOPE
        WHERE ID_USUARIO = I_ID_USUARIO;

    SELECT 'ok' AS resultado, 'Datos actualizados exitosamente' AS descripcion;
END ;;
DELIMITER ;
