CREATE DEFINER=`root`@`%` PROCEDURE `SP_LISTAR_LOCALIDADES_CON_JERARQUIA`()
BEGIN
    SELECT 
        l.ID_LOCALIDAD AS id_localidad,
        l.TX_LOCALIDAD AS localidad,
        d.ID_DEPARTAMENTO AS id_departamento,
        d.TX_DEPARTAMENTO AS departamento,
        p.ID_PROVINCIA AS id_provincia,
        p.TX_PROVINCIA AS provincia,
        pa.ID_PAIS AS id_pais,
        pa.TX_PAIS AS pais
    FROM LOCALIDADES l
    LEFT JOIN DEPARTAMENTOS d ON l.ID_DEPARTAMENTO = d.ID_DEPARTAMENTO
    LEFT JOIN PROVINCIAS p ON d.ID_PROVINCIA = p.ID_PROVINCIA
    LEFT JOIN PAISES pa ON p.ID_PAIS = pa.ID_PAIS
    ORDER BY pa.TX_PAIS, p.TX_PROVINCIA, d.TX_DEPARTAMENTO, l.TX_LOCALIDAD;
END ;;
DELIMITER ;
