CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_LISTAR_TIPOS_SUBTIPOS_OFERTA`()
BEGIN
	-- Primer conjunto de resultados: Tipos de oferta
    SELECT 
        ID_TIPO_OFERTA AS id_tipo_oferta,
        TX_TIPO_OFERTA AS nombre_tipo_oferta
    FROM 
        TIPOS_OFERTA
    ORDER BY 
        ID_TIPO_OFERTA;

    -- Segundo conjunto de resultados: Subtipos de oferta
    SELECT 
        ID_SUB_TIPO_OFERTA AS id_sub_tipo_oferta,
        ID_TIPO_OFERTA AS id_tipo_oferta,
        TX_SUB_TIPO_OFERTA AS nombre_sub_tipo_oferta
    FROM 
        SUB_TIPO_OFERTA
    ORDER BY 
        ID_TIPO_OFERTA, ID_SUB_TIPO_OFERTA;
END ;;
DELIMITER ;
