CREATE DEFINER=`root`@`%` PROCEDURE `SP_LISTAR_UBICACIONES`()
BEGIN
    SELECT ID_LOCALIDAD AS id_localidad,
		   TX_LOCALIDAD AS localidad,
		   ID_DEPARTAMENTO AS id_departamento 
    FROM LOCALIDADES
    ORDER BY TX_LOCALIDAD;
    SELECT ID_DEPARTAMENTO AS id_departamento,
		   TX_DEPARTAMENTO AS departamento,
		   ID_PROVINCIA AS id_provincia 
    FROM DEPARTAMENTOS
	ORDER BY TX_DEPARTAMENTO;
    SELECT ID_PROVINCIA AS id_provincia,
		   TX_PROVINCIA AS provincia,
		   ID_PAIS AS id_pais  
    FROM PROVINCIAS
	ORDER BY TX_PROVINCIA;
    SELECT ID_PAIS AS id_pais,
		   TX_PAIS AS pais
    FROM PAISES
	ORDER BY TX_PAIS;
END ;;
DELIMITER ;
