CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_ALOJAMIENTOS_X_FILTRO`(
    IN I_PageNumber INT,
    IN I_PageSize INT,
    IN I_ID_SUB_TIPO_OFERTA INT,
    IN I_ID_ESTABLECIMIENTO INT,
    IN I_TX_OFERTA VARCHAR(100),
    IN I_ID_PROVINCIA INT,
    IN I_ID_DEPARTAMENTO INT,
    IN I_ID_LOCALIDAD INT,
  --  IN I_TX_BARRIO VARCHAR(45),
    IN I_TX_CALLE VARCHAR(100),
    IN I_MIN_MONTO_GARANTIA DECIMAL(20,2),
    IN I_MAX_MONTO_GARANTIA DECIMAL(20,2),
    IN I_MIN_DIAS_ESTADIA INT
)
BEGIN
    DECLARE OffsetValue INT;

    -- Calculamos el offset para la paginación
    SET OffsetValue = (I_PageNumber - 1) * I_PageSize;

    -- Construimos la base de la consulta
    SET @V_SQL := '
        SELECT 
            OT.ID_OFERTA_TURISTICA AS id_alojamiento,
            OT.TX_OFERTA AS nombre_oferta,
            OT.TX_DESCRIPCION AS descripcion_alojamiento,
            OT.FEC_ALTA AS fecha_alta,
            OT.FEC_BAJA AS fecha_baja,
            OT.ID_ESTABLECIMIENTO AS id_establecimiento,
            E.TX_ESTABLECIMIENTO AS nombre_establecimiento,
            P.TX_RAZON_SOCIAL AS razon_social_prestador,
            OT.ID_TIPO_OFERTA AS id_tipo_oferta,
            OT.ID_SUB_TIPO_OFERTA AS id_subtipo_oferta,
            OT.MONTO_GARANTIA AS garantia_alojamiento,
            OT.MONTO_PAGO_ANTICIPADO AS pago_anticipado,
            OT.PORCENTAJE_PAGO_ANTICIPADO AS porcentaje_pago_anticipado,
            OT.MIN_DIAS_ESTADIA AS minimo_dias_estadia,
            D.TX_CALLE AS nombre_calle,
            D.TX_BARRIO AS nombre_barrio,
            D.ID_LOCALIDAD AS id_localidad,
            D.ID_DEPARTAMENTO AS id_departamento,
            D.ID_PROVINCIA AS id_provincia
        FROM OFERTAS_TURISTICAS OT
        LEFT JOIN ESTABLECIMIENTOS E ON OT.ID_ESTABLECIMIENTO = E.ID_ESTABLECIMIENTO
        LEFT JOIN PRESTADORES P ON OT.ID_PRESTADOR = P.ID_PRESTADOR
        LEFT JOIN DOMICILIOS D ON OT.ID_DOMICILIO = D.ID_DOMICILIO
        LEFT JOIN CAMBIOS_ESTADO_OFERTA CEO ON CEO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
			AND CEO.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_OFERTA WHERE ID_OFERTA = OT.ID_OFERTA_TURISTICA)
        WHERE OT.ID_TIPO_OFERTA = 1
        AND CEO.ID_ESTADO = 4 ';  -- Siempre cierto para facilitar agregar condiciones dinámicas

    -- Agregamos condiciones según los filtros recibidos

    IF I_ID_SUB_TIPO_OFERTA IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND OT.ID_SUB_TIPO_OFERTA = ', I_ID_SUB_TIPO_OFERTA);
    END IF;

    IF I_ID_ESTABLECIMIENTO IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND OT.ID_ESTABLECIMIENTO = ', I_ID_ESTABLECIMIENTO);
    END IF;

    IF I_TX_OFERTA IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND OT.TX_OFERTA LIKE ', QUOTE(CONCAT('%', I_TX_OFERTA, '%')));
    END IF;

    IF I_ID_PROVINCIA IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND D.ID_PROVINCIA = ', I_ID_PROVINCIA);
    END IF;

    IF I_ID_DEPARTAMENTO IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND D.ID_DEPARTAMENTO = ', I_ID_DEPARTAMENTO);
    END IF;

    IF I_ID_LOCALIDAD IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND D.ID_LOCALIDAD = ', I_ID_LOCALIDAD);
    END IF;

  /*  IF I_TX_BARRIO IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND D.TX_BARRIO LIKE ', QUOTE(CONCAT('%', I_TX_BARRIO, '%')));
    END IF; */

    IF I_TX_CALLE IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND D.TX_CALLE LIKE ', QUOTE(CONCAT('%', I_TX_CALLE, '%')));
    END IF;

    IF I_MIN_MONTO_GARANTIA IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND OT.MONTO_GARANTIA >= ', I_MIN_MONTO_GARANTIA);
    END IF;

    IF I_MAX_MONTO_GARANTIA IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND OT.MONTO_GARANTIA <= ', I_MAX_MONTO_GARANTIA);
    END IF;

    IF I_MIN_DIAS_ESTADIA IS NOT NULL THEN
        SET @V_SQL := CONCAT(@V_SQL, ' AND OT.MIN_DIAS_ESTADIA >= ', I_MIN_DIAS_ESTADIA);
    END IF;

    -- Agregamos la parte de orden y paginación
    SET @V_SQL := CONCAT(@V_SQL, ' ORDER BY OT.FEC_ALTA DESC LIMIT ', I_PageSize, ' OFFSET ', OffsetValue);

    -- Ejecutamos la consulta
  --   SELECT @V_SQL;
	PREPARE CONSULTA FROM @V_SQL;
    EXECUTE CONSULTA;
    DEALLOCATE PREPARE CONSULTA;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
