CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_AUTH_TIPO_PAGO`(
    IN I_ID_USUARIO VARCHAR(36),
    IN I_ID_OFERTA VARCHAR(36)
)
BEGIN
    SELECT 
        ot.ID_TIPO_PAGO_ANTICIPADO AS id_tipo_pago_anticipado,
        dmp.EXPIRACION AS fecha_expiracion_autorizacion_mp
        
    FROM OFERTAS_TURISTICAS ot
    LEFT JOIN PRESTADORES p on p.ID_PRESTADOR = ot.ID_PRESTADOR
    LEFT JOIN USUARIOS u ON u.ID_USUARIO = p.ID_USUARIO
    LEFT JOIN DATOS_MP_USUARIO dmp ON dmp.ID_USUARIO = u.ID_USUARIO
    WHERE u.ID_USUARIO = I_ID_USUARIO
	AND ot.ID_OFERTA_TURISTICA = I_ID_OFERTA;
    
END ;;
DELIMITER ;
