CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_OBT_DATOS_OFERTA_TURISTICA`(IN I_ID_OFERTA VARCHAR(36))
BEGIN
SELECT
    ot.TX_OFERTA AS nombre,
    ot.TX_DESCRIPCION AS descripcion,
    e.ID_ESTADO AS id_estado,
    e.TX_ESTADO AS estado
FROM
    OFERTAS_TURISTICAS ot
    LEFT JOIN CAMBIOS_ESTADO_OFERTA ceo ON ot.ID_OFERTA_TURISTICA = ceo.ID_OFERTA
    AND ceo.ID_CAMBIO_ESTADO = (
        SELECT
            MAX(ID_CAMBIO_ESTADO)
        FROM
            CAMBIOS_ESTADO_OFERTA
        WHERE
            ID_OFERTA = ceo.ID_OFERTA
    )
    LEFT JOIN ESTADOS e ON ceo.ID_ESTADO = e.ID_ESTADO
WHERE
    ot.ID_OFERTA_TURISTICA = I_ID_OFERTA;
    
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
