CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_DATOS_PREFERENCIA`(
    IN I_ID_RESERVA VARCHAR(36)
)
BEGIN
    DECLARE V_ID_USUARIO_PRESTADOR VARCHAR(36);
    DECLARE V_ID_OFERTA VARCHAR(36);
	DECLARE V_ID_TIPO_OFERTA INT;
    DECLARE V_ID_SUB_TIPO_OFERTA INT;
    
    SELECT ot.ID_OFERTA_TURISTICA, p.ID_USUARIO, ot.ID_TIPO_OFERTA, ot.ID_SUB_TIPO_OFERTA
    INTO V_ID_OFERTA, V_ID_USUARIO_PRESTADOR, V_ID_TIPO_OFERTA, V_ID_SUB_TIPO_OFERTA
    FROM RESERVAS r
    LEFT JOIN OFERTAS_TURISTICAS ot on r.ID_OFERTA = ot.ID_OFERTA_TURISTICA
    LEFT JOIN PRESTADORES p on p.ID_PRESTADOR = ot.ID_PRESTADOR
    WHERE ID_RESERVA = I_ID_RESERVA;
    
    IF V_ID_TIPO_OFERTA = 1 AND V_ID_SUB_TIPO_OFERTA = 1
    THEN

		SELECT
		dr.ID_DETALLE_RESERVA AS id_detalle_reserva,
        ot.TX_OFERTA AS titulo,
		td.TX_TIPO_DETALLE AS descripcion,
		dr.PRECIO_UNITARIO	AS precio_unitario,
		dr.CANTIDAD	AS cantidad
		FROM DETALLE_RESERVA dr
        LEFT JOIN RESERVAS r ON dr.ID_RESERVA = r.ID_RESERVA
		LEFT JOIN TIPOS_DETALLE td ON td.ID_TIPO_DETALLE = dr.ID_TIPO_DETALLE
		LEFT JOIN OFERTAS_TURISTICAS ot on td.ID_OFERTA = ot.ID_OFERTA_TURISTICA
        WHERE dr.ID_RESERVA = I_ID_RESERVA;
        
		SELECT TX_ACCESS_TOKEN AS access_token,
				TX_PUBLIC_KEY AS pk_mp
		FROM DATOS_MP_USUARIO
		WHERE ID_USUARIO = V_ID_USUARIO_PRESTADOR;
        
		SELECT DISTINCT
		u.TX_NOMBRE AS nombre_comprador,
        u.TX_APELLIDO AS apellido_comprador,
        tdi.TX_TIPO_DOCUMENTO_IDENTIDAD AS tipo_documento,
        u.NRO_DOCUMENTO_IDENTIDAD AS documento,
        u.TX_MAIL AS mail,
        ot.ID_TIPO_OFERTA AS id_tipo_oferta
        FROM DETALLE_RESERVA dr
        LEFT JOIN RESERVAS r ON dr.ID_RESERVA = r.ID_RESERVA
        LEFT JOIN TURISTAS t ON t.ID_TURISTA = r.ID_TURISTA
        LEFT JOIN USUARIOS u ON u.ID_USUARIO = t.ID_USUARIO
        LEFT JOIN TIPOS_DOCUMENTO_IDENTIDAD tdi ON tdi.ID_TIPO_DOCUMENTO_IDENTIDAD = u.ID_TIPO_DOCUMENTO_IDENTIDAD
		LEFT JOIN TIPOS_DETALLE td ON td.ID_TIPO_DETALLE = dr.ID_TIPO_DETALLE
		LEFT JOIN OFERTAS_TURISTICAS ot on td.ID_OFERTA = ot.ID_OFERTA_TURISTICA
        WHERE dr.ID_RESERVA = I_ID_RESERVA;
        
    
    ELSEIF V_ID_TIPO_OFERTA = 2
	THEN
	
        SELECT DISTINCT
		dr.ID_DETALLE_RESERVA AS id_detalle_reserva,
        ot.TX_OFERTA AS titulo,
		te.TX_TIPO_ENTRADA AS descripcion,
		dr.PRECIO_UNITARIO	AS precio_unitario,
		dr.CANTIDAD	AS cantidad
		FROM DETALLE_RESERVA dr
		LEFT JOIN TIPOS_ENTRADA_X_OFERTA te ON te.ID_TIPO_ENTRADA = dr.ID_TIPO_ENTRADA
		LEFT JOIN OFERTAS_TURISTICAS ot on te.ID_OFERTA = ot.ID_OFERTA_TURISTICA
        WHERE dr.ID_RESERVA = I_ID_RESERVA;
        
		SELECT TX_ACCESS_TOKEN AS access_token,
				TX_PUBLIC_KEY AS pk_mp
		FROM DATOS_MP_USUARIO
		WHERE ID_USUARIO = V_ID_USUARIO_PRESTADOR;
		
        SELECT
		u.TX_NOMBRE AS nombre_comprador,
        u.TX_APELLIDO AS apellido_comprador,
        tdi.TX_TIPO_DOCUMENTO_IDENTIDAD AS tipo_documento,
        u.NRO_DOCUMENTO_IDENTIDAD AS documento,
        u.TX_MAIL AS mail,
        ot.ID_TIPO_OFERTA AS id_tipo_oferta
        FROM DETALLE_RESERVA dr
        LEFT JOIN RESERVAS r ON dr.ID_RESERVA = r.ID_RESERVA
        LEFT JOIN TURISTAS t ON t.ID_TURISTA = r.ID_TURISTA
        LEFT JOIN USUARIOS u ON u.ID_USUARIO = t.ID_USUARIO
        LEFT JOIN TIPOS_DOCUMENTO_IDENTIDAD tdi ON tdi.ID_TIPO_DOCUMENTO_IDENTIDAD = u.ID_TIPO_DOCUMENTO_IDENTIDAD
		LEFT JOIN TIPOS_DETALLE td ON td.ID_TIPO_DETALLE = dr.ID_TIPO_DETALLE
		LEFT JOIN OFERTAS_TURISTICAS ot on td.ID_OFERTA = ot.ID_OFERTA_TURISTICA
        WHERE dr.ID_RESERVA = I_ID_RESERVA;
        
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
