CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_DATOS_USUARIO`(
	IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
	SELECT
			U.ID_USUARIO 	AS id_usuario,
            U.TX_MAIL		AS mail,
			U.TX_NOMBRE		AS nombre,
			U.TX_APELLIDO	AS apellido
		FROM USUARIOS U
		WHERE U.FEC_BAJA IS NULL
		AND U.ID_USUARIO = I_ID_USUARIO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
