CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_DATOS_USUARIO_AUTORIZADO`(
    IN I_CODIGO_RANDOM VARCHAR(100)
)
BEGIN
    DECLARE V_ID_USUARIO VARCHAR(36);
    DECLARE V_FEC_ALTA BIGINT;

    -- Obtener datos del usuario autorizado
    SELECT ID_USUARIO AS id_usuario,
			FEC_ALTA AS fecha_creacion
    INTO V_ID_USUARIO, V_FEC_ALTA
    FROM DATOS_MP_USUARIO
    WHERE TX_CODIGO_RANDOM = I_CODIGO_RANDOM;

    -- Verificar si se encontró algún resultado
    IF V_ID_USUARIO IS NULL THEN
        SELECT 'error' AS resultado, 'No se encontraron datos para el código proporcionado' AS descripcion;
    ELSE
        SELECT 'ok' AS resultado, 'Datos obtenidos exitosamente' AS descripcion, V_ID_USUARIO AS id_usuario, V_FEC_ALTA AS fecha_creacion;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
