CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_DATOS_USUARIO_X_PERFIL`(
	IN I_ID_USUARIO VARCHAR(36),
    IN I_ID_PERFIL INT
)
BEGIN
	IF I_ID_PERFIL = 1
    THEN
		SELECT
			U.TX_NOMBRE		AS nombre,
			U.TX_APELLIDO	AS apellido,
            U.TX_MAIL		AS mail,
        --    T.ID_IDIOMA,
            I.TX_IDIOMA		AS idioma,
		-- 	T.ID_GENERO,
			G.TX_GENERO		AS genero
		FROM USUARIOS U
		INNER JOIN TURISTAS T ON U.ID_USUARIO = T.ID_USUARIO
		INNER JOIN IDIOMAS I ON T.ID_IDIOMA = I.ID_IDIOMA
		INNER JOIN GENEROS G ON T.ID_GENERO = G.ID_GENERO
		WHERE U.FEC_BAJA IS NULL
		AND U.ID_USUARIO = I_ID_USUARIO;
	
    ELSEIF  I_ID_PERFIL = 2
    THEN
		SELECT
			U.TX_NOMBRE		AS nombre,
			U.TX_APELLIDO	AS apellido,
            U.TX_MAIL		AS mail,
            P.TX_RAZON_SOCIAL	AS razon_social
		FROM USUARIOS U
		INNER JOIN PRESTADORES P ON U.ID_USUARIO = P.ID_USUARIO
		WHERE U.FEC_BAJA IS NULL
		AND U.ID_USUARIO = I_ID_USUARIO;
        
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
