CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_DETALLE_OFERTA_X_FILTRO`(
    IN I_ID_OFERTA VARCHAR(36), -- NOT NULL
    IN I_MIN_MONTO DECIMAL(20,2),
    IN I_MAX_MONTO DECIMAL(20,2),
    IN I_NOCHES_ESTADIA INT,
    IN I_FEC_DESDE DATE,  -- NOT NULL           
    IN I_FEC_HASTA DATE,     -- NOT NULL        
    IN I_CANTIDAD_PERSONAS INT       -- NOT NULL
)
BEGIN
	DECLARE V_ID_TIPO_OFERTA VARCHAR(36);
	DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN
        -- Manejo de errores
        ROLLBACK;
    END;
    
    -- Crear la tabla temporal para guardar ID_TIPO_DETALLE
    CREATE TABLE IF NOT EXISTS tmp_tipo_detalle (
        ID_TIPO_DETALLE VARCHAR(36)
    );
    
    -- Limpiar la tabla temporal antes de usarla
    TRUNCATE TABLE tmp_tipo_detalle;
    
    SELECT ID_TIPO_OFERTA
    INTO V_ID_TIPO_OFERTA
    FROM OFERTAS_TURISTICAS
    WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA;
    
    -- Primer filtro basado en los parámetros ingresados
    IF V_ID_TIPO_OFERTA = 1 THEN
            
		INSERT INTO tmp_tipo_detalle (ID_TIPO_DETALLE)
        SELECT DISTINCT TD.ID_TIPO_DETALLE
        FROM OFERTAS_TURISTICAS OT
        LEFT JOIN SUB_TIPO_OFERTA ST ON ST.ID_SUB_TIPO_OFERTA = OT.ID_SUB_TIPO_OFERTA
        LEFT JOIN TARIFAS_X_OFERTA TXO ON TXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
        LEFT JOIN TIPOS_DETALLE TD ON TXO.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE
        LEFT JOIN ESTABLECIMIENTOS E ON OT.ID_ESTABLECIMIENTO = E.ID_ESTABLECIMIENTO
        LEFT JOIN PRESTADORES P ON OT.ID_PRESTADOR = P.ID_PRESTADOR
        LEFT JOIN DOMICILIOS D ON OT.ID_DOMICILIO = D.ID_DOMICILIO
        LEFT JOIN LOCALIDADES L ON L.ID_LOCALIDAD = D.ID_LOCALIDAD
        LEFT JOIN DOMICILIOS DEST ON E.ID_DOMICILIO = DEST.ID_DOMICILIO
        LEFT JOIN LOCALIDADES LEST ON LEST.ID_LOCALIDAD = DEST.ID_LOCALIDAD
        LEFT JOIN PLAZAS_X_TIPO_DETALLE PTD ON PTD.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE
        LEFT JOIN TIPOS_CAMA TC ON TC.ID_TIPO_CAMA = PTD.ID_TIPO_CAMA
        LEFT JOIN IMAGENES_X_OFERTA IXO ON IXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
        LEFT JOIN CAMBIOS_ESTADO_OFERTA CEO ON CEO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
            AND CEO.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_OFERTA WHERE ID_OFERTA = OT.ID_OFERTA_TURISTICA)
        WHERE CEO.ID_ESTADO = 4
			AND OT.ID_OFERTA_TURISTICA = I_ID_OFERTA
            AND PTD.FEC_BAJA IS NULL
            AND OT.ID_TIPO_OFERTA = 1 
            AND (I_MIN_MONTO IS NULL OR TXO.MONTO_TARIFA >= I_MIN_MONTO)
			AND (I_MAX_MONTO IS NULL OR TXO.MONTO_TARIFA <= I_MAX_MONTO)
            AND TXO.FEC_DESDE <= I_FEC_DESDE 
            AND TXO.FEC_HASTA >= I_FEC_HASTA
            AND OT.MIN_DIAS_ESTADIA <= I_NOCHES_ESTADIA
        GROUP BY OT.ID_OFERTA_TURISTICA, TXO.ID_TIPO_DETALLE;
        
        -- Detalles de la oferta turística
        SELECT 
            ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
            ot.TX_OFERTA AS nombre,
            ot.TX_DESCRIPCION AS descripcion,
            ot.ID_TIPO_OFERTA AS id_tipo_oferta,
            tipo.TX_TIPO_OFERTA AS tipo_oferta,
            ot.ID_SUB_TIPO_OFERTA AS id_sub_tipo_oferta,
            sto.TX_SUB_TIPO_OFERTA AS sub_tipo_oferta,
            ot.ID_POLITICA_CANCELACION AS id_politica_cancelacion,
            ot.PLAZO_DIAS_CANCELACION AS plazo_dias_cancelacion,
            ot.BL_SOLICITA_GARANTIA AS bl_solicita_garantia,
            ot.MONTO_GARANTIA AS monto_garantia,
            ot.ID_TIPO_PAGO_ANTICIPADO AS id_tipo_pago_anticipado,
            ot.PORCENTAJE_PAGO_ANTICIPADO AS porcentaje_pago_anticipado,
            ot.MIN_DIAS_ESTADIA AS min_dias_estadia
        FROM OFERTAS_TURISTICAS ot
        LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
        LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
        WHERE ot.ID_OFERTA_TURISTICA = I_ID_OFERTA;

        -- Métodos de pago por oferta
        SELECT 
            mpxo.ID_METODO_PAGO_X_OFERTA AS id_metodo_pago_oferta,
            mpxo.ID_METODO_PAGO AS id_metodo_pago,
            mp.N_METODO_PAGO AS metodo_pago
        FROM METODOS_PAGO_X_OFERTA mpxo
        LEFT JOIN METODOS_PAGO mp ON mp.ID_METODO_PAGO = mpxo.ID_METODO_PAGO
        WHERE mpxo.ID_OFERTA = I_ID_OFERTA
        AND mpxo.FEC_BAJA IS NULL;

        -- Características por oferta
        SELECT 
            cxo.ID_CARACTERISTICA_X_OFERTA AS id_caracteristica_oferta,
            c.ID_CARACTERISTICA AS id_caracteristica,
            c.TX_CARACTERISTICA AS caracteristica,
            c.ID_AMBITO AS id_ambito,
            ac.TX_AMBITO AS ambito
        FROM CARACTERISTICAS_X_OFERTA cxo
        LEFT JOIN CARACTERISTICAS c ON c.ID_CARACTERISTICA = cxo.ID_CARACTERISTICA
        LEFT JOIN AMBITOS_CARACTERISTICAS ac ON ac.ID_AMBITO = c.ID_AMBITO
        WHERE cxo.ID_OFERTA_TURISTICA = I_ID_OFERTA
        AND ac.ID_AMBITO IN (1,2,3,4);

        -- Observaciones por oferta
        SELECT 
            oxo.ID_OBSERVACION_X_OFERTA AS id_observacion_oferta,
            oxo.TX_OBSERVACION AS observacion,
            tipob.ID_TIPO_OBSERVACION AS id_tipo_observacion,
            tipob.TX_TIPO_OBSERVACION AS tipo_observacion
        FROM OBSERVACIONES_X_OFERTA oxo
        LEFT JOIN TIPOS_OBSERVACION tipob ON tipob.ID_TIPO_OBSERVACION = oxo.ID_TIPO_OBSERVACION
        WHERE oxo.ID_OFERTA = I_ID_OFERTA
        AND oxo.FEC_BAJA IS NULL;

        -- Horarios de check-in y check-out por oferta
        SELECT 
            h.ID_HORARIO AS id_horario,
            h.CHECK_IN_HORA AS check_in_hora,
            h.CHECK_IN_MINUTO AS check_in_minuto,
            h.CHECK_OUT_HORA AS check_out_hora,
            h.CHECK_OUT_MINUTO AS check_out_minuto,
            h.APLICA_LUNES AS aplica_lunes,
            h.APLICA_MARTES AS aplica_martes,
            h.APLICA_MIERCOLES AS aplica_miercoles,
            h.APLICA_JUEVES AS aplica_jueves,
            h.APLICA_VIERNES AS aplica_viernes,
            h.APLICA_SABADO AS aplica_sabado,
            h.APLICA_DOMINGO AS aplica_domingo,
            h.CUPO_MAXIMO AS cupo_maximo,
            h.CUPO_ACTUAL AS cupo_actual,
            h.BL_SIN_CUPO AS sin_cupo
        FROM HORARIOS_CHECK h
        WHERE h.ID_OFERTA = I_ID_OFERTA
        AND h.FEC_BAJA IS NULL;
        
        SELECT 
				coalesce(d.TX_CALLE,de.TX_CALLE) AS nombre_calle,
				coalesce(d.TX_BARRIO,de.TX_BARRIO) AS nombre_barrio,
				coalesce(d.ID_LOCALIDAD,de.ID_LOCALIDAD) AS id_localidad,
				coalesce(l.TX_LOCALIDAD,le.TX_LOCALIDAD) AS localidad,
				coalesce(d.ID_DEPARTAMENTO,de.ID_DEPARTAMENTO) AS id_departamento,
				coalesce(d.ID_PROVINCIA,de.ID_PROVINCIA) AS id_provincia,
                coalesce(d.TX_LATITUD,de.TX_LATITUD) AS latitud,
                coalesce(d.TX_LONGITUD,de.TX_LONGITUD) AS longitud,
                coalesce(d.TX_ALTURA, de.TX_ALTURA) AS numero,
				coalesce(d.TX_CODIGO_POSTAL,de.TX_CODIGO_POSTAL) AS codigo_postal,
				coalesce(d.TX_LOTE,de.TX_LOTE) AS lote,
				coalesce(d.TX_MANZANA,de.TX_MANZANA) AS manzana,
				coalesce(d.TX_PISO,de.TX_PISO) AS piso,
				coalesce(d.TX_TORRE,de.TX_TORRE) AS torre,
				CASE WHEN COALESCE(d.TX_ALTURA, de.TX_ALTURA) = 'S/N' THEN true 
				ELSE false 
				END AS sin_numero,
				oxo.ID_OBSERVACION_X_OFERTA AS id_observacion_oferta,
				oxo.TX_OBSERVACION AS observacion
        FROM OFERTAS_TURISTICAS o
        LEFT JOIN ESTABLECIMIENTOS e on o.ID_ESTABLECIMIENTO = e.ID_ESTABLECIMIENTO
        LEFT JOIN DOMICILIOS d ON o.ID_DOMICILIO = d.ID_DOMICILIO
		LEFT JOIN LOCALIDADES l ON l.ID_LOCALIDAD = d.ID_LOCALIDAD
		LEFT JOIN DOMICILIOS de ON e.ID_DOMICILIO = de.ID_DOMICILIO
		LEFT JOIN LOCALIDADES le ON le.ID_LOCALIDAD = de.ID_LOCALIDAD
        LEFT JOIN OBSERVACIONES_X_OFERTA oxo ON oxo.ID_OFERTA = o.ID_OFERTA_TURISTICA
			AND oxo.ID_TIPO_OBSERVACION = 7
        WHERE o.ID_OFERTA_TURISTICA = I_ID_OFERTA
        AND o.FEC_BAJA IS NULL
        AND d.FEC_BAJA IS NULL
		AND de.FEC_BAJA IS NULL
		AND oxo.FEC_BAJA IS NULL;
        
        SELECT
		ID_IMAGEN_X_OFERTA as id_imagen,
        TX_RUTA_ARCHIVO as ruta_imagen
		FROM IMAGENES_X_OFERTA IXO
		WHERE IXO.FEC_BAJA IS NULL
		AND IXO.ID_OFERTA = I_ID_OFERTA;
        
        -- ------------------------------------ INFO DETALLES
        SELECT DISTINCT
        TD.ID_TIPO_DETALLE AS id_tipo_detalle, 
        TD.TX_TIPO_DETALLE AS tipo_detalle,
        TD.CANTIDAD AS cantidad,
        TD.CANTIDAD_BAÑOS AS cantidad_baños,
        TD.BL_BAÑO_COMPARTIDO AS bl_baño_compartido,
        TD.BL_BAÑO_ADAPTADO AS bl_baño_adaptado
		FROM TIPOS_DETALLE TD
		WHERE TD.ID_TIPO_DETALLE in (select ID_TIPO_DETALLE from tmp_tipo_detalle)
		AND TD.ID_OFERTA = I_ID_OFERTA
		AND TD.FEC_BAJA IS NULL;

    -- Segundo SELECT: Datos de Plazas por Tipo Detalle
		SELECT DISTINCT
			TD.ID_TIPO_DETALLE as id_tipo_detalle,
			PTD.ID_PLAZA_X_TIPO_DETALLE AS id_plaza_x_tipo_detalle,
			PTD.ID_TIPO_CAMA AS id_tipo_cama,
			TC.TX_TIPO_CAMA AS nombre_cama,
			PTD.CANTIDAD_CAMAS AS cantidad
		FROM TIPOS_DETALLE TD
		INNER JOIN PLAZAS_X_TIPO_DETALLE PTD ON TD.ID_TIPO_DETALLE = PTD.ID_TIPO_DETALLE
		INNER JOIN TIPOS_CAMA TC ON TC.ID_TIPO_CAMA = PTD.ID_TIPO_CAMA
		WHERE TD.ID_TIPO_DETALLE in (select ID_TIPO_DETALLE from tmp_tipo_detalle)
        AND TD.ID_OFERTA = I_ID_OFERTA
		AND TD.FEC_BAJA IS NULL
		AND PTD.FEC_BAJA IS NULL;

		-- Tercer SELECT: Datos de Características por Tipo Detalle, incluyendo el ámbito de características
		SELECT DISTINCT
			TD.ID_TIPO_DETALLE as id_tipo_detalle,
			CTD.ID_CARACTERISTICA_X_DETALLE AS id_caracteristica_x_detalle,
			CTD.ID_CARACTERISTICA AS id_caracteristica,
			C.TX_CARACTERISTICA AS caracteristica,
			AC.TX_AMBITO AS ambito
		FROM TIPOS_DETALLE TD
		INNER JOIN CARACTERISTICAS_X_TIPO_DETALLE CTD ON TD.ID_TIPO_DETALLE = CTD.ID_TIPO_DETALLE
		INNER JOIN CARACTERISTICAS C ON CTD.ID_CARACTERISTICA = C.ID_CARACTERISTICA
		INNER JOIN AMBITOS_CARACTERISTICAS AC ON C.ID_AMBITO = AC.ID_AMBITO
		WHERE TD.ID_OFERTA = I_ID_OFERTA
		AND TD.ID_TIPO_DETALLE in (select ID_TIPO_DETALLE from tmp_tipo_detalle)
		AND TD.FEC_BAJA IS NULL
		AND CTD.FEC_BAJA IS NULL;
        
        SELECT
			ID_IMAGEN_X_TIPO_DETALLE as id_imagen_x_tipo_detalle,
            ID_TIPO_DETALLE as id_tipo_detalle,
			TX_RUTA_ARCHIVO as ruta_imagen
		FROM IMAGENES_X_TIPOS_DETALLE IXTD
		WHERE IXTD.FEC_BAJA IS NULL
        AND IXTD.ID_TIPO_DETALLE in (select ID_TIPO_DETALLE from tmp_tipo_detalle);
        
		SELECT 
        TXO.ID_TARIFA_X_OFERTA AS id_tarifa,
        OT.ID_OFERTA_TURISTICA AS id_oferta,
        OT.TX_OFERTA AS nombre_oferta,
        TD.ID_TIPO_DETALLE AS id_tipo_detalle,
        TD.TX_TIPO_DETALLE AS nombre_tipo_detalle,
        TE.ID_TIPO_ENTRADA AS id_tipo_entrada,
		TE.TX_TIPO_ENTRADA AS nombre_tipo_entrada,
		TE.TX_DESCRIPCION AS descripcion_entrada,
        TXO.MONTO_TARIFA AS monto_tarifa,
        TXO.FEC_DESDE AS fecha_desde,
        TXO.FEC_HASTA AS fecha_hasta,
        TXO.BL_GRATIS AS bl_gratis,
        TXO.ID_HORARIO AS id_horario
        
		FROM TARIFAS_X_OFERTA TXO
		LEFT JOIN OFERTAS_TURISTICAS OT ON OT.ID_OFERTA_TURISTICA = TXO.ID_OFERTA
		LEFT JOIN TIPOS_DETALLE TD ON TD.ID_TIPO_DETALLE = TXO.ID_TIPO_DETALLE
		LEFT JOIN TIPOS_ENTRADA_X_OFERTA TE ON TE.ID_TIPO_ENTRADA = TXO.ID_TIPO_ENTRADA
		LEFT JOIN HORARIOS_CHECK HC ON HC.ID_HORARIO = TXO.ID_HORARIO
		WHERE TXO.ID_TIPO_DETALLE in (select ID_TIPO_DETALLE from tmp_tipo_detalle)
		AND TE.FEC_BAJA IS NULL
		AND TD.FEC_BAJA IS NULL
		AND HC.FEC_BAJA IS NULL
		AND TXO.FEC_BAJA IS NULL
		ORDER BY TXO.FEC_DESDE; 
        
	DROP TABLE IF EXISTS tmp_tipo_detalle;
    
    -- Primer filtro basado en los parámetros ingresados
    ELSEIF V_ID_TIPO_OFERTA = 2 THEN
            
		INSERT INTO tmp_tipo_detalle (ID_TIPO_DETALLE)
        SELECT DISTINCT TD.ID_TIPO_DETALLE
        FROM OFERTAS_TURISTICAS OT
        LEFT JOIN SUB_TIPO_OFERTA ST ON ST.ID_SUB_TIPO_OFERTA = OT.ID_SUB_TIPO_OFERTA
        LEFT JOIN TARIFAS_X_OFERTA TXO ON TXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
        LEFT JOIN TIPOS_DETALLE TD ON TXO.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE
        LEFT JOIN ESTABLECIMIENTOS E ON OT.ID_ESTABLECIMIENTO = E.ID_ESTABLECIMIENTO
        LEFT JOIN PRESTADORES P ON OT.ID_PRESTADOR = P.ID_PRESTADOR
        LEFT JOIN DOMICILIOS D ON OT.ID_DOMICILIO = D.ID_DOMICILIO
        LEFT JOIN LOCALIDADES L ON L.ID_LOCALIDAD = D.ID_LOCALIDAD
        LEFT JOIN DOMICILIOS DEST ON E.ID_DOMICILIO = DEST.ID_DOMICILIO
        LEFT JOIN LOCALIDADES LEST ON LEST.ID_LOCALIDAD = DEST.ID_LOCALIDAD
        LEFT JOIN IMAGENES_X_OFERTA IXO ON IXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
        LEFT JOIN CAMBIOS_ESTADO_OFERTA CEO ON CEO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
            AND CEO.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_OFERTA WHERE ID_OFERTA = OT.ID_OFERTA_TURISTICA)
        WHERE CEO.ID_ESTADO = 4
			AND OT.ID_OFERTA_TURISTICA = I_ID_OFERTA
            AND OT.ID_TIPO_OFERTA = 2
            AND (I_MIN_MONTO IS NULL OR TXO.MONTO_TARIFA >= I_MIN_MONTO)
			AND (I_MAX_MONTO IS NULL OR TXO.MONTO_TARIFA <= I_MAX_MONTO)
            AND TXO.FEC_DESDE <= I_FEC_DESDE  
            AND TXO.FEC_HASTA >= I_FEC_HASTA
        GROUP BY OT.ID_OFERTA_TURISTICA, TXO.ID_TIPO_DETALLE;
        
        -- Detalles de la oferta turística
        SELECT ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        ot.TX_OFERTA AS nombre,
        ot.TX_DESCRIPCION AS descripcion,
        ot.ID_TIPO_OFERTA AS id_tipo_oferta,
        tipo.TX_TIPO_OFERTA AS tipo_oferta,
        ot.ID_SUB_TIPO_OFERTA AS id_sub_tipo_oferta,
        sto.TX_SUB_TIPO_OFERTA AS sub_tipo_oferta,
        ot.ID_SUB_CATEGORIA AS id_sub_categoria,
        sco.TX_SUB_CATEGORIA AS sub_categoria,
        ot.ID_POLITICA_CANCELACION AS id_politica_cancelacion,
        ot.PLAZO_DIAS_CANCELACION AS plazo_dias_cancelacion,
        ot.BL_SOLICITA_GARANTIA AS bl_solicita_garantia,
        ot.MONTO_GARANTIA AS monto_garantia,
        ot.ID_TIPO_PAGO_ANTICIPADO AS id_tipo_pago_anticipado,
        ot.PORCENTAJE_PAGO_ANTICIPADO AS porcentaje_pago_anticipado,
        ot.DURACION_HS AS duracion_horas,
        ot.DISTANCIA_KM AS distancia_km,
        ot.ID_DIFICULTAD AS id_dificultad,
		da.TX_DIFICULTAD AS dificultad,
        ot.TX_REQUISITOS AS requisitos,
        ot.BL_CON_GUIA AS bl_con_guia
    FROM OFERTAS_TURISTICAS ot
    LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
    LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
    LEFT JOIN SUB_CATEGORIA_OFERTA sco ON ot.ID_SUB_CATEGORIA = sco.ID_SUB_CATEGORIA
    LEFT JOIN DIFICULTAD_ACTIVIDAD da ON ot.ID_DIFICULTAD = da.ID_DIFICULTAD
	WHERE ot.ID_OFERTA_TURISTICA = I_ID_OFERTA;

        -- Métodos de pago por oferta
        SELECT 
            mpxo.ID_METODO_PAGO_X_OFERTA AS id_metodo_pago_oferta,
            mpxo.ID_METODO_PAGO AS id_metodo_pago,
            mp.N_METODO_PAGO AS metodo_pago
        FROM METODOS_PAGO_X_OFERTA mpxo
        LEFT JOIN METODOS_PAGO mp ON mp.ID_METODO_PAGO = mpxo.ID_METODO_PAGO
        WHERE mpxo.ID_OFERTA = I_ID_OFERTA
        AND mpxo.FEC_BAJA IS NULL;

        -- Horarios de check-in y check-out por oferta
        SELECT 
            h.ID_HORARIO AS id_horario,
            h.CHECK_IN_HORA AS check_in_hora,
            h.CHECK_IN_MINUTO AS check_in_minuto,
            h.CHECK_OUT_HORA AS check_out_hora,
            h.CHECK_OUT_MINUTO AS check_out_minuto,
            h.APLICA_LUNES AS aplica_lunes,
            h.APLICA_MARTES AS aplica_martes,
            h.APLICA_MIERCOLES AS aplica_miercoles,
            h.APLICA_JUEVES AS aplica_jueves,
            h.APLICA_VIERNES AS aplica_viernes,
            h.APLICA_SABADO AS aplica_sabado,
            h.APLICA_DOMINGO AS aplica_domingo,
            h.CUPO_MAXIMO AS cupo_maximo,
            h.CUPO_ACTUAL AS cupo_actual,
            h.BL_SIN_CUPO AS sin_cupo
        FROM HORARIOS_CHECK h
        WHERE h.ID_OFERTA = I_ID_OFERTA
        AND h.FEC_BAJA IS NULL;
        
        SELECT 
				coalesce(d.TX_CALLE,de.TX_CALLE) AS nombre_calle,
				coalesce(d.TX_BARRIO,de.TX_BARRIO) AS nombre_barrio,
				coalesce(d.ID_LOCALIDAD,de.ID_LOCALIDAD) AS id_localidad,
				coalesce(l.TX_LOCALIDAD,le.TX_LOCALIDAD) AS localidad,
				coalesce(d.ID_DEPARTAMENTO,de.ID_DEPARTAMENTO) AS id_departamento,
				coalesce(d.ID_PROVINCIA,de.ID_PROVINCIA) AS id_provincia,
                coalesce(d.TX_LATITUD,de.TX_LATITUD) AS latitud,
                coalesce(d.TX_LONGITUD,de.TX_LONGITUD) AS longitud,
                coalesce(d.TX_ALTURA, de.TX_ALTURA) AS numero,
				coalesce(d.TX_CODIGO_POSTAL,de.TX_CODIGO_POSTAL) AS codigo_postal,
				coalesce(d.TX_LOTE,de.TX_LOTE) AS lote,
				coalesce(d.TX_MANZANA,de.TX_MANZANA) AS manzana,
				coalesce(d.TX_PISO,de.TX_PISO) AS piso,
				coalesce(d.TX_TORRE,de.TX_TORRE) AS torre,
				CASE WHEN COALESCE(d.TX_ALTURA, de.TX_ALTURA) = 'S/N' THEN true 
				ELSE false 
				END AS sin_numero,
				oxo.ID_OBSERVACION_X_OFERTA AS id_observacion_oferta,
				oxo.TX_OBSERVACION AS observacion
        FROM OFERTAS_TURISTICAS o
        LEFT JOIN ESTABLECIMIENTOS e on o.ID_ESTABLECIMIENTO = e.ID_ESTABLECIMIENTO
        LEFT JOIN DOMICILIOS d ON o.ID_DOMICILIO = d.ID_DOMICILIO
		LEFT JOIN LOCALIDADES l ON l.ID_LOCALIDAD = d.ID_LOCALIDAD
		LEFT JOIN DOMICILIOS de ON e.ID_DOMICILIO = de.ID_DOMICILIO
		LEFT JOIN LOCALIDADES le ON le.ID_LOCALIDAD = de.ID_LOCALIDAD
        LEFT JOIN OBSERVACIONES_X_OFERTA oxo ON oxo.ID_OFERTA = o.ID_OFERTA_TURISTICA
			AND oxo.ID_TIPO_OBSERVACION = 7
        WHERE o.ID_OFERTA_TURISTICA = I_ID_OFERTA
        AND o.FEC_BAJA IS NULL
        AND d.FEC_BAJA IS NULL
		AND de.FEC_BAJA IS NULL
		AND oxo.FEC_BAJA IS NULL;
        
        SELECT
		ID_IMAGEN_X_OFERTA as id_imagen,
        TX_RUTA_ARCHIVO as ruta_imagen
		FROM IMAGENES_X_OFERTA IXO
		WHERE IXO.FEC_BAJA IS NULL
		AND IXO.ID_OFERTA = I_ID_OFERTA;
        
		SELECT 
        TXO.ID_TARIFA_X_OFERTA AS id_tarifa,
        OT.ID_OFERTA_TURISTICA AS id_oferta,
        OT.TX_OFERTA AS nombre_oferta,
        TD.ID_TIPO_DETALLE AS id_tipo_detalle,
        TD.TX_TIPO_DETALLE AS nombre_tipo_detalle,
        TE.ID_TIPO_ENTRADA AS id_tipo_entrada,
		TE.TX_TIPO_ENTRADA AS nombre_tipo_entrada,
		TE.TX_DESCRIPCION AS descripcion_entrada,
        TXO.MONTO_TARIFA AS monto_tarifa,
        TXO.FEC_DESDE AS fecha_desde,
        TXO.FEC_HASTA AS fecha_hasta,
        TXO.BL_GRATIS AS bl_gratis,
        TXO.ID_HORARIO AS id_horario
        
		FROM TARIFAS_X_OFERTA TXO
		LEFT JOIN OFERTAS_TURISTICAS OT ON OT.ID_OFERTA_TURISTICA = TXO.ID_OFERTA
		LEFT JOIN TIPOS_DETALLE TD ON TD.ID_TIPO_DETALLE = TXO.ID_TIPO_DETALLE
		LEFT JOIN TIPOS_ENTRADA_X_OFERTA TE ON TE.ID_TIPO_ENTRADA = TXO.ID_TIPO_ENTRADA
		LEFT JOIN HORARIOS_CHECK HC ON HC.ID_HORARIO = TXO.ID_HORARIO
		WHERE TXO.ID_OFERTA = I_ID_OFERTA
		AND TE.FEC_BAJA IS NULL
		AND TD.FEC_BAJA IS NULL
		AND HC.FEC_BAJA IS NULL
		AND TXO.FEC_BAJA IS NULL
		ORDER BY TXO.FEC_DESDE; 
        
	DROP TABLE IF EXISTS tmp_tipo_detalle;

    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_OBT_DOMICILIO_OFERTA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_DOMICILIO_OFERTA`(
    IN I_ID_OFERTA VARCHAR(36),
    IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
    DECLARE V_USR_ALTA VARCHAR(36);

    -- Obtener el usuario creador de la oferta para validar
    SELECT USR_ALTA INTO V_USR_ALTA
    FROM OFERTAS_TURISTICAS
    WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA;

    -- Validar que el usuario que realiza la solicitud es el creador de la oferta
    IF V_USR_ALTA = I_ID_USUARIO THEN
        -- Seleccionar datos del domicilio asociado a la oferta
        SELECT 
				coalesce(d.TX_CALLE,de.TX_CALLE) AS nombre_calle,
				coalesce(d.TX_BARRIO,de.TX_BARRIO) AS nombre_barrio,
				coalesce(d.ID_LOCALIDAD,de.ID_LOCALIDAD) AS id_localidad,
				coalesce(l.TX_LOCALIDAD,le.TX_LOCALIDAD) AS localidad,
				coalesce(d.ID_DEPARTAMENTO,de.ID_DEPARTAMENTO) AS id_departamento,
				coalesce(d.ID_PROVINCIA,de.ID_PROVINCIA) AS id_provincia,
                coalesce(d.TX_LATITUD,de.TX_LATITUD) AS latitud,
                coalesce(d.TX_LONGITUD,de.TX_LONGITUD) AS longitud,
                coalesce(d.TX_ALTURA, de.TX_ALTURA) AS numero,
				coalesce(d.TX_CODIGO_POSTAL,de.TX_CODIGO_POSTAL) AS codigo_postal,
				coalesce(d.TX_LOTE,de.TX_LOTE) AS lote,
				coalesce(d.TX_MANZANA,de.TX_MANZANA) AS manzana,
				coalesce(d.TX_PISO,de.TX_PISO) AS piso,
				coalesce(d.TX_TORRE,de.TX_TORRE) AS torre,
				CASE WHEN COALESCE(d.TX_ALTURA, de.TX_ALTURA) = 'S/N' THEN true 
				ELSE false 
				END AS sin_numero,
				oxo.ID_OBSERVACION_X_OFERTA AS id_observacion_oferta,
				oxo.TX_OBSERVACION AS observacion
        FROM OFERTAS_TURISTICAS o
        LEFT JOIN ESTABLECIMIENTOS e on o.ID_ESTABLECIMIENTO = e.ID_ESTABLECIMIENTO
        LEFT JOIN DOMICILIOS d ON o.ID_DOMICILIO = d.ID_DOMICILIO
		LEFT JOIN LOCALIDADES l ON l.ID_LOCALIDAD = d.ID_LOCALIDAD
		LEFT JOIN DOMICILIOS de ON e.ID_DOMICILIO = de.ID_DOMICILIO
		LEFT JOIN LOCALIDADES le ON le.ID_LOCALIDAD = de.ID_LOCALIDAD
        LEFT JOIN OBSERVACIONES_X_OFERTA oxo ON oxo.ID_OFERTA = o.ID_OFERTA_TURISTICA
			AND oxo.ID_TIPO_OBSERVACION = 7
        WHERE o.ID_OFERTA_TURISTICA = I_ID_OFERTA
        AND o.FEC_BAJA IS NULL
        AND d.FEC_BAJA IS NULL
		AND de.FEC_BAJA IS NULL
		AND oxo.FEC_BAJA IS NULL;

    ELSE
        -- Si el usuario no es el creador, lanzar un error
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Error: Usuario no autorizado para acceder a este domicilio.';
    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_OBT_ESTADISTICA_TURISTAS` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_ESTADISTICA_TURISTAS`(
    IN I_ID_USUARIO VARCHAR(36),    
    IN I_FEC_INICIO DATE,
    IN I_FEC_FIN DATE
)
BEGIN
    DECLARE TOTAL_TURISTAS INT;
    DECLARE TURISTAS_NUEVOS INT;
    DECLARE TURISTAS_RECURRENTES INT;
    DECLARE V_ID_PRESTADOR VARCHAR(36);
    
	SELECT ID_PRESTADOR
    INTO V_ID_PRESTADOR
    FROM PRESTADORES
    WHERE ID_USUARIO = I_ID_USUARIO;
    
    -- 1. Contar total de turistas con reservas en el período
    SELECT COUNT(DISTINCT ID_TURISTA)
    INTO TOTAL_TURISTAS
    FROM RESERVAS R
    LEFT JOIN OFERTAS_TURISTICAS OT ON R.ID_OFERTA = OT.ID_OFERTA_TURISTICA
    WHERE OT.ID_PRESTADOR = V_ID_PRESTADOR
    AND FEC_INICIO BETWEEN I_FEC_INICIO AND I_FEC_FIN;

    -- 2. Contar turistas nuevos (primera reserva en el período)
    SELECT COUNT(DISTINCT R1.ID_TURISTA)
    INTO TURISTAS_NUEVOS
    FROM RESERVAS R1
    LEFT JOIN OFERTAS_TURISTICAS OT ON R1.ID_OFERTA = OT.ID_OFERTA_TURISTICA
    WHERE OT.ID_PRESTADOR = V_ID_PRESTADOR
    AND R1.FEC_INICIO BETWEEN I_FEC_INICIO AND I_FEC_FIN
	AND (SELECT MIN(R2.FEC_INICIO) FROM RESERVAS R2
		LEFT JOIN OFERTAS_TURISTICAS OT2 ON R2.ID_OFERTA = ID_OFERTA_TURISTICA
		WHERE R2.ID_TURISTA = R1.ID_TURISTA AND OT2.ID_PRESTADOR = V_ID_PRESTADOR) BETWEEN I_FEC_INICIO AND I_FEC_FIN;

    -- 3. Calcular turistas recurrentes
    SET TURISTAS_RECURRENTES = TOTAL_TURISTAS - TURISTAS_NUEVOS;

    -- 4. Calcular porcentajes
    SELECT 
        TURISTAS_NUEVOS AS Cantidad_Turistas_Nuevos,
        (TURISTAS_NUEVOS / TOTAL_TURISTAS * 100) AS Porcentaje_Turistas_Nuevos,
        TURISTAS_RECURRENTES AS Cantidad_Turistas_Recurrentes,
        (TURISTAS_RECURRENTES / TOTAL_TURISTAS * 100) AS Porcentaje_Turistas_Recurrentes;

    -- 5. Top nacionalidades de turistas
    SELECT 
        P.TX_PAIS AS Pais,
        L.TX_LOCALIDAD AS Localidad,
        COUNT(DISTINCT R.ID_TURISTA) AS Cantidad_Turistas
    FROM RESERVAS R
	LEFT JOIN OFERTAS_TURISTICAS OT ON R.ID_OFERTA = OT.ID_OFERTA_TURISTICA
    LEFT JOIN TURISTAS T ON R.ID_TURISTA = T.ID_TURISTA
    LEFT JOIN USUARIOS U ON T.ID_USUARIO = U.ID_USUARIO
    LEFT JOIN DOMICILIOS D ON U.ID_DOMICILIO = D.ID_DOMICILIO
    LEFT JOIN LOCALIDADES L ON D.ID_LOCALIDAD = L.ID_LOCALIDAD
    LEFT JOIN PAISES P ON D.ID_PAIS = P.ID_PAIS
    WHERE R.FEC_INICIO BETWEEN I_FEC_INICIO AND I_FEC_FIN
    AND OT.ID_PRESTADOR = V_ID_PRESTADOR
    GROUP BY P.TX_PAIS, L.TX_LOCALIDAD
    ORDER BY Cantidad_Turistas DESC
    LIMIT 5;

    -- 6. Top provincias y departamentos
    SELECT 
        PR.TX_PROVINCIA AS Provincia,
        DP.TX_DEPARTAMENTO AS Departamento,
        COUNT(DISTINCT R.ID_TURISTA) AS Cantidad_Turistas
    FROM RESERVAS R
	LEFT JOIN OFERTAS_TURISTICAS OT ON R.ID_OFERTA = OT.ID_OFERTA_TURISTICA
    LEFT JOIN TURISTAS T ON R.ID_TURISTA = T.ID_TURISTA
     LEFT JOIN USUARIOS U ON T.ID_USUARIO = U.ID_USUARIO
    LEFT JOIN DOMICILIOS D ON U.ID_DOMICILIO = D.ID_DOMICILIO
    LEFT JOIN LOCALIDADES L ON D.ID_LOCALIDAD = L.ID_LOCALIDAD
    LEFT JOIN DEPARTAMENTOS DP ON D.ID_DEPARTAMENTO = DP.ID_DEPARTAMENTO
    LEFT JOIN PROVINCIAS PR ON D.ID_PROVINCIA = PR.ID_PROVINCIA
    WHERE R.FEC_INICIO BETWEEN I_FEC_INICIO AND I_FEC_FIN
    AND OT.ID_PRESTADOR = V_ID_PRESTADOR
    GROUP BY PR.TX_PROVINCIA, DP.TX_DEPARTAMENTO
    ORDER BY Cantidad_Turistas DESC
    LIMIT 5;
END ;;
DELIMITER ;
