CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_INFO_ACTIVIDAD`(
IN I_ID_OFERTA VARCHAR(36)
)
BEGIN
    -- Primer SELECT: Detalles de la oferta turística
    SELECT 
        ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        ot.TX_OFERTA AS nombre,
        ot.TX_DESCRIPCION AS descripcion,
        ot.ID_TIPO_OFERTA AS id_tipo_oferta,
        tipo.TX_TIPO_OFERTA AS tipo_oferta,
        ot.ID_SUB_TIPO_OFERTA AS id_sub_tipo_oferta,
        sto.TX_SUB_TIPO_OFERTA AS sub_tipo_oferta,
        ot.ID_SUB_CATEGORIA AS id_sub_categoria,
        sco.TX_SUB_CATEGORIA AS sub_categoria,
        ot.ID_POLITICA_CANCELACION AS id_politica_cancelacion,
        ot.PLAZO_DIAS_CANCELACION AS plazo_dias_cancelacion,
        ot.BL_SOLICITA_GARANTIA AS bl_solicita_garantia,
        ot.MONTO_GARANTIA AS monto_garantia,
        ot.ID_TIPO_PAGO_ANTICIPADO AS id_tipo_pago_anticipado,
        ot.PORCENTAJE_PAGO_ANTICIPADO AS porcentaje_pago_anticipado,
        ot.DURACION_HS AS duracion_horas,
        ot.DISTANCIA_KM AS distancia_km,
        ot.ID_DIFICULTAD AS id_dificultad,
		da.TX_DIFICULTAD AS dificultad,
        ot.TX_REQUISITOS AS requisitos,
        ot.BL_CON_GUIA AS bl_con_guia

    FROM OFERTAS_TURISTICAS ot
    LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
    LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
    LEFT JOIN SUB_CATEGORIA_OFERTA sco ON ot.ID_SUB_CATEGORIA = sco.ID_SUB_CATEGORIA
    LEFT JOIN DIFICULTAD_ACTIVIDAD da ON ot.ID_DIFICULTAD = da.ID_DIFICULTAD
    WHERE ot.ID_OFERTA_TURISTICA = I_ID_OFERTA;

    -- Segundo SELECT: Métodos de pago por oferta
    SELECT 
        mpxo.ID_METODO_PAGO_X_OFERTA AS id_metodo_pago_oferta,
        mpxo.ID_METODO_PAGO AS id_metodo_pago,
        mp.N_METODO_PAGO AS metodo_pago
    FROM METODOS_PAGO_X_OFERTA mpxo
    LEFT JOIN METODOS_PAGO mp ON mp.ID_METODO_PAGO = mpxo.ID_METODO_PAGO
    WHERE mpxo.ID_OFERTA = I_ID_OFERTA
    AND mpxo.FEC_BAJA IS NULL;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
