DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_INFO_ESTABLECIMIENTO`(
	IN I_ID_ESTABLECIMIENTO INT
	)
BEGIN
	SELECT 
		e.ID_ESTABLECIMIENTO AS id_establecimiento,
        e.TX_ESTABLECIMIENTO AS nombre,
        e.TX_DESCRIPCION AS descripcion,
        e.NRO_HABILITACION AS numero_habilitacion,
        e.NRO_TELEFONO AS telefono,
        e.TX_MAIL AS mail,
        d.TX_CALLE AS calle,
        CASE 
            WHEN d.TX_ALTURA = 'S/N' THEN true 
            ELSE false 
        END AS sin_numero,
        d.TX_ALTURA AS numero,
        d.ID_LOCALIDAD AS id_localidad,
        l.TX_LOCALIDAD AS localidad,
        d.ID_DEPARTAMENTO AS id_departamento,
        dp.TX_DEPARTAMENTO AS departamento,
        d.ID_PROVINCIA AS id_provincia,
        p.TX_PROVINCIA AS provincia,
        d.TX_LATITUD AS latitud,
        d.TX_LONGITUD AS longitud
	FROM ESTABLECIMIENTOS e
    LEFT JOIN PRESTADORES pr ON e.ID_PRESTADOR = pr.ID_PRESTADOR
    LEFT JOIN DOMICILIOS d ON e.ID_DOMICILIO = d.ID_DOMICILIO
    LEFT JOIN LOCALIDADES l ON d.ID_LOCALIDAD = l.ID_LOCALIDAD
    LEFT JOIN DEPARTAMENTOS dp ON d.ID_DEPARTAMENTO = dp.ID_DEPARTAMENTO
    LEFT JOIN PROVINCIAS p ON d.ID_PROVINCIA = p.ID_PROVINCIA
    WHERE e.ID_ESTABLECIMIENTO = I_ID_ESTABLECIMIENTO
    AND e.FEC_BAJA is null ;
END ;;
DELIMITER ;
