DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_OFERTAS_GUARDADAS_X_USUARIO`(
    IN I_ID_USUARIO VARCHAR(36) -- CHEQUEAR SI HACE FALTA
)
BEGIN
    -- Primer SELECT: Detalles de las ofertas guardadas por el turista
    SELECT 
        og.ID_OFERTA_GUARDADA AS id_oferta_guardada,
        ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        ot.TX_OFERTA AS nombre_oferta,
        ot.TX_DESCRIPCION AS descripcion_oferta,
        ot.ID_TIPO_OFERTA AS id_tipo_oferta,
        tipo.TX_TIPO_OFERTA AS tipo_oferta,
        ot.ID_SUB_TIPO_OFERTA AS id_sub_tipo_oferta,
        sto.TX_SUB_TIPO_OFERTA AS sub_tipo_oferta
    FROM OFERTAS_GUARDADAS og
    LEFT JOIN OFERTAS_TURISTICAS ot ON og.ID_OFERTA = ot.ID_OFERTA_TURISTICA
    LEFT JOIN TIPOS_DETALLE td ON og.ID_TIPO_DETALLE = td.ID_TIPO_DETALLE
    LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
    LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
    WHERE og.USR_ALTA = I_ID_USUARIO
    AND og.FECHA_BAJA IS NULL
	AND ot.FEC_BAJA IS NULL;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
