CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_OFERTAS_RESERVADAS_X_USUARIO`(
    IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
    -- Primer SELECT: Detalles de las reservas realizadas por el turista
    SELECT 
        r.ID_RESERVA AS id_reserva,
        r.FEC_INICIO AS fecha_inicio,
        r.FEC_FIN AS fecha_fin,
        r.MONTO_FINAL AS monto_final,
        ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        ot.TX_OFERTA AS nombre_oferta,
        ot.TX_DESCRIPCION AS descripcion_oferta,
        ot.ID_TIPO_OFERTA AS id_tipo_oferta,
        tipo.TX_TIPO_OFERTA AS tipo_oferta,
        ot.ID_SUB_TIPO_OFERTA AS id_sub_tipo_oferta,
        sto.TX_SUB_TIPO_OFERTA AS sub_tipo_oferta,
        cer.ID_ESTADO AS id_estado_reserva,
        est.TX_ESTADO AS estado_reserva
    FROM RESERVAS r
    LEFT JOIN OFERTAS_TURISTICAS ot ON r.ID_OFERTA = ot.ID_OFERTA_TURISTICA
    LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
    LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
    LEFT JOIN CAMBIOS_ESTADO_RESERVA cer ON r.ID_RESERVA = cer.ID_RESERVA
    LEFT JOIN ESTADOS est ON cer.ID_ESTADO = est.ID_ESTADO
    WHERE r.USR_ALTA = I_ID_USUARIO
    AND ot.FEC_BAJA IS NULL
    ORDER BY r.FEC_INICIO DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
