/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_OFERTAS_TURISTICAS_X_USUARIO`(
    IN I_ID_USUARIO VARCHAR(36) -- CHEQUEAR SI HACE FALTA
)
BEGIN
    SELECT 
        ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        ot.TX_OFERTA AS nombre,
        ot.TX_DESCRIPCION AS descripcion,
        ot.ID_TIPO_OFERTA AS id_tipo_oferta,
        tipo.TX_TIPO_OFERTA AS tipo_oferta,
        ot.ID_SUB_TIPO_OFERTA AS id_sub_tipo_oferta,
        sto.TX_SUB_TIPO_OFERTA AS sub_tipo_oferta,
        d.TX_CALLE AS calle,
        CASE 
            WHEN d.TX_ALTURA = 'S/N' THEN true 
            ELSE false 
        END AS sin_numero,
        d.TX_ALTURA AS numero,
        d.ID_LOCALIDAD AS id_localidad,
        d.ID_DEPARTAMENTO AS id_departamento,
        d.ID_PROVINCIA AS id_provincia,
        d.TX_LATITUD AS latitud,
        d.TX_LONGITUD AS longitud,
        ot.ID_POLITICA_CANCELACION AS id_politica_cancelacion,
        ot.PLAZO_DIAS_CANCELACION AS plazo_dias_cancelacion,
        ot.BL_SOLICITA_GARANTIA AS bl_solicita_garantia,
        ot.MONTO_GARANTIA AS monto_garantia,
        ot.ID_TIPO_PAGO_ANTICIPADO AS id_tipo_pago_anticipado,
        ot.PORCENTAJE_PAGO_ANTICIPADO AS porcentaje_pago_anticipado,
        ot.MIN_DIAS_ESTADIA AS min_dias_estadia,
        e.ID_ESTADO AS id_estado,
        e.TX_ESTADO AS estado,
        GROUP_CONCAT(DISTINCT td.TX_TIPO_DETALLE) AS tipos_detalle,
        GROUP_CONCAT(DISTINCT td.CANTIDAD) AS cantidades_detalle,
        GROUP_CONCAT(DISTINCT td.CANTIDAD_BAÑOS) AS cantidades_baños,
        GROUP_CONCAT(DISTINCT td.BL_BAÑO_COMPARTIDO) AS baños_compartidos,
        GROUP_CONCAT(DISTINCT td.BL_BAÑO_ADAPTADO) AS baños_adaptados,
        GROUP_CONCAT(DISTINCT cxo.ID_CARACTERISTICA) AS ids_caracteristicas,
        GROUP_CONCAT(DISTINCT mpxo.ID_METODO_PAGO) AS ids_metodos_pago,
        GROUP_CONCAT(DISTINCT oxo.TX_OBSERVACION) AS observaciones_oferta,
        GROUP_CONCAT(DISTINCT CONCAT(pxtd.ID_TIPO_CAMA, ':', pxtd.CANTIDAD_CAMAS)) AS plazas_por_tipo_cama,
        GROUP_CONCAT(DISTINCT CONCAT(txo.ID_TIPO_ENTRADA, ':', txo.MONTO_TARIFA)) AS tarifas_por_tipo_pension
    FROM OFERTAS_TURISTICAS ot
    LEFT JOIN PRESTADORES p ON ot.ID_PRESTADOR = p.ID_PRESTADOR
    LEFT JOIN DOMICILIOS d ON ot.ID_DOMICILIO = d.ID_DOMICILIO
    LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
    LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
    LEFT JOIN TIPOS_DETALLE td ON ot.ID_OFERTA_TURISTICA = td.ID_OFERTA
    LEFT JOIN CARACTERISTICAS_X_OFERTA cxo ON ot.ID_OFERTA_TURISTICA = cxo.ID_OFERTA_TURISTICA
    LEFT JOIN METODOS_PAGO_X_OFERTA mpxo ON ot.ID_OFERTA_TURISTICA = mpxo.ID_OFERTA
    LEFT JOIN OBSERVACIONES_X_OFERTA oxo ON ot.ID_OFERTA_TURISTICA = oxo.ID_OFERTA
    LEFT JOIN PLAZAS_X_TIPO_DETALLE pxtd ON td.ID_TIPO_DETALLE = pxtd.ID_PLAZA_X_TIPO_DETALLE
    LEFT JOIN TARIFAS_X_OFERTA txo ON td.ID_TIPO_DETALLE = txo.ID_TIPO_DETALLE
    LEFT JOIN CAMBIOS_ESTADO_OFERTA ceo ON ot.ID_OFERTA_TURISTICA = ceo.ID_OFERTA
		AND ceo.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_OFERTA WHERE ID_OFERTA = ceo.ID_OFERTA)
	LEFT JOIN ESTADOS e ON ceo.ID_ESTADO = e.ID_ESTADO
    WHERE p.ID_USUARIO = I_ID_USUARIO
    AND ot.FEC_BAJA IS NULL
    GROUP BY ot.ID_OFERTA_TURISTICA,  e.ID_ESTADO;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_OBT_OFERTAS_X_FILTRO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_OBT_OFERTAS_X_FILTRO`(
	IN I_PageNumber         INT,
	IN I_PageSize           INT,
	IN I_ID_TIPO_OFERTA     INT,
	IN I_ID_SUB_TIPO_OFERTA INT,
	IN I_ID_LOCALIDAD       INT,
	IN I_MIN_MONTO          DECIMAL(20, 2),
	IN I_MAX_MONTO          DECIMAL(20, 2),
	IN I_NOCHES_ESTADIA     INT,
	IN I_LATITUD            DECIMAL(10, 6),
	IN I_LONGITUD           DECIMAL(10, 6),
	IN I_RADIO_KM           DECIMAL(10, 2),
	IN I_FEC_DESDE          DATE,
	IN I_FEC_HASTA          DATE,
	IN I_CANTIDAD_PERSONAS  INT
)
BEGIN
    DECLARE OffsetValue INT;

    SET OffsetValue = (I_PageNumber - 1) * I_PageSize;
	SET @V_SQL := '';
    
    IF I_ID_TIPO_OFERTA = 1 THEN
    
		SET @V_SQL := CONCAT(@V_SQL, '
				SELECT 
				OT.ID_OFERTA_TURISTICA AS id_oferta,
				OT.TX_OFERTA AS nombre_oferta,
				OT.TX_DESCRIPCION AS descripcion,
				OT.FEC_ALTA AS fecha_alta,
				OT.FEC_BAJA AS fecha_baja,
				OT.ID_ESTABLECIMIENTO AS id_establecimiento,
				E.TX_ESTABLECIMIENTO AS nombre_establecimiento,
				P.TX_RAZON_SOCIAL AS razon_social_prestador,
				OT.ID_TIPO_OFERTA AS id_tipo_oferta,
				OT.ID_SUB_TIPO_OFERTA AS id_subtipo_oferta,
				ST.TX_SUB_TIPO_OFERTA AS subtipo_oferta,
				OT.MONTO_GARANTIA AS garantia_alojamiento,
				OT.MONTO_PAGO_ANTICIPADO AS pago_anticipado,
				OT.PORCENTAJE_PAGO_ANTICIPADO AS porcentaje_pago_anticipado,
				OT.MIN_DIAS_ESTADIA AS minimo_noches_estadia,
				coalesce(D.TX_CALLE,DEST.TX_CALLE) AS nombre_calle,
				coalesce(D.TX_BARRIO,DEST.TX_BARRIO) AS nombre_barrio,
				coalesce(D.ID_LOCALIDAD,DEST.ID_LOCALIDAD) AS id_localidad,
				coalesce(L.TX_LOCALIDAD,LEST.TX_LOCALIDAD) AS localidad,
				coalesce(D.ID_DEPARTAMENTO,DEST.ID_DEPARTAMENTO) AS id_departamento,
				coalesce(D.ID_PROVINCIA,DEST.ID_PROVINCIA) AS id_provincia,
                coalesce(D.TX_LATITUD,DEST.TX_LATITUD) AS latitud,
                coalesce(D.TX_LONGITUD,DEST.TX_LONGITUD) AS longitud,
				MIN(IXO.TX_RUTA_ARCHIVO) AS ruta_imagen,
				MIN(TXO.MONTO_TARIFA)*', I_NOCHES_ESTADIA, ' AS precios_desde,
			TXO.ID_TIPO_DETALLE AS id_tipo_detalle,
			TD.CANTIDAD_BAÑOS AS cantidad_baños,
			TD.BL_BAÑO_COMPARTIDO AS bl_baño_compartido,
			TD.BL_BAÑO_ADAPTADO AS bl_baño_adaptado,
			FN_OBT_CANT_TIPO_CAMA_X_DETALLE_OFERTA(TD.ID_TIPO_DETALLE) AS camas_cantidad
	   --     SUM(PTD.CANTIDAD_CAMAS) AS cantidad_camas
		FROM OFERTAS_TURISTICAS OT
		LEFT JOIN SUB_TIPO_OFERTA ST ON ST.ID_SUB_TIPO_OFERTA = OT.ID_SUB_TIPO_OFERTA
		-- LEFT JOIN TARIFAS_X_OFERTA TXO ON TXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
		INNER JOIN TARIFAS_X_OFERTA TXO ON TXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
			AND TXO.ID_TARIFA_X_OFERTA = (
			SELECT TXO1.ID_TARIFA_X_OFERTA
			FROM TARIFAS_X_OFERTA TXO1
			WHERE TXO1.ID_OFERTA = OT.ID_OFERTA_TURISTICA
				AND TXO1.FEC_DESDE <= DATE(',QUOTE(I_FEC_DESDE),')
				AND TXO1.FEC_HASTA >= DATE(',QUOTE(I_FEC_HASTA),')
                AND MONTO_TARIFA = (SELECT MIN(MONTO_TARIFA) FROM TARIFAS_X_OFERTA WHERE ID_TARIFA_X_OFERTA = TXO1.ID_TARIFA_X_OFERTA)
            LIMIT 1
		)
		LEFT JOIN TIPOS_DETALLE TD ON TXO.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE
		LEFT JOIN ESTABLECIMIENTOS E ON OT.ID_ESTABLECIMIENTO = E.ID_ESTABLECIMIENTO
		LEFT JOIN PRESTADORES P ON OT.ID_PRESTADOR = P.ID_PRESTADOR
		LEFT JOIN DOMICILIOS D ON OT.ID_DOMICILIO = D.ID_DOMICILIO
		LEFT JOIN LOCALIDADES L ON L.ID_LOCALIDAD = D.ID_LOCALIDAD
			LEFT JOIN DOMICILIOS DEST ON E.ID_DOMICILIO = DEST.ID_DOMICILIO
			LEFT JOIN LOCALIDADES LEST ON LEST.ID_LOCALIDAD = DEST.ID_LOCALIDAD
		LEFT JOIN PLAZAS_X_TIPO_DETALLE PTD ON PTD.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE
		LEFT JOIN TIPOS_CAMA TC ON TC.ID_TIPO_CAMA = PTD.ID_TIPO_CAMA
		LEFT JOIN IMAGENES_X_OFERTA IXO ON IXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
		LEFT JOIN CAMBIOS_ESTADO_OFERTA CEO ON CEO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
			AND CEO.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_OFERTA WHERE ID_OFERTA = OT.ID_OFERTA_TURISTICA)
		WHERE 
			CEO.ID_ESTADO = 4
			AND PTD.FEC_BAJA IS NULL
            AND OT.ID_TIPO_OFERTA = 1 
		');
		
		IF I_ID_SUB_TIPO_OFERTA IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND OT.ID_SUB_TIPO_OFERTA = ', I_ID_SUB_TIPO_OFERTA);
		END IF;
	  
		IF I_ID_LOCALIDAD IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND coalesce(D.ID_LOCALIDAD,DEST.ID_LOCALIDAD) = ', I_ID_LOCALIDAD);
		END IF;

		IF I_MIN_MONTO IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.MONTO_TARIFA >= ', I_MIN_MONTO);
		END IF;

		IF I_MAX_MONTO IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.MONTO_TARIFA <= ', I_MAX_MONTO);
		END IF;

		IF I_FEC_DESDE IS NOT NULL AND I_FEC_HASTA IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.FEC_DESDE <= DATE(', QUOTE(I_FEC_HASTA), ') AND TXO.FEC_HASTA >= DATE(', QUOTE(I_FEC_DESDE),') ');
		END IF;
		
		IF I_NOCHES_ESTADIA IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND OT.MIN_DIAS_ESTADIA <= ', I_NOCHES_ESTADIA);
		END IF;

	--      --   SET @V_SQL := CONCAT(@V_SQL, ' GROUP BY TXO.ID_TIPO_DETALLE, OT.ID_OFERTA_TURISTICA HAVING SUM(PTD.CANTIDAD_CAMAS) >= ', I_CANTIDAD_PERSONAS);
	  --   ELSE
			SET @V_SQL := CONCAT(@V_SQL, ' GROUP BY OT.ID_OFERTA_TURISTICA, TXO.ID_TIPO_DETALLE ');
	   --  END IF;

		IF I_LATITUD IS NOT NULL AND I_LONGITUD IS NOT NULL AND I_RADIO_KM IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' HAVING distancia_km <= ', I_RADIO_KM);
		END IF;

		SET @V_SQL := CONCAT(@V_SQL, ' ORDER BY OT.FEC_ALTA DESC LIMIT ', I_PageSize, ' OFFSET ', OffsetValue);
		
		-- select @V_SQL from dual;
	
    ELSEIF I_ID_TIPO_OFERTA = 2
    THEN
		
        SET @V_SQL := CONCAT(@V_SQL, '
				SELECT 
				OT.ID_OFERTA_TURISTICA AS id_oferta,
				OT.TX_OFERTA AS nombre_oferta,
				OT.TX_DESCRIPCION AS descripcion,
				OT.FEC_ALTA AS fecha_alta,
				OT.FEC_BAJA AS fecha_baja,
				OT.ID_ESTABLECIMIENTO AS id_establecimiento,
				E.TX_ESTABLECIMIENTO AS nombre_establecimiento,
				P.TX_RAZON_SOCIAL AS razon_social_prestador,
				OT.ID_TIPO_OFERTA AS id_tipo_oferta,
				OT.ID_SUB_TIPO_OFERTA AS id_subtipo_oferta,
				ST.TX_SUB_TIPO_OFERTA AS subtipo_oferta,
				OT.MONTO_GARANTIA AS garantia_alojamiento,
				OT.MONTO_PAGO_ANTICIPADO AS pago_anticipado,
				OT.PORCENTAJE_PAGO_ANTICIPADO AS porcentaje_pago_anticipado,
				coalesce(D.TX_CALLE,DEST.TX_CALLE) AS nombre_calle,
				coalesce(D.TX_BARRIO,DEST.TX_BARRIO) AS nombre_barrio,
				coalesce(D.ID_LOCALIDAD,DEST.ID_LOCALIDAD) AS id_localidad,
				coalesce(L.TX_LOCALIDAD,LEST.TX_LOCALIDAD) AS localidad,
				coalesce(D.ID_DEPARTAMENTO,DEST.ID_DEPARTAMENTO) AS id_departamento,
				coalesce(D.ID_PROVINCIA,DEST.ID_PROVINCIA) AS id_provincia,
                coalesce(D.TX_LATITUD,DEST.TX_LATITUD) AS latitud,
                coalesce(D.TX_LONGITUD,DEST.TX_LONGITUD) AS longitud,
				MIN(IXO.TX_RUTA_ARCHIVO) AS ruta_imagen,
				MIN(TXO.MONTO_TARIFA) *', I_CANTIDAD_PERSONAS, ' AS precios_desde
		FROM OFERTAS_TURISTICAS OT
		LEFT JOIN SUB_TIPO_OFERTA ST ON ST.ID_SUB_TIPO_OFERTA = OT.ID_SUB_TIPO_OFERTA
		-- LEFT JOIN TARIFAS_X_OFERTA TXO ON TXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
		LEFT JOIN TARIFAS_X_OFERTA TXO ON TXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
			AND TXO.ID_TARIFA_X_OFERTA = (
			SELECT TXO1.ID_TARIFA_X_OFERTA
			FROM TARIFAS_X_OFERTA TXO1
			WHERE TXO1.ID_OFERTA = OT.ID_OFERTA_TURISTICA
				AND TXO1.FEC_DESDE <= DATE(',QUOTE(I_FEC_HASTA),')
				AND TXO1.FEC_HASTA >= DATE(',QUOTE(I_FEC_DESDE),')
                AND MONTO_TARIFA = (SELECT MIN(MONTO_TARIFA) FROM TARIFAS_X_OFERTA WHERE ID_TARIFA_X_OFERTA = TXO1.ID_TARIFA_X_OFERTA)
            LIMIT 1
		)
		LEFT JOIN TIPOS_DETALLE TD ON TXO.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE
		LEFT JOIN ESTABLECIMIENTOS E ON OT.ID_ESTABLECIMIENTO = E.ID_ESTABLECIMIENTO
		LEFT JOIN PRESTADORES P ON OT.ID_PRESTADOR = P.ID_PRESTADOR
		LEFT JOIN DOMICILIOS D ON OT.ID_DOMICILIO = D.ID_DOMICILIO
		LEFT JOIN LOCALIDADES L ON L.ID_LOCALIDAD = D.ID_LOCALIDAD
			LEFT JOIN DOMICILIOS DEST ON E.ID_DOMICILIO = DEST.ID_DOMICILIO
			LEFT JOIN LOCALIDADES LEST ON LEST.ID_LOCALIDAD = DEST.ID_LOCALIDAD
		LEFT JOIN PLAZAS_X_TIPO_DETALLE PTD ON PTD.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE
		LEFT JOIN TIPOS_CAMA TC ON TC.ID_TIPO_CAMA = PTD.ID_TIPO_CAMA
		LEFT JOIN IMAGENES_X_OFERTA IXO ON IXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
		LEFT JOIN CAMBIOS_ESTADO_OFERTA CEO ON CEO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
			AND CEO.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_OFERTA WHERE ID_OFERTA = OT.ID_OFERTA_TURISTICA)
		WHERE 
			CEO.ID_ESTADO = 4
			AND PTD.FEC_BAJA IS NULL 
            AND OT.ID_TIPO_OFERTA = 2
		');
		
		IF I_ID_TIPO_OFERTA IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND OT.ID_TIPO_OFERTA = ', I_ID_TIPO_OFERTA);
		END IF;

		IF I_ID_SUB_TIPO_OFERTA IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND OT.ID_SUB_TIPO_OFERTA = ', I_ID_SUB_TIPO_OFERTA);
		END IF;

	  
		IF I_ID_LOCALIDAD IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND coalesce(D.ID_LOCALIDAD,DEST.ID_LOCALIDAD) = ', I_ID_LOCALIDAD);
		END IF;

		IF I_MIN_MONTO IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.MONTO_TARIFA >= ', I_MIN_MONTO);
		END IF;

		IF I_MAX_MONTO IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.MONTO_TARIFA <= ', I_MAX_MONTO);
		END IF;

		IF I_FEC_DESDE IS NOT NULL AND I_FEC_HASTA IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.FEC_DESDE <= DATE(', QUOTE(I_FEC_HASTA), ') AND TXO.FEC_HASTA >= DATE(', QUOTE(I_FEC_DESDE),') ');
		END IF;

	--      --   SET @V_SQL := CONCAT(@V_SQL, ' GROUP BY TXO.ID_TIPO_DETALLE, OT.ID_OFERTA_TURISTICA HAVING SUM(PTD.CANTIDAD_CAMAS) >= ', I_CANTIDAD_PERSONAS);
	  --   ELSE
			SET @V_SQL := CONCAT(@V_SQL, ' GROUP BY OT.ID_OFERTA_TURISTICA, TXO.ID_TIPO_DETALLE ');
	   --  END IF;

		IF I_LATITUD IS NOT NULL AND I_LONGITUD IS NOT NULL AND I_RADIO_KM IS NOT NULL THEN
			SET @V_SQL := CONCAT(@V_SQL, ' HAVING distancia_km <= ', I_RADIO_KM);
		END IF;

		SET @V_SQL := CONCAT(@V_SQL, ' ORDER BY OT.FEC_ALTA DESC LIMIT ', I_PageSize, ' OFFSET ', OffsetValue);
		
	-- 	select @V_SQL from dual;
	
    END IF;
    
    PREPARE CONSULTA FROM @V_SQL;
    EXECUTE CONSULTA;
    DEALLOCATE PREPARE CONSULTA;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_OBT_OFERTAS_X_FILTRO_MEJORADO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_OBT_OFERTAS_X_FILTRO_MEJORADO`(
    IN I_PageNumber INT,
    IN I_PageSize INT,
    IN I_ID_TIPO_OFERTA INT,
    IN I_ID_SUB_TIPO_OFERTA INT,
    IN I_ID_LOCALIDAD INT,
    IN I_MIN_MONTO DECIMAL(20,2),
    IN I_MAX_MONTO DECIMAL(20,2),
    IN I_NOCHES_ESTADIA INT,
    IN I_LATITUD DECIMAL(10, 6),
    IN I_LONGITUD DECIMAL(10, 6),
    IN I_RADIO_KM DECIMAL(10, 2),
    IN I_FEC_DESDE DATE,
    IN I_FEC_HASTA DATE,
    IN I_CANTIDAD_PERSONAS INT
)
BEGIN
    DECLARE OffsetValue INT;
    DECLARE V_SQL LONGTEXT;

    SET I_PageNumber = IFNULL(I_PageNumber, 1);
    IF I_PageNumber < 1 THEN
        SET I_PageNumber = 1;
    END IF;
    
    SET OffsetValue = (I_PageNumber - 1) * I_PageSize;
    SET @V_SQL := '';
    
    IF I_ID_TIPO_OFERTA = 1 THEN
    
        SET @V_SQL := CONCAT('
            SELECT 
                OT.ID_OFERTA_TURISTICA AS id_oferta,
                OT.TX_OFERTA AS nombre_oferta,
                OT.TX_DESCRIPCION AS descripcion,
                OT.FEC_ALTA AS fecha_alta,
                OT.FEC_BAJA AS fecha_baja,
                OT.ID_ESTABLECIMIENTO AS id_establecimiento,
                E.TX_ESTABLECIMIENTO AS nombre_establecimiento,
                P.TX_RAZON_SOCIAL AS razon_social_prestador,
                OT.ID_TIPO_OFERTA AS id_tipo_oferta,
                OT.ID_SUB_TIPO_OFERTA AS id_subtipo_oferta,
                ST.TX_SUB_TIPO_OFERTA AS subtipo_oferta,
                OT.MONTO_GARANTIA AS garantia_alojamiento,
                OT.MONTO_PAGO_ANTICIPADO AS pago_anticipado,
                OT.PORCENTAJE_PAGO_ANTICIPADO AS porcentaje_pago_anticipado,
                OT.MIN_DIAS_ESTADIA AS minimo_noches_estadia,
                COALESCE(D.TX_CALLE, DEST.TX_CALLE) AS nombre_calle,
                COALESCE(D.TX_BARRIO, DEST.TX_BARRIO) AS nombre_barrio,
                COALESCE(D.ID_LOCALIDAD, DEST.ID_LOCALIDAD) AS id_localidad,
                COALESCE(L.TX_LOCALIDAD, LEST.TX_LOCALIDAD) AS localidad,
                COALESCE(D.ID_DEPARTAMENTO, DEST.ID_DEPARTAMENTO) AS id_departamento,
                COALESCE(D.ID_PROVINCIA, DEST.ID_PROVINCIA) AS id_provincia,
                COALESCE(D.TX_LATITUD, DEST.TX_LATITUD) AS latitud,
                COALESCE(D.TX_LONGITUD, DEST.TX_LONGITUD) AS longitud,
                MIN(IXO.TX_RUTA_ARCHIVO) AS ruta_imagen,
                (MIN(TXO.MONTO_TARIFA) * ', IFNULL(I_NOCHES_ESTADIA, 1), ') AS precios_desde,
                TXO.ID_TIPO_DETALLE AS id_tipo_detalle,
                TD.CANTIDAD_BAÑOS AS cantidad_baños,
                TD.BL_BAÑO_COMPARTIDO AS bl_baño_compartido,
                TD.BL_BAÑO_ADAPTADO AS bl_baño_adaptado,
                FN_OBT_CANT_TIPO_CAMA_X_DETALLE_OFERTA(TD.ID_TIPO_DETALLE) AS camas_cantidad');
        
        -- Agregar cálculo de distancia solo si se proporcionan coordenadas
        IF I_LATITUD IS NOT NULL AND I_LONGITUD IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ',
                (6371 * ACOS(
                    COS(RADIANS(', I_LATITUD, ')) * 
                    COS(RADIANS(COALESCE(D.TX_LATITUD, DEST.TX_LATITUD))) * 
                    COS(RADIANS(COALESCE(D.TX_LONGITUD, DEST.TX_LONGITUD)) - RADIANS(', I_LONGITUD, ')) + 
                    SIN(RADIANS(', I_LATITUD, ')) * 
                    SIN(RADIANS(COALESCE(D.TX_LATITUD, DEST.TX_LATITUD)))
                )) AS distancia_km');
        END IF;
        
        SET @V_SQL := CONCAT(@V_SQL, '
            FROM OFERTAS_TURISTICAS OT
            LEFT JOIN SUB_TIPO_OFERTA ST ON ST.ID_SUB_TIPO_OFERTA = OT.ID_SUB_TIPO_OFERTA
            INNER JOIN TARIFAS_X_OFERTA TXO ON TXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA');
        
        -- Filtro de fechas solo si se proporcionan
        IF I_FEC_DESDE IS NOT NULL AND I_FEC_HASTA IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, '
                AND TXO.FEC_DESDE <= DATE(', QUOTE(I_FEC_HASTA), ')
                AND TXO.FEC_HASTA >= DATE(', QUOTE(I_FEC_DESDE), ')');
        END IF;
        
        SET @V_SQL := CONCAT(@V_SQL, '
            LEFT JOIN TIPOS_DETALLE TD ON TXO.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE
            LEFT JOIN ESTABLECIMIENTOS E ON OT.ID_ESTABLECIMIENTO = E.ID_ESTABLECIMIENTO
            LEFT JOIN PRESTADORES P ON OT.ID_PRESTADOR = P.ID_PRESTADOR
            LEFT JOIN DOMICILIOS D ON OT.ID_DOMICILIO = D.ID_DOMICILIO
            LEFT JOIN LOCALIDADES L ON L.ID_LOCALIDAD = D.ID_LOCALIDAD
            LEFT JOIN DOMICILIOS DEST ON E.ID_DOMICILIO = DEST.ID_DOMICILIO
            LEFT JOIN LOCALIDADES LEST ON LEST.ID_LOCALIDAD = DEST.ID_LOCALIDAD
            LEFT JOIN PLAZAS_X_TIPO_DETALLE PTD ON PTD.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE AND PTD.FEC_BAJA IS NULL
            LEFT JOIN TIPOS_CAMA TC ON TC.ID_TIPO_CAMA = PTD.ID_TIPO_CAMA
            LEFT JOIN IMAGENES_X_OFERTA IXO ON IXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
            LEFT JOIN CAMBIOS_ESTADO_OFERTA CEO ON CEO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
                AND CEO.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_OFERTA WHERE ID_OFERTA = OT.ID_OFERTA_TURISTICA)
            WHERE 
                CEO.ID_ESTADO = 4
                AND OT.ID_TIPO_OFERTA = 1 
        ');
        
        IF I_ID_SUB_TIPO_OFERTA IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND OT.ID_SUB_TIPO_OFERTA = ', I_ID_SUB_TIPO_OFERTA);
        END IF;
      
        IF I_ID_LOCALIDAD IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND COALESCE(D.ID_LOCALIDAD, DEST.ID_LOCALIDAD) = ', I_ID_LOCALIDAD);
        END IF;

        IF I_MIN_MONTO IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.MONTO_TARIFA >= ', I_MIN_MONTO);
        END IF;

        IF I_MAX_MONTO IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.MONTO_TARIFA <= ', I_MAX_MONTO);
        END IF;
        
        IF I_NOCHES_ESTADIA IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND OT.MIN_DIAS_ESTADIA <= ', I_NOCHES_ESTADIA);
        END IF;

        -- Filtro de cantidad de personas
        IF I_CANTIDAD_PERSONAS IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND TD.ID_TIPO_DETALLE IN (
                SELECT PTD2.ID_TIPO_DETALLE 
                FROM PLAZAS_X_TIPO_DETALLE PTD2 
                WHERE PTD2.FEC_BAJA IS NULL
                GROUP BY PTD2.ID_TIPO_DETALLE 
                HAVING SUM(PTD2.CANTIDAD_CAMAS) >= ', I_CANTIDAD_PERSONAS, '
            )');
        END IF;

        SET @V_SQL := CONCAT(@V_SQL, ' GROUP BY OT.ID_OFERTA_TURISTICA, TXO.ID_TIPO_DETALLE ');

        IF I_LATITUD IS NOT NULL AND I_LONGITUD IS NOT NULL AND I_RADIO_KM IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' HAVING distancia_km <= ', I_RADIO_KM);
        END IF;

        SET @V_SQL := CONCAT(@V_SQL, ' ORDER BY OT.FEC_ALTA DESC LIMIT ', I_PageSize, ' OFFSET ', OffsetValue);
        
    ELSEIF I_ID_TIPO_OFERTA = 2 THEN
        
        SET @V_SQL := CONCAT('
            SELECT 
                OT.ID_OFERTA_TURISTICA AS id_oferta,
                OT.TX_OFERTA AS nombre_oferta,
                OT.TX_DESCRIPCION AS descripcion,
                OT.FEC_ALTA AS fecha_alta,
                OT.FEC_BAJA AS fecha_baja,
                OT.ID_ESTABLECIMIENTO AS id_establecimiento,
                E.TX_ESTABLECIMIENTO AS nombre_establecimiento,
                P.TX_RAZON_SOCIAL AS razon_social_prestador,
                OT.ID_TIPO_OFERTA AS id_tipo_oferta,
                OT.ID_SUB_TIPO_OFERTA AS id_subtipo_oferta,
                ST.TX_SUB_TIPO_OFERTA AS subtipo_oferta,
                OT.MONTO_GARANTIA AS garantia_alojamiento,
                OT.MONTO_PAGO_ANTICIPADO AS pago_anticipado,
                OT.PORCENTAJE_PAGO_ANTICIPADO AS porcentaje_pago_anticipado,
                OT.MIN_DIAS_ESTADIA AS minimo_noches_estadia,
                COALESCE(D.TX_CALLE, DEST.TX_CALLE) AS nombre_calle,
                COALESCE(D.TX_BARRIO, DEST.TX_BARRIO) AS nombre_barrio,
                COALESCE(D.ID_LOCALIDAD, DEST.ID_LOCALIDAD) AS id_localidad,
                COALESCE(L.TX_LOCALIDAD, LEST.TX_LOCALIDAD) AS localidad,
                COALESCE(D.ID_DEPARTAMENTO, DEST.ID_DEPARTAMENTO) AS id_departamento,
                COALESCE(D.ID_PROVINCIA, DEST.ID_PROVINCIA) AS id_provincia,
                COALESCE(D.TX_LATITUD, DEST.TX_LATITUD) AS latitud,
                COALESCE(D.TX_LONGITUD, DEST.TX_LONGITUD) AS longitud,
                MIN(IXO.TX_RUTA_ARCHIVO) AS ruta_imagen,
                MIN(TXO.MONTO_TARIFA) AS precios_desde,
                TXO.ID_TIPO_DETALLE AS id_tipo_detalle');
        
        -- Agregar cálculo de distancia para tipo 2
        IF I_LATITUD IS NOT NULL AND I_LONGITUD IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ',
                (6371 * ACOS(
                    COS(RADIANS(', I_LATITUD, ')) * 
                    COS(RADIANS(COALESCE(D.TX_LATITUD, DEST.TX_LATITUD))) * 
                    COS(RADIANS(COALESCE(D.TX_LONGITUD, DEST.TX_LONGITUD)) - RADIANS(', I_LONGITUD, ')) + 
                    SIN(RADIANS(', I_LATITUD, ')) * 
                    SIN(RADIANS(COALESCE(D.TX_LATITUD, DEST.TX_LATITUD)))
                )) AS distancia_km');
        END IF;
        
        SET @V_SQL := CONCAT(@V_SQL, '
            FROM OFERTAS_TURISTICAS OT
            LEFT JOIN SUB_TIPO_OFERTA ST ON ST.ID_SUB_TIPO_OFERTA = OT.ID_SUB_TIPO_OFERTA
            INNER JOIN TARIFAS_X_OFERTA TXO ON TXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA');
        
        -- Filtro de fechas solo si se proporcionan
        IF I_FEC_DESDE IS NOT NULL AND I_FEC_HASTA IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, '
                AND TXO.FEC_DESDE <= DATE(', QUOTE(I_FEC_HASTA), ')
                AND TXO.FEC_HASTA >= DATE(', QUOTE(I_FEC_DESDE), ')');
        END IF;
        
        SET @V_SQL := CONCAT(@V_SQL, '
            LEFT JOIN TIPOS_DETALLE TD ON TXO.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE
            LEFT JOIN ESTABLECIMIENTOS E ON OT.ID_ESTABLECIMIENTO = E.ID_ESTABLECIMIENTO
            LEFT JOIN PRESTADORES P ON OT.ID_PRESTADOR = P.ID_PRESTADOR
            LEFT JOIN DOMICILIOS D ON OT.ID_DOMICILIO = D.ID_DOMICILIO
            LEFT JOIN LOCALIDADES L ON L.ID_LOCALIDAD = D.ID_LOCALIDAD
            LEFT JOIN DOMICILIOS DEST ON E.ID_DOMICILIO = DEST.ID_DOMICILIO
            LEFT JOIN LOCALIDADES LEST ON LEST.ID_LOCALIDAD = DEST.ID_LOCALIDAD
            LEFT JOIN PLAZAS_X_TIPO_DETALLE PTD ON PTD.ID_TIPO_DETALLE = TD.ID_TIPO_DETALLE AND PTD.FEC_BAJA IS NULL
            LEFT JOIN TIPOS_CAMA TC ON TC.ID_TIPO_CAMA = PTD.ID_TIPO_CAMA
            LEFT JOIN IMAGENES_X_OFERTA IXO ON IXO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
            LEFT JOIN CAMBIOS_ESTADO_OFERTA CEO ON CEO.ID_OFERTA = OT.ID_OFERTA_TURISTICA
                AND CEO.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_OFERTA WHERE ID_OFERTA = OT.ID_OFERTA_TURISTICA)
            WHERE 
                CEO.ID_ESTADO = 4
                AND OT.ID_TIPO_OFERTA = 2
        ');
        
        IF I_ID_SUB_TIPO_OFERTA IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND OT.ID_SUB_TIPO_OFERTA = ', I_ID_SUB_TIPO_OFERTA);
        END IF;
      
        IF I_ID_LOCALIDAD IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND COALESCE(D.ID_LOCALIDAD, DEST.ID_LOCALIDAD) = ', I_ID_LOCALIDAD);
        END IF;

        IF I_MIN_MONTO IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.MONTO_TARIFA >= ', I_MIN_MONTO);
        END IF;

        IF I_MAX_MONTO IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND TXO.MONTO_TARIFA <= ', I_MAX_MONTO);
        END IF;

        -- Filtro de cantidad de personas para tipo 2
        IF I_CANTIDAD_PERSONAS IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' AND TD.ID_TIPO_DETALLE IN (
                SELECT PTD2.ID_TIPO_DETALLE 
                FROM PLAZAS_X_TIPO_DETALLE PTD2 
                WHERE PTD2.FEC_BAJA IS NULL
                GROUP BY PTD2.ID_TIPO_DETALLE 
                HAVING SUM(PTD2.CANTIDAD_CAMAS) >= ', I_CANTIDAD_PERSONAS, '
            )');
        END IF;

        SET @V_SQL := CONCAT(@V_SQL, ' GROUP BY OT.ID_OFERTA_TURISTICA, TXO.ID_TIPO_DETALLE ');

        IF I_LATITUD IS NOT NULL AND I_LONGITUD IS NOT NULL AND I_RADIO_KM IS NOT NULL THEN
            SET @V_SQL := CONCAT(@V_SQL, ' HAVING distancia_km <= ', I_RADIO_KM);
        END IF;

        SET @V_SQL := CONCAT(@V_SQL, ' ORDER BY OT.FEC_ALTA DESC LIMIT ', I_PageSize, ' OFFSET ', OffsetValue);
        
    END IF;
    
    SELECT @V_SQL;

    PREPARE CONSULTA FROM @V_SQL;
    EXECUTE CONSULTA;
    DEALLOCATE PREPARE CONSULTA;
END ;;
DELIMITER ;
