CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_PERFILES_X_USUARIO`(
	IN I_ID_USUARIO VARCHAR(36)
    )
BEGIN
    DECLARE V_ERROR VARCHAR (5000);
	DECLARE V_ERROR_SQL VARCHAR(5000);
	DECLARE V_DESCRIPCION VARCHAR(500);
    DECLARE DONE INT DEFAULT FALSE;
    
	DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET DONE = TRUE;

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
		GET CURRENT DIAGNOSTICS CONDITION 1
		V_ERROR_SQL = MESSAGE_TEXT;
		IF (V_ERROR IS NULL ) THEN
			SET V_ERROR = V_ERROR_SQL;
		END IF;
        ROLLBACK;

		SELECT	'error'			AS resultado,
				V_ERROR			AS descripcion;
	END;
    
    SELECT 
		PXU.ID_PERFIL_X_USUARIO AS id_perfil_x_usuario,
        PXU.ID_PERFIL AS id_perfil,
        P.TX_PERFIL AS nombre_perfil
    FROM PERFILES_X_USUARIO PXU
    LEFT JOIN PERFILES P ON PXU.ID_PERFIL = P.ID_PERFIL
    WHERE ID_USUARIO = I_ID_USUARIO
    AND FEC_BAJA IS NULL
    AND USR_BAJA IS NULL;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
