/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_PROMEDIO_INGRESOS_X_RESERVA_X_PRESTADOR`(
    IN FEC_DESDE DATETIME, 
    IN FEC_HASTA DATETIME,
    IN ID_USUARIO VARCHAR(36)
)
BEGIN
	DECLARE V_ID_PRESTADOR VARCHAR(36);
    
	SELECT ID_PRESTADOR
    INTO V_ID_PRESTADOR
    FROM PRESTADORES
    WHERE ID_USUARIO = ID_USUARIO;
    
    -- Calcular el promedio de ingresos por proveedor en el rango de fechas
    SELECT 
        P.TX_RAZON_SOCIAL,
        ROUND(AVG(R.MONTO_FINAL), 2) AS promedio_ingreso_proveedor
    FROM RESERVAS R
    LEFT JOIN CAMBIOS_ESTADO_RESERVA CER ON R.ID_RESERVA = CER.ID_RESERVA
		AND CER.ID_ESTADO = 8
    LEFT JOIN OFERTAS_TURISTICAS O ON R.ID_OFERTA = o.ID_OFERTA_TURISTICA
    LEFT JOIN PRESTADORES P ON O.ID_PRESTADOR = P.ID_PRESTADOR
   --  LEFT JOIN PAGOS 																	-- ACA ESTA LO QUE NOS IMPORTA
    WHERE R.fecha_reserva BETWEEN FEC_DESDE AND FEC_HASTA
    AND P.ID_PRESTADOR = V_ID_PRESTADOR
    GROUP BY P.ID_PRESTADOR;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
