CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_REPORTE_RESERVAS_PRESTADOR`(
    IN I_ID_USUARIO VARCHAR(36),
    IN I_FEC_DESDE DATE,
    IN I_FEC_HASTA DATE
)
BEGIN
	DECLARE V_ID_PRESTADOR VARCHAR(36);
    
	SELECT ID_PRESTADOR
    INTO V_ID_PRESTADOR
    FROM PRESTADORES
    WHERE ID_USUARIO = I_ID_USUARIO;
    
    SELECT 
        OT.ID_OFERTA_TURISTICA AS ID_Oferta,
        OT.TX_OFERTA AS Nombre_Oferta,
        OT.ID_TIPO_OFERTA AS Tipo_Oferta,
        OT.ID_SUB_TIPO_OFERTA AS Sub_Tipo_Oferta,
        COUNT(R.ID_RESERVA) AS Cantidad_Reservas,
        IFNULL(SUM(R.MONTO_FINAL), 0) AS Monto_Total_Reservas
    FROM 
        OFERTAS_TURISTICAS OT
    INNER JOIN 
        RESERVAS R ON OT.ID_OFERTA_TURISTICA = R.ID_OFERTA
    WHERE OT.ID_PRESTADOR = V_ID_PRESTADOR
	AND R.FEC_INICIO BETWEEN I_FEC_DESDE AND I_FEC_HASTA
	AND OT.FEC_BAJA IS NULL  -- Incluye solo ofertas activas
    GROUP BY 
        OT.ID_OFERTA_TURISTICA, OT.TX_OFERTA, OT.ID_TIPO_OFERTA, OT.ID_SUB_TIPO_OFERTA
    ORDER BY 
        Cantidad_Reservas DESC;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_OBT_RESERVAS_PRESTADOR` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_RESERVAS_PRESTADOR`(
    IN I_ID_USUARIO VARCHAR(36),
    IN I_ID_TIPO_OFERTA INT
)
BEGIN
	-- select de id PRESTADOR
    DECLARE V_ID_PRESTADOR VARCHAR(36);
    
	SELECT ID_PRESTADOR
    INTO V_ID_PRESTADOR
    FROM PRESTADORES
    WHERE ID_USUARIO = I_ID_USUARIO;
    
	-- Primer SELECT: Info de las reservas realizadas en ofertas del prestador
    SELECT ID_ESTADO AS id_estado,
		TX_ESTADO AS nombre_estado
    FROM ESTADOS
    WHERE ID_ESTADO IN (7,8);
    
    -- Segundo SELECT: Info de las reservas realizadas en ofertas del prestador
    SELECT 
        r.ID_RESERVA AS id_reserva,
        r.FEC_INICIO AS fecha_inicio,
        r.FEC_FIN AS fecha_fin,
        r.MONTO_FINAL AS monto_final,
        ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        ot.TX_OFERTA AS nombre_oferta,
        ot.TX_DESCRIPCION AS descripcion_oferta,
        ot.ID_TIPO_OFERTA AS id_tipo_oferta,
        tipo.TX_TIPO_OFERTA AS tipo_oferta,
        ot.ID_SUB_TIPO_OFERTA AS id_sub_tipo_oferta,
        sto.TX_SUB_TIPO_OFERTA AS sub_tipo_oferta,
        cer.ID_ESTADO AS id_estado_reserva,
        est.TX_ESTADO AS estado_reserva,
        t.ID_TURISTA AS id_turista,
		u.TX_NOMBRE AS nombre_turista,
        u.TX_APELLIDO AS apellido_turista
    FROM RESERVAS r
	LEFT JOIN OFERTAS_TURISTICAS ot ON r.ID_OFERTA = ot.ID_OFERTA_TURISTICA
    LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
    LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
    LEFT JOIN CAMBIOS_ESTADO_RESERVA cer ON r.ID_RESERVA = cer.ID_RESERVA
		AND cer.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_RESERVA WHERE ID_RESERVA = cer.ID_RESERVA)
    LEFT JOIN ESTADOS est ON cer.ID_ESTADO = est.ID_ESTADO
    LEFT JOIN TURISTAS t ON r.ID_TURISTA = t.ID_TURISTA  -- Join para obtener el nombre y apellido del turista
    LEFT JOIN USUARIOS u ON t.ID_USUARIO = u.ID_USUARIO
    WHERE ot.ID_PRESTADOR = V_ID_PRESTADOR
    AND ot.ID_TIPO_OFERTA = I_ID_TIPO_OFERTA
    AND ot.FEC_BAJA IS NULL
    AND cer.ID_ESTADO IN (7,8)
    ORDER BY r.FEC_INICIO DESC;

    -- Tercer SELECT: Info de los detalles de las reservas realizadas por el turista
    SELECT 
        r.ID_RESERVA AS id_reserva,
        ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        ot.TX_OFERTA AS nombre_oferta,
        dr.ID_TIPO_DETALLE AS id_tipo_detalle,
        td.TX_TIPO_DETALLE AS nombre_tipo_detalle,
        dr.ID_TIPO_ENTRADA AS id_tipo_entrada,
        texo.TX_TIPO_ENTRADA AS nombre_tipo_entrada,
        dr.CANTIDAD AS cantidad,
        dr.PRECIO_UNITARIO AS precio_unitario,
        dr.MONTO_TOTAL AS monto_total_detalle
    FROM RESERVAS r
    LEFT JOIN DETALLE_RESERVA dr ON dr.ID_RESERVA = r.ID_RESERVA
	LEFT JOIN OFERTAS_TURISTICAS ot ON r.ID_OFERTA = ot.ID_OFERTA_TURISTICA
    LEFT JOIN TIPOS_DETALLE td ON dr.ID_TIPO_DETALLE = td.ID_TIPO_DETALLE
    LEFT JOIN TIPOS_ENTRADA_X_OFERTA texo ON texo.ID_TIPO_ENTRADA = dr.ID_TIPO_ENTRADA
    LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
    LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
    LEFT JOIN CAMBIOS_ESTADO_RESERVA cer ON r.ID_RESERVA = cer.ID_RESERVA
		AND cer.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_RESERVA WHERE ID_RESERVA = cer.ID_RESERVA)
    LEFT JOIN ESTADOS est ON cer.ID_ESTADO = est.ID_ESTADO
	WHERE ot.ID_PRESTADOR = V_ID_PRESTADOR
	AND ot.ID_TIPO_OFERTA = I_ID_TIPO_OFERTA
    AND ot.FEC_BAJA IS NULL
    AND cer.ID_ESTADO IN (7,8)
    ORDER BY r.FEC_INICIO DESC;
    
     -- Cuarto SELECT: Listado de turistas que cumplen con el filtro de estado
    SELECT DISTINCT
        t.ID_TURISTA AS id_turista,
        u.TX_NOMBRE AS nombre_turista,
        u.TX_APELLIDO AS apellido_turista
    FROM TURISTAS t
    INNER JOIN USUARIOS u ON t.ID_USUARIO = u.ID_USUARIO
    INNER JOIN RESERVAS r ON t.ID_TURISTA = r.ID_TURISTA
    INNER JOIN OFERTAS_TURISTICAS ot ON r.ID_OFERTA = ot.ID_OFERTA_TURISTICA
    INNER JOIN CAMBIOS_ESTADO_RESERVA cer ON r.ID_RESERVA = cer.ID_RESERVA
        AND cer.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_RESERVA WHERE ID_RESERVA = r.ID_RESERVA)
    WHERE ot.ID_PRESTADOR = V_ID_PRESTADOR
	AND ot.ID_TIPO_OFERTA = I_ID_TIPO_OFERTA
    AND ot.FEC_BAJA IS NULL
    AND cer.ID_ESTADO IN (7,8);

    -- Quinto SELECT: Listado de ofertas turísticas con el filtro de estado
    SELECT DISTINCT
        ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        ot.TX_OFERTA AS nombre_oferta
    FROM OFERTAS_TURISTICAS ot
    INNER JOIN RESERVAS r ON ot.ID_OFERTA_TURISTICA = r.ID_OFERTA
    INNER JOIN CAMBIOS_ESTADO_RESERVA cer ON r.ID_RESERVA = cer.ID_RESERVA
        AND cer.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_RESERVA WHERE ID_RESERVA = r.ID_RESERVA)
    WHERE ot.ID_PRESTADOR = V_ID_PRESTADOR
	AND ot.ID_TIPO_OFERTA = I_ID_TIPO_OFERTA
    AND ot.FEC_BAJA IS NULL
    AND cer.ID_ESTADO IN (7,8);
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SP_OBT_RESERVAS_TURISTA` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_RESERVAS_TURISTA`(
    IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
    -- Primer SELECT: Info de las reservas realizadas por el turista
    SELECT 
        r.ID_RESERVA AS id_reserva,
        r.FEC_INICIO AS fecha_inicio,
        r.FEC_FIN AS fecha_fin,
        r.MONTO_FINAL AS monto_final,
        ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        ot.TX_OFERTA AS nombre_oferta,
        ot.TX_DESCRIPCION AS descripcion_oferta,
        ot.ID_TIPO_OFERTA AS id_tipo_oferta,
        tipo.TX_TIPO_OFERTA AS tipo_oferta,
        ot.ID_SUB_TIPO_OFERTA AS id_sub_tipo_oferta,
        sto.TX_SUB_TIPO_OFERTA AS sub_tipo_oferta,
        cer.ID_ESTADO AS id_estado_reserva,
        est.TX_ESTADO AS estado_reserva
    FROM RESERVAS r
	LEFT JOIN OFERTAS_TURISTICAS ot ON r.ID_OFERTA = ot.ID_OFERTA_TURISTICA
    LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
    LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
    LEFT JOIN CAMBIOS_ESTADO_RESERVA cer ON r.ID_RESERVA = cer.ID_RESERVA
		AND cer.ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_RESERVA WHERE ID_RESERVA = cer.ID_RESERVA)
    LEFT JOIN ESTADOS est ON cer.ID_ESTADO = est.ID_ESTADO
    WHERE r.USR_ALTA = I_ID_USUARIO
    AND ot.FEC_BAJA IS NULL
    ORDER BY r.FEC_INICIO DESC;

    -- Segundo SELECT: Info de los detalles de las reservas realizadas por el turista
    SELECT 
        r.ID_RESERVA AS id_reserva,
        ot.ID_OFERTA_TURISTICA AS id_oferta_turistica,
        dr.ID_TIPO_DETALLE AS id_tipo_detalle,
        td.TX_TIPO_DETALLE AS nombre_tipo_detalle,
        dr.ID_TIPO_ENTRADA AS id_tipo_entrada,
        texo.TX_TIPO_ENTRADA AS nombre_tipo_entrada,
        dr.CANTIDAD AS cantidad_detalle_entrada,
        dr.PRECIO_UNITARIO AS precio_unitario,
        dr.MONTO_TOTAL AS monto_total_detalle
    FROM RESERVAS r
    LEFT JOIN DETALLE_RESERVA dr ON dr.ID_RESERVA = r.ID_RESERVA
	LEFT JOIN OFERTAS_TURISTICAS ot ON r.ID_OFERTA = ot.ID_OFERTA_TURISTICA
    LEFT JOIN TIPOS_DETALLE td ON dr.ID_TIPO_DETALLE = td.ID_TIPO_DETALLE
    LEFT JOIN TIPOS_ENTRADA_X_OFERTA texo ON texo.ID_TIPO_ENTRADA = dr.ID_TIPO_ENTRADA
    LEFT JOIN TIPOS_OFERTA tipo ON ot.ID_TIPO_OFERTA = tipo.ID_TIPO_OFERTA
    LEFT JOIN SUB_TIPO_OFERTA sto ON ot.ID_SUB_TIPO_OFERTA = sto.ID_SUB_TIPO_OFERTA
    LEFT JOIN CAMBIOS_ESTADO_RESERVA cer ON r.ID_RESERVA = cer.ID_RESERVA
    LEFT JOIN ESTADOS est ON cer.ID_ESTADO = est.ID_ESTADO
    WHERE r.USR_ALTA = I_ID_USUARIO
    AND ot.FEC_BAJA IS NULL
    ORDER BY r.FEC_INICIO DESC;
END ;;
DELIMITER ;
