DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_TARIFA_X_TIPO_DETALLE`(
    IN I_ID_TIPO_DETALLE VARCHAR(36)
)
BEGIN
    SELECT 
        TXTD.ID_TARIFA_X_TIPO_DETALLE AS id_tarifa,
        TD.ID_TIPO_DETALLE AS id_tipo_detalle,
        TD.TX_TIPO_DETALLE AS tipo_detalle,
        TXTD.ID_TIPO_PENSION AS id_tipo_pension,
        TP.TX_TIPO_PENSION AS tipo_pension,
        TXTD.MONTO_TARIFA AS monto_tarifa,
        TXTD.FEC_DESDE AS fecha_desde,
        TXTD.FEC_HASTA AS fecha_hasta
    FROM TIPOS_DETALLE TD
    INNER JOIN TARIFAS_X_OFERTA TXO ON TD.ID_TIPO_DETALLE = TXO.ID_TIPO_DETALLE
    LEFT JOIN TIPOS_PENSION TP ON TP.ID_TIPO_PENSION = TXO.ID_TIPO_PENSION
    WHERE TD.ID_TIPO_DETALLE = I_ID_TIPO_DETALLE
    AND TD.FEC_BAJA IS NULL
    AND TXO.FEC_BAJA IS NULL; -- Solo tarifas activas
END ;;
