CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_TIPOS_ENTRADA_X_OFERTA`(
    IN I_ID_OFERTA VARCHAR(36)
)
BEGIN
    SELECT
        TEO.ID_TIPO_ENTRADA AS id_tipo_entrada,
        TEO.TX_TIPO_ENTRADA AS nombre_tipo_entrada,
        TEO.TX_DESCRIPCION AS descripcion_tipo_entrada,
        TXO.ID_TARIFA_X_OFERTA AS id_tarifa,
        TXO.MONTO_TARIFA AS monto_tarifa,
        TXO.FEC_DESDE AS fed_desde,
        TXO.FEC_HASTA AS fec_hasta,
        TXO.BL_GRATIS AS bl_gratis
        
    FROM TIPOS_ENTRADA_X_OFERTA TEO
    LEFT JOIN TARIFAS_X_OFERTA TXO ON TEO.ID_TIPO_ENTRADA = TXO.ID_TIPO_ENTRADA
    WHERE TEO.FEC_BAJA IS NULL
    AND TXO.FEC_BAJA IS NULL
    AND TEO.ID_OFERTA = I_ID_OFERTA;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
