CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_URL_X_USUARIO`(
	IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
	SELECT DISTINCT 	U.ID_USUARIO 				AS id_usuario,
						URL.TX_URL 					AS url,
						M.TX_METODO					AS metodo,
						PXU.ID_PERFIL		 		AS id_perfil
	FROM USUARIOS U
	INNER JOIN PERFILES_X_USUARIO PXU ON U.ID_USUARIO = PXU.ID_USUARIO
	INNER JOIN PERFILES P ON PXU.ID_PERFIL = P.ID_PERFIL
	INNER JOIN FUNCIONALIDADES_X_PERFIL FXP ON P.ID_PERFIL = FXP.ID_PERFIL
	INNER JOIN FUNCIONALIDADES F ON FXP.ID_FUNCIONALIDAD = F.ID_FUNCIONALIDAD
	INNER JOIN URLS_X_FUNCIONALIDAD UXF ON F.ID_FUNCIONALIDAD = UXF.ID_FUNCIONALIDAD
	INNER JOIN URLS URL ON UXF.ID_URL = URL.ID_URL
	INNER JOIN METODOS M ON URL.ID_METODO = M.ID_METODO
	WHERE PXU.FEC_BAJA IS NULL
	AND U.FEC_BAJA IS NULL
	AND U.ID_USUARIO = I_ID_USUARIO;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
