CREATE DEFINER=`root`@`%` PROCEDURE `SP_OBT_USUARIO_X_EMAIL`(
    IN I_TX_MAIL VARCHAR(100)
)
BEGIN
    DECLARE V_COUNT_USUARIO INT;
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_DESCRIPCION VARCHAR(500);

    SELECT COUNT(*)
    INTO V_COUNT_USUARIO
    FROM USUARIOS
    WHERE TX_MAIL = TRIM(I_TX_MAIL)
    AND FEC_BAJA IS NULL;

    IF V_COUNT_USUARIO = 1 THEN
        SELECT 
            U.ID_USUARIO        AS id_usuario,
            U.TX_CONTRASENIA    AS contraseña,
            FN_VALIDAR_PERFILES_USUARIO(U.ID_USUARIO) AS cantidad_perfiles,
            U.BL_VERIFICADO AS verificado,
            PXU.ID_PERFIL AS perfil
            -- P.TX_PERFIL AS nombre_perfil
        FROM USUARIOS U
        LEFT JOIN PERFILES_X_USUARIO PXU ON U.ID_USUARIO = PXU.ID_USUARIO
        LEFT JOIN PERFILES P ON PXU.ID_PERFIL = P.ID_PERFIL
        WHERE U.TX_MAIL = TRIM(I_TX_MAIL)
        AND U.FEC_BAJA IS NULL
        AND PXU.FEC_BAJA IS NULL;

    ELSE
        SET V_ERROR := 'Error al obtener usuario. ';
        SELECT	'error'			AS resultado,
				V_ERROR			AS descripcion;
    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
