CREATE DEFINER=`root`@`%` PROCEDURE `SP_REGISTRAR_CODIGO_MP`(
    IN I_ID_USUARIO VARCHAR(36),
    IN I_CODE_RANDOM VARCHAR(50),
    IN I_FECHA_CREACION BIGINT
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_EXISTE INT DEFAULT 0;

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Verificar si ya existe un registro con el mismo I_ID_USUARIO
    SELECT COUNT(*) INTO V_EXISTE
    FROM DATOS_MP_USUARIO
    WHERE ID_USUARIO = I_ID_USUARIO;

    IF V_EXISTE > 0 THEN
        -- Si el usuario ya existe, realizar un update
        UPDATE DATOS_MP_USUARIO
        SET TX_CODIGO_RANDOM = I_CODE_RANDOM,
            FEC_ALTA = I_FECHA_CREACION
        WHERE ID_USUARIO = I_ID_USUARIO;

        SELECT 'ok' AS resultado, 'Código actualizado exitosamente' AS descripcion;
    ELSE
        -- Si no existe, insertar un nuevo registro
        INSERT INTO DATOS_MP_USUARIO (
            ID_USUARIO,
            TX_CODIGO_RANDOM,
            FEC_ALTA
        ) VALUES (
            I_ID_USUARIO,
            I_CODE_RANDOM,
            I_FECHA_CREACION
        );

        SELECT 'ok' AS resultado, 'Código registrado exitosamente' AS descripcion;
    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
