CREATE DEFINER=`root`@`%` PROCEDURE `SP_REGISTRAR_DATOS_RESERVA`(
    IN I_ID_RESERVA VARCHAR(36),
    IN I_PREFERENCE_ID VARCHAR(100),
    IN I_EXTERNAL_REFERENCE VARCHAR(36),
    IN I_INIT_POINT VARCHAR(500),
    IN I_FEC_EXPIRACION_DESDE DATETIME,
    IN I_FEC_EXPIRACION_HASTA DATETIME,
    IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);

    -- Manejo de excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    START TRANSACTION;
    
    -- Insertar los datos en la tabla DATOS_MP_RESERVA
    INSERT INTO DATOS_MP_RESERVA (
        ID_DATOS_MP,
        ID_USUARIO,
        ID_RESERVA,
        FEC_ALTA,
        FEC_EXPIRACION_HASTA,
        EXTERNAL_REFERENCE,
        PREFERENCE_ID,
        INIT_POINT
    )
    VALUES (
        UUID(), -- Genera un nuevo UUID para ID_DATOS_MP
        I_ID_USUARIO,
        I_ID_RESERVA,
        I_FEC_EXPIRACION_DESDE, -- Fecha actual de alta
        I_FEC_EXPIRACION_HASTA,
        I_EXTERNAL_REFERENCE,
        I_PREFERENCE_ID,
        I_INIT_POINT
    );

    COMMIT;

    -- Respuesta de éxito
    SELECT 'ok' AS resultado, 'Datos de reserva registrados exitosamente' AS descripcion;
END ;;
DELIMITER ;
