CREATE DEFINER=`root`@`%` PROCEDURE `SP_REGISTRAR_DEPARTAMENTO`(
    IN I_DEPARTAMENTO VARCHAR(100),
    IN I_PROVINCIA VARCHAR(100)
)
BEGIN
    DECLARE V_ID_PROVINCIA INT;
    DECLARE V_ID_DEPARTAMENTO INT;
    
    -- Obtener ID de la provincia
    SELECT ID_PROVINCIA INTO V_ID_PROVINCIA
    FROM PROVINCIAS
    WHERE TX_PROVINCIA = I_PROVINCIA;
    
    IF V_ID_PROVINCIA IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La provincia especificada no existe.';
    ELSE
        -- Verificar si el departamento ya existe
        SELECT ID_DEPARTAMENTO INTO V_ID_DEPARTAMENTO
        FROM DEPARTAMENTOS
        WHERE TX_DEPARTAMENTO = I_DEPARTAMENTO AND ID_PROVINCIA = V_ID_PROVINCIA;
        
        IF V_ID_DEPARTAMENTO IS NULL THEN
            -- Si no existe, insertar nuevo departamento
            INSERT INTO DEPARTAMENTOS (TX_DEPARTAMENTO, ID_PROVINCIA)
            VALUES (I_DEPARTAMENTO, V_ID_PROVINCIA);
            
            SET V_ID_DEPARTAMENTO = LAST_INSERT_ID();
        END IF;
        
        -- Devolver el ID del departamento
        SELECT V_ID_DEPARTAMENTO AS ID_DEPARTAMENTO;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
