CREATE DEFINER=`root`@`%` PROCEDURE `SP_REGISTRAR_OFERTA`(
    IN I_ID_OFERTA_TURISTICA VARCHAR(36),
    IN I_ID_USUARIO VARCHAR(36)
)
BEGIN
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);
    DECLARE V_ID_ESTADO_ACTUAL INT;
    DECLARE V_USR_ALTA VARCHAR(36);

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Obtener el usuario que creó la oferta desde la tabla OFERTAS_TURISTICAS
    SELECT USR_ALTA
    INTO V_USR_ALTA
    FROM OFERTAS_TURISTICAS
    WHERE ID_OFERTA_TURISTICA = I_ID_OFERTA_TURISTICA;

    -- Validar que el usuario que realiza la publicación es el creador de la oferta
    IF V_USR_ALTA != I_ID_USUARIO THEN
        SET V_ERROR = 'Error: Usuario no autorizado para publicar esta oferta.';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;

    -- Obtener el último estado de la oferta a partir del registro con el mayor ID_CAMBIO_ESTADO
    SELECT ID_ESTADO
    INTO V_ID_ESTADO_ACTUAL
    FROM CAMBIOS_ESTADO_OFERTA
    WHERE ID_OFERTA = I_ID_OFERTA_TURISTICA
    AND ID_CAMBIO_ESTADO = (SELECT MAX(ID_CAMBIO_ESTADO) FROM CAMBIOS_ESTADO_OFERTA WHERE ID_OFERTA = I_ID_OFERTA_TURISTICA);

    -- Validar que la oferta no está ya en el estado "Publicada" 
    IF V_ID_ESTADO_ACTUAL != 2 THEN

        INSERT INTO CAMBIOS_ESTADO_OFERTA (ID_OFERTA, ID_ESTADO, FEC_ALTA, USR_ALTA)
        VALUES (I_ID_OFERTA_TURISTICA, 2, NOW(), I_ID_USUARIO);

        SELECT 'ok' AS resultado, 'Oferta registrada exitosamente' AS descripcion;

    ELSE
        -- Error: La oferta ya está en el estado "Publicada"
        SET V_ERROR = 'Error: La oferta ya está en el estado "Registrada".';
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = V_ERROR;
    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
