CREATE DEFINER=`root`@`%` PROCEDURE `SP_REGISTRAR_PAGO_RESERVA`(
	IN I_PAYMENT_ID bigint ,
	IN I_EXTERNAL_REFERENCE varchar(36) ,
	IN I_MONEY_REALEASE_DATE datetime ,
	IN I_TRANSACTION_AMOUNT decimal(20,2) ,
	IN I_ESTADO varchar(45) ,
    IN I_DESCRIPCION VARCHAR(100)
)
BEGIN
    DECLARE V_ID_RESERVA VARCHAR(36);
    DECLARE V_ID_USUARIO VARCHAR(36);
    DECLARE V_ERROR VARCHAR(5000);
    DECLARE V_ERROR_SQL VARCHAR(5000);

    -- Handler para capturar excepciones
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        GET CURRENT DIAGNOSTICS CONDITION 1 V_ERROR_SQL = MESSAGE_TEXT;
        SET V_ERROR = V_ERROR_SQL;
        ROLLBACK;
        SELECT 'error' AS resultado, V_ERROR AS descripcion;
    END;

    -- Buscar la reserva correspondiente
    SELECT ID_RESERVA, ID_USUARIO
    INTO V_ID_RESERVA, V_ID_USUARIO
    FROM DATOS_MP_RESERVA
    WHERE EXTERNAL_REFERENCE = I_EXTERNAL_REFERENCE;

    -- Verificar si se encuentra la reserva
    IF V_ID_RESERVA IS NULL THEN
        -- Si no se encuentra la reserva, se termina el procedimiento y se muestra el error
        SELECT 'error' AS resultado, 'No se encontró la reserva con los datos proporcionados' AS descripcion;
    ELSE
        -- Insertar el pago en la tabla PAGOS_X_RESERVA
        INSERT INTO PAGOS_X_RESERVA (
            ID_PAGO_RESERVA, 
            PAYMENT_ID,
            ID_RESERVA, 
            EXTERNAL_REFERENCE,
            MONEY_REALEASE_DATE,
			TRANSACTION_AMOUNT,
			ESTADO,
            DESCRIPCION
        )
        VALUES (UUID(),
			I_PAYMENT_ID,
            V_ID_RESERVA,
			I_EXTERNAL_REFERENCE,
			I_MONEY_REALEASE_DATE,
			I_TRANSACTION_AMOUNT,
			I_ESTADO,
            I_DESCRIPCION);

        -- Actualizar el estado de la reserva a "pagada"
        INSERT INTO CAMBIOS_ESTADO_RESERVA (ID_RESERVA,ID_ESTADO,FEC_ALTA,USR_ALTA)
        VALUES (V_ID_RESERVA, 8, NOW(), V_ID_USUARIO);
   
        SELECT 
        UTUR.TX_NOMBRE AS nombre_turista,
        UTUR.TX_APELLIDO AS apellido_turista,
        UPRES.TX_NOMBRE AS nombre_prestador,
        UPRES.TX_APELLIDO AS apellido_prestador,
        UTUR.TX_MAIL AS mail_turista,
        UPRES.TX_MAIL AS mail_prestador,
        R.MONTO_FINAL AS monto_final,
        R.FEC_INICIO AS fecha_inicio,
        R.FEC_FIN AS fecha_fin,
        OT.TX_OFERTA AS nombre_oferta
        
		FROM RESERVAS R
        LEFT JOIN OFERTAS_TURISTICAS OT ON R.ID_OFERTA = OT.ID_OFERTA_TURISTICA
        LEFT JOIN PRESTADORES PRES ON PRES.ID_PRESTADOR = OT.ID_PRESTADOR
        LEFT JOIN USUARIOS UPRES ON UPRES.ID_USUARIO = PRES.ID_USUARIO
        LEFT JOIN TURISTAS TUR ON R.ID_TURISTA = TUR.ID_TURISTA
        LEFT JOIN USUARIOS UTUR ON UTUR.ID_USUARIO = TUR.ID_USUARIO
		WHERE ID_RESERVA = V_ID_RESERVA;        

        SELECT 'ok' AS resultado, 'Pago registrado y estado actualizado exitosamente' AS descripcion;
        
             
        COMMIT;
        -- Si todo salió bien, mostrar el resultado
        
    END IF;
END ;;
DELIMITER ;
