CREATE DEFINER=`root`@`%` PROCEDURE `SP_REGISTRAR_PRESTADOR`(
	IN I_ID_USUARIO VARCHAR(36),
	IN I_TX_NOMBRE varchar(50),
	IN I_TX_APELLIDO varchar(50) ,
	IN I_FEC_NACIMIENTO datetime ,
    IN I_NRO_DOCUMENTO_IDENTIDAD VARCHAR(100),
	IN I_ID_TIPO_DOCUMENTO_IDENTIDAD INT,
	IN I_NRO_TELEFONO VARCHAR(45),
	IN I_ID_LOCALIDAD_ORIGEN INT,
    IN I_ID_DEPARTAMENTO INT,
    IN I_ID_PROVINCIA INT,
    IN I_TX_CUIT VARCHAR(45),
    IN I_TX_RAZON_SOCIAL VARCHAR(100)
)
BEGIN
	DECLARE V_ID_PRESTADOR VARCHAR(36);
    DECLARE V_EXISTE_PRESTADOR INT;
	DECLARE V_ID_DOMICILIO INT;

	DECLARE V_ERROR VARCHAR (5000);
	DECLARE V_ERROR_SQL VARCHAR(5000);
	DECLARE V_DESCRIPCION VARCHAR(500);
    DECLARE DONE INT DEFAULT FALSE;
    
	DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET DONE = TRUE;

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
		GET CURRENT DIAGNOSTICS CONDITION 1
		V_ERROR_SQL = MESSAGE_TEXT;
		IF (V_ERROR IS NULL ) THEN
			SET V_ERROR = V_ERROR_SQL;
		END IF;
        ROLLBACK;

		SELECT	'error'			AS resultado,
				V_ERROR			AS descripcion,
				V_ID_PRESTADOR	AS id_prestador;
	END;
    
	IF I_ID_USUARIO IS NOT NULL THEN
		
        SELECT COUNT(*)
		INTO V_EXISTE_PRESTADOR
		FROM PRESTADORES
		WHERE ID_USUARIO = I_ID_USUARIO;
        
        IF V_EXISTE_PRESTADOR = 0
        THEN
			SET V_ID_PRESTADOR = UUID();
			
            INSERT INTO DOMICILIOS(
            ID_LOCALIDAD,
            ID_DEPARTAMENTO,
            ID_PROVINCIA,
            ID_PAIS
            )
            VALUES (
            I_ID_LOCALIDAD_ORIGEN,
            I_ID_DEPARTAMENTO,
            I_ID_PROVINCIA,
            1); -- Argentina
            SELECT LAST_INSERT_ID() INTO V_ID_DOMICILIO;
            
			INSERT INTO PRESTADORES(
            ID_PRESTADOR,
			ID_USUARIO,
            TX_CUIT,
            TX_RAZON_SOCIAL,
            FEC_ALTA)
			VALUES (
            V_ID_PRESTADOR,
			I_ID_USUARIO,
            I_TX_CUIT,
            I_TX_RAZON_SOCIAL,
            NOW());
			
            INSERT INTO PERFILES_X_USUARIO(
            ID_USUARIO,
            ID_PERFIL,
            FEC_ALTA,
            USR_ALTA
            )
            VALUES (
            I_ID_USUARIO,
            2, -- perfil prestador
            now(),
            I_ID_USUARIO
            );
            
           UPDATE USUARIOS
            SET TX_NOMBRE = I_TX_NOMBRE,
				TX_APELLIDO = I_TX_APELLIDO,
				FEC_NACIMIENTO = I_FEC_NACIMIENTO,
                ID_DOMICILIO = V_ID_DOMICILIO,
                NRO_DOCUMENTO_IDENTIDAD = I_NRO_DOCUMENTO_IDENTIDAD,
				ID_TIPO_DOCUMENTO_IDENTIDAD = I_ID_TIPO_DOCUMENTO_IDENTIDAD,
                NRO_TELEFONO = I_NRO_TELEFONO
            WHERE ID_USUARIO = I_ID_USUARIO;
            
            SELECT	'ok' 				AS resultado,
				V_DESCRIPCION		AS descripcion,
				V_ID_PRESTADOR		AS id_prestador;
                
        ELSE
			SET V_ERROR := 'Error, este usuario ya es un prestador. ';
			SIGNAL SQLSTATE '45000';
		END IF;
				
	END IF;
END ;;
DELIMITER ;
