CREATE DEFINER=`root`@`%` PROCEDURE `SP_VERIFICAR_CUENTA`(
	IN I_ID_USUARIO VARCHAR(100),
    IN I_NRO_VERIFICACION VARCHAR(8)
)
BEGIN
	DECLARE V_NRO_VERIFICACION VARCHAR(8);
    DECLARE V_NRO_INTENTOS INT;
	DECLARE V_ERROR VARCHAR (5000);
	DECLARE V_ERROR_SQL VARCHAR(5000);
	DECLARE V_DESCRIPCION VARCHAR(500);
    DECLARE DONE INT DEFAULT FALSE;
    
	DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET DONE = TRUE;

	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	BEGIN
		GET CURRENT DIAGNOSTICS CONDITION 1
		V_ERROR_SQL = MESSAGE_TEXT;
		IF (V_ERROR IS NULL ) THEN
			SET V_ERROR = V_ERROR_SQL;
		END IF;
        ROLLBACK;

		SELECT	'error'			AS resultado,
				V_ERROR			AS descripcion,
                V_NRO_INTENTOS AS nro_intentos;
	END;
	
    IF I_NRO_VERIFICACION IS NOT NULL
    AND I_ID_USUARIO IS NOT NULL
    THEN
    
		SELECT NRO_VERIFICACION, NRO_INTENTOS
		INTO V_NRO_VERIFICACION, V_NRO_INTENTOS
		FROM USUARIOS
		WHERE ID_USUARIO = I_ID_USUARIO
		AND BL_VERIFICADO = 0;
		
        UPDATE USUARIOS
        SET NRO_INTENTOS = NRO_INTENTOS + 1
        WHERE ID_USUARIO = I_ID_USUARIO;
        
		IF TRIM(V_NRO_VERIFICACION) = TRIM(I_NRO_VERIFICACION)
		THEN
			UPDATE USUARIOS
			SET BL_VERIFICADO = 1,
				USR_MODIF = I_ID_USUARIO,
				FEC_MODIF = NOW()
			WHERE ID_USUARIO = I_ID_USUARIO;
		
			SELECT	'ok' 				AS resultado,
					V_DESCRIPCION		AS descripcion,
					V_NRO_INTENTOS AS nro_intentos;

		ELSE
			SET V_ERROR := 'Error al verificar usuario. El código ingresado no es correcto.';
            
            SELECT NRO_INTENTOS
            INTO V_NRO_INTENTOS
            FROM USUARIOS
            WHERE ID_USUARIO = I_ID_USUARIO;
			
            SIGNAL SQLSTATE '45000';
		END IF;
	END IF;
END ;;
DELIMITER ;
